// Retra GBA core - common definitions.
#pragma once

#include <cstdint>
#include <cstddef>
#include <cstring>

namespace retra {

using u8 = uint8_t;
using u16 = uint16_t;
using u32 = uint32_t;
using u64 = uint64_t;
using s8 = int8_t;
using s16 = int16_t;
using s32 = int32_t;
using s64 = int64_t;

#if defined(__GNUC__)
#define RETRA_INLINE inline __attribute__((always_inline))
#define RETRA_NOINLINE __attribute__((noinline))
#define RETRA_LIKELY(x) __builtin_expect(!!(x), 1)
#define RETRA_UNLIKELY(x) __builtin_expect(!!(x), 0)
#else
#define RETRA_INLINE inline
#define RETRA_NOINLINE
#define RETRA_LIKELY(x) (x)
#define RETRA_UNLIKELY(x) (x)
#endif

// Little-endian host assumed (x86, arm64 Android). Unaligned-safe loads.
template <typename T>
RETRA_INLINE T loadLE(const u8* p) {
    T v;
    std::memcpy(&v, p, sizeof(T));
    return v;
}
template <typename T>
RETRA_INLINE void storeLE(u8* p, T v) {
    std::memcpy(p, &v, sizeof(T));
}

RETRA_INLINE u32 ror32(u32 v, u32 s) {
    s &= 31;
    return s ? (v >> s) | (v << (32 - s)) : v;
}

constexpr u32 kCyclesPerLine = 1232;
constexpr u32 kLinesPerFrame = 228;
constexpr u32 kCyclesPerFrame = kCyclesPerLine * kLinesPerFrame;  // 280896
constexpr u32 kCpuClock = 16777216;
constexpr u32 kSampleRate = 32768;
constexpr u32 kCyclesPerSample = kCpuClock / kSampleRate;  // 512

}  // namespace retra

// Retra GBA core - ARM7TDMI interpreter.
#pragma once

#include "common.h"

namespace retra {

class Gba;
class StateWriter;
class StateReader;

enum CpuMode : u32 {
    MODE_USR = 0x10,
    MODE_FIQ = 0x11,
    MODE_IRQ = 0x12,
    MODE_SVC = 0x13,
    MODE_ABT = 0x17,
    MODE_UND = 0x1B,
    MODE_SYS = 0x1F,
};

// Trap opcode used by the replacement BIOS to call into the HLE implementation:
// ARM "permanently undefined" space 0xE7F000F0 | (n & 0xF) | ((n >> 4) << 8).
constexpr u32 kHleTrapMask = 0xFFF000F0;
constexpr u32 kHleTrapBase = 0xE7F000F0;

class Cpu {
public:
    explicit Cpu(Gba* gba) : g(gba) {}

    void reset();
    // Execute until the scheduler's next event (or halted).
    void run();

    // Register file. r[15] = address of current instruction + 8 (ARM) / + 4 (THUMB)
    // while executing; between instructions it is next instruction + 8 / + 4.
    u32 r[16] = {};
    // Flags kept unpacked for speed (each 0 or 1).
    u32 fN = 0, fZ = 0, fC = 0, fV = 0;
    u32 mode = MODE_SYS;
    bool thumb = false;
    bool irqDisable = true;  // CPSR.I
    bool fiqDisable = true;  // CPSR.F
    u32 spsr = 0;            // SPSR of current mode (0 in usr/sys)

    // Banked storage (index via bankIndex()).
    u32 bankR13[6] = {}, bankR14[6] = {}, bankSpsr[6] = {};
    u32 bankFiq[5] = {}, bankUsr[5] = {};  // r8-r12

    bool halted = false;
    bool irqLine = false;  // set by Gba when (IE & IF) && IME

    u32 cpsr() const {
        return (fN << 31) | (fZ << 30) | (fC << 29) | (fV << 28) | (irqDisable ? 0x80 : 0) |
               (fiqDisable ? 0x40 : 0) | (thumb ? 0x20 : 0) | mode;
    }
    void setCpsr(u32 v);  // full write including mode switch
    void setFlags(u32 v) {
        fN = v >> 31;
        fZ = (v >> 30) & 1;
        fC = (v >> 29) & 1;
        fV = (v >> 28) & 1;
    }
    void switchMode(u32 newMode);
    bool hasSpsr() const { return mode != MODE_USR && mode != MODE_SYS; }

    void branchTo(u32 addr);       // jump; pipeline refill accounted
    void raiseIrq();
    void raiseSwi();
    void raiseUndefined();

    // Open-bus value (what the pipeline last fetched).
    u32 openBus();

    void serialize(StateWriter& w) const;
    void deserialize(StateReader& rd);

    Gba* g;

    // --- execution helpers used by the instruction handlers
    void stepArm();
    void stepThumb();
    bool condPassed(u32 cond) const;

    // Barrel shifter helpers
    template <bool SETC>
    RETRA_INLINE u32 shiftImm(u32 type, u32 v, u32 amt, u32& carry) const;
    template <bool SETC>
    RETRA_INLINE u32 shiftReg(u32 type, u32 v, u32 amt, u32& carry) const;

    RETRA_INLINE void setNZ(u32 v) {
        fN = v >> 31;
        fZ = v == 0;
    }
    RETRA_INLINE u32 addFlags(u32 a, u32 b) {
        u32 res = a + b;
        fN = res >> 31;
        fZ = res == 0;
        fC = res < a;
        fV = ((~(a ^ b) & (a ^ res)) >> 31);
        return res;
    }
    RETRA_INLINE u32 adcFlags(u32 a, u32 b, u32 c) {
        u64 res64 = (u64)a + b + c;
        u32 res = (u32)res64;
        fN = res >> 31;
        fZ = res == 0;
        fC = (u32)(res64 >> 32);
        fV = ((~(a ^ b) & (a ^ res)) >> 31);
        return res;
    }
    RETRA_INLINE u32 subFlags(u32 a, u32 b) {
        u32 res = a - b;
        fN = res >> 31;
        fZ = res == 0;
        fC = a >= b;
        fV = (((a ^ b) & (a ^ res)) >> 31);
        return res;
    }
    RETRA_INLINE u32 sbcFlags(u32 a, u32 b, u32 c) {
        // a - b - !c
        u32 nc = c ^ 1;
        u32 res = a - b - nc;
        fN = res >> 31;
        fZ = res == 0;
        fC = (u64)a >= (u64)b + nc;
        fV = (((a ^ b) & (a ^ res)) >> 31);
        return res;
    }

    // Multiply internal cycles from multiplier operand.
    static RETRA_INLINE u32 mulCycles(u32 rs, bool signedMode) {
        if (signedMode) {
            if ((rs & 0xFFFFFF00) == 0 || (rs & 0xFFFFFF00) == 0xFFFFFF00) return 1;
            if ((rs & 0xFFFF0000) == 0 || (rs & 0xFFFF0000) == 0xFFFF0000) return 2;
            if ((rs & 0xFF000000) == 0 || (rs & 0xFF000000) == 0xFF000000) return 3;
            return 4;
        }
        if ((rs & 0xFFFFFF00) == 0) return 1;
        if ((rs & 0xFFFF0000) == 0) return 2;
        if ((rs & 0xFF000000) == 0) return 3;
        return 4;
    }

    void idle(u32 n);  // internal cycles

private:
    static int bankIndex(u32 m);
};

}  // namespace retra

// Retra GBA core - tiny event scheduler (fixed event slots, linear min scan).
#pragma once

#include "common.h"

namespace retra {

enum EventId : int {
    EV_HBLANK = 0,    // H-draw ends (HBlank flag/IRQ/DMA, render line)
    EV_LINE_END,      // line ends, VCOUNT++
    EV_TIMER0,
    EV_TIMER1,
    EV_TIMER2,
    EV_TIMER3,
    EV_APU_SAMPLE,    // produce one output sample
    EV_STOP,          // run loop exit request (frame end)
    EV_COUNT
};

constexpr u64 kNever = ~0ull;

struct Scheduler {
    u64 now = 0;
    u64 next = kNever;
    u64 when[EV_COUNT];

    Scheduler() { clear(); }
    void clear() {
        for (auto& w : when) w = kNever;
        next = kNever;
        now = 0;
    }
    RETRA_INLINE void schedule(int ev, u64 t) {
        when[ev] = t;
        if (t < next) next = t;
    }
    void cancel(int ev) {
        when[ev] = kNever;
        recompute();
    }
    void recompute() {
        u64 m = kNever;
        for (u64 w : when) m = w < m ? w : m;
        next = m;
    }
};

