struct Envelope {
    u32 initVol = 0, dirUp = 0, period = 0;
    u32 vol = 0, timer = 0;
    void load(u16 reg) {
        period = (reg >> 8) & 7;
        dirUp = (reg >> 11) & 1;
        initVol = (reg >> 12) & 15;
    }
    bool dacOn() const { return initVol != 0 || dirUp; }
    void trigger() {
        vol = initVol;
        timer = period ? period : 8;
    }
    void clock() {
        if (!period) return;
        if (--timer == 0) {
            timer = period;
            if (dirUp && vol < 15) vol++;
            else if (!dirUp && vol > 0) vol--;
        }
    }
};

