// Retra GBA core - inline fast paths of the system bus. Include after gba.h.
#pragma once

#include "gba.h"

namespace retra {

template <typename T>
constexpr int busWidthIndex() {
    return sizeof(T) == 1 ? 0 : (sizeof(T) == 2 ? 1 : 2);
}

template <typename T>
RETRA_INLINE T Bus::read(u32 addr, bool seq) {
    u32 region = addr >> 24;
    if (RETRA_UNLIKELY(region > 15)) {
        g->sched.now += 1;
        return readSlow<T>(addr);
    }
    g->sched.now += timing[busWidthIndex<T>()][seq][region];
    const u32 a = addr & ~(u32)(sizeof(T) - 1);
    switch (region) {
        case 0x2: return loadLE<T>(&ewram[a & 0x3FFFF]);
        case 0x3: return loadLE<T>(&iwram[a & 0x7FFF]);
        case 0x8:
        case 0x9:
        case 0xA:
        case 0xB:
        case 0xC: return loadLE<T>(&rom[a & 0x1FFFFFF]);
        default: return readSlow<T>(addr);
    }
}

template <typename T>
RETRA_INLINE void Bus::write(u32 addr, T value, bool seq) {
    u32 region = addr >> 24;
    if (RETRA_UNLIKELY(region > 15)) {
        g->sched.now += 1;
        return;
    }
    g->sched.now += timing[busWidthIndex<T>()][seq][region];
    const u32 a = addr & ~(u32)(sizeof(T) - 1);
    switch (region) {
        case 0x2: storeLE<T>(&ewram[a & 0x3FFFF], value); return;
        case 0x3: storeLE<T>(&iwram[a & 0x7FFF], value); return;
        default: writeSlow<T>(addr, value); return;
    }
}

template <typename T>
RETRA_INLINE T Bus::peek(u32 addr) {
    u32 region = addr >> 24;
    const u32 a = addr & ~(u32)(sizeof(T) - 1);
    switch (region) {
        case 0x0: return a < 0x4000 ? loadLE<T>(&bios[a]) : 0;
        case 0x2: return loadLE<T>(&ewram[a & 0x3FFFF]);
        case 0x3: return loadLE<T>(&iwram[a & 0x7FFF]);
        case 0x5: return loadLE<T>(&pram[a & 0x3FF]);
        case 0x6: {
            u32 o = a & 0x1FFFF;
            if (o >= 0x18000) o -= 0x8000;
            return loadLE<T>(&vram[o]);
        }
        case 0x7: return loadLE<T>(&oam[a & 0x3FF]);
        case 0x8:
        case 0x9:
        case 0xA:
        case 0xB:
        case 0xC:
        case 0xD: return loadLE<T>(&rom[a & 0x1FFFFFF]);
        default: return readSlow<T>(addr);
    }
}

inline u32 Bus::fetch32(u32 addr, bool seq) {
    u32 region = (addr >> 24) & 0xF;
    const u32 a = addr & ~3u;
    switch (region) {
        case 0x0:
            g->sched.now += 1;
            if (a < 0x4000) {
                if (a + 8 < 0x4000) biosLatch = loadLE<u32>(&bios[a + 8]);
                return loadLE<u32>(&bios[a]);
            }
            return 0;
        case 0x2: g->sched.now += timing[2][seq][2]; return loadLE<u32>(&ewram[a & 0x3FFFF]);
        case 0x3: g->sched.now += 1; return loadLE<u32>(&iwram[a & 0x7FFF]);
        case 0x8:
        case 0x9:
        case 0xA:
        case 0xB:
        case 0xC:
        case 0xD:
            g->sched.now += (seq && prefetchEnabled) ? 2 : timing[2][seq][region];
            return loadLE<u32>(&rom[a & 0x1FFFFFF]);
        default: return read<u32>(addr, seq);
    }
}

inline u16 Bus::fetch16(u32 addr, bool seq) {
    u32 region = (addr >> 24) & 0xF;
    const u32 a = addr & ~1u;
    switch (region) {
        case 0x0:
            g->sched.now += 1;
            if (a < 0x4000) {
                if (a + 4 < 0x4000) biosLatch = loadLE<u32>(&bios[(a + 4) & ~3u]);
                return loadLE<u16>(&bios[a]);
            }
            return 0;
        case 0x2: g->sched.now += timing[1][seq][2]; return loadLE<u16>(&ewram[a & 0x3FFFF]);
        case 0x3: g->sched.now += 1; return loadLE<u16>(&iwram[a & 0x7FFF]);
        case 0x8:
        case 0x9:
        case 0xA:
        case 0xB:
        case 0xC:
        case 0xD:
            g->sched.now += (seq && prefetchEnabled) ? 1 : timing[1][seq][region];
            return loadLE<u16>(&rom[a & 0x1FFFFFF]);
        default: return read<u16>(addr, seq);
    }
}

}  // namespace retra

// Retra GBA core - ARM7TDMI common (modes, exceptions, run loop).
#include "cpu.h"

#include "bus_inl.h"
#include "gba.h"
#include "state.h"

namespace retra {

int Cpu::bankIndex(u32 m) {
    switch (m) {
        case MODE_FIQ: return 1;
        case MODE_IRQ: return 2;
        case MODE_SVC: return 3;
        case MODE_ABT: return 4;
        case MODE_UND: return 5;
        default: return 0;
    }
}

void Cpu::reset() {
    std::memset(r, 0, sizeof(r));
    std::memset(bankR13, 0, sizeof(bankR13));
    std::memset(bankR14, 0, sizeof(bankR14));
    std::memset(bankSpsr, 0, sizeof(bankSpsr));
    std::memset(bankFiq, 0, sizeof(bankFiq));
    std::memset(bankUsr, 0, sizeof(bankUsr));
    fN = fZ = fC = fV = 0;
    mode = MODE_SVC;
    thumb = false;
    irqDisable = true;
    fiqDisable = true;
    spsr = 0;
    halted = false;
    irqLine = false;
    r[15] = 8;
}

void Cpu::switchMode(u32 newMode) {
    int ob = bankIndex(mode), nb = bankIndex(newMode);
    if (ob != nb) {
        bankR13[ob] = r[13];
        bankR14[ob] = r[14];
        bankSpsr[ob] = spsr;
        if (ob == 1) {
            for (int i = 0; i < 5; i++) {
                bankFiq[i] = r[8 + i];
                r[8 + i] = bankUsr[i];
            }
        } else if (nb == 1) {
            for (int i = 0; i < 5; i++) {
                bankUsr[i] = r[8 + i];
                r[8 + i] = bankFiq[i];
            }
        }
        r[13] = bankR13[nb];
        r[14] = bankR14[nb];
        spsr = bankSpsr[nb];
    }
    mode = newMode;
}

void Cpu::setCpsr(u32 v) {
    setFlags(v);
    irqDisable = (v >> 7) & 1;
    fiqDisable = (v >> 6) & 1;
    thumb = (v >> 5) & 1;
    u32 m = v & 0x1F;
    if (bankIndex(m) == 0 && m != MODE_USR && m != MODE_SYS) m = MODE_SYS;  // invalid -> sys
    switchMode(m);
}

void Cpu::idle(u32 n) { g->sched.now += n; }

void Cpu::branchTo(u32 addr) {
    Bus& b = g->bus;
    if (thumb) {
        addr &= ~1u;
        r[15] = addr + 2;
        u32 region = (addr >> 24) & 0xF;
        g->sched.now += b.timing[1][0][region] + b.timing[1][1][region];
    } else {
        addr &= ~3u;
        r[15] = addr + 4;
        u32 region = (addr >> 24) & 0xF;
        g->sched.now += b.timing[2][0][region] + b.timing[2][1][region];
    }
}

void Cpu::raiseIrq() {
    // Called between instructions: r[15] = next + 8 (ARM) / next + 4 (THUMB).
    u32 next = r[15] - (thumb ? 4 : 8);
    u32 old = cpsr();
    switchMode(MODE_IRQ);
    spsr = old;
    r[14] = next + 4;
    irqDisable = true;
    thumb = false;
    halted = false;
    r[15] = 0x18 + 8;
    g->sched.now += 3;
}

void Cpu::raiseSwi() {
    // Called during execution of the SWI instruction.
    u32 next = r[15] - (thumb ? 2 : 4);
    u32 old = cpsr();
    switchMode(MODE_SVC);
    spsr = old;
    r[14] = next;
    irqDisable = true;
    thumb = false;
    branchTo(0x08);
}

void Cpu::raiseUndefined() {
    u32 next = r[15] - (thumb ? 2 : 4);
    u32 old = cpsr();
    switchMode(MODE_UND);
    spsr = old;
    r[14] = next;
    irqDisable = true;
    thumb = false;
    branchTo(0x04);
}

bool Cpu::condPassed(u32 cond) const {
    switch (cond) {
        case 0x0: return fZ;
        case 0x1: return !fZ;
        case 0x2: return fC;
        case 0x3: return !fC;
        case 0x4: return fN;
        case 0x5: return !fN;
        case 0x6: return fV;
        case 0x7: return !fV;
        case 0x8: return fC && !fZ;
        case 0x9: return !fC || fZ;
        case 0xA: return fN == fV;
        case 0xB: return fN != fV;
        case 0xC: return !fZ && fN == fV;
        case 0xD: return fZ || fN != fV;
        case 0xE: return true;
        default: return false;
    }
}

u32 Cpu::openBus() {
    if (!thumb) return g->bus.peek<u32>(r[15]);
    u32 h = g->bus.peek<u16>(r[15]);
    return h | (h << 16);
}

void Cpu::run() {
    Scheduler& s = g->sched;
    while (s.now < s.next) {
        if (RETRA_UNLIKELY(halted)) {
            s.now = s.next;
            break;
        }
        if (RETRA_UNLIKELY(irqLine) && !irqDisable) raiseIrq();
        if (thumb)
            stepThumb();
        else
            stepArm();
    }
}

void Cpu::serialize(StateWriter& w) const {
    w.tag("CPU0");
    w.pod(r);
    w.pod(fN);
    w.pod(fZ);
    w.pod(fC);
    w.pod(fV);
    w.pod(mode);
    w.pod(thumb);
    w.pod(irqDisable);
    w.pod(fiqDisable);
    w.pod(spsr);
    w.pod(bankR13);
    w.pod(bankR14);
    w.pod(bankSpsr);
    w.pod(bankFiq);
    w.pod(bankUsr);
    w.pod(halted);
}

void Cpu::deserialize(StateReader& rd) {
    rd.tag("CPU0");
    rd.pod(r);
    rd.pod(fN);
    rd.pod(fZ);
    rd.pod(fC);
    rd.pod(fV);
    rd.pod(mode);
    rd.pod(thumb);
    rd.pod(irqDisable);
    rd.pod(fiqDisable);
    rd.pod(spsr);
    rd.pod(bankR13);
    rd.pod(bankR14);
    rd.pod(bankSpsr);
    rd.pod(bankFiq);
    rd.pod(bankUsr);
    rd.pod(halted);
    fN &= 1;
    fZ &= 1;
    fC &= 1;
    fV &= 1;
}

}  // namespace retra

// Retra GBA core - ARM (32-bit) instruction set.
#include <array>
#include <utility>

#include "bus_inl.h"
#include "cpu.h"
#include "cpu_shift.h"
#include "gba.h"

namespace retra {

using ArmHandler = void (*)(Cpu&, u32);

// ---------------------------------------------------------------- data processing
template <u32 OPC, bool S, bool IMM, u32 SHT, bool REGSHIFT>
static void armDataProc(Cpu& c, u32 op) {
    const u32 rn = (op >> 16) & 15;
    const u32 rd = (op >> 12) & 15;
    u32 op2;
    u32 carry = c.fC;
    u32 rnv;
    if constexpr (IMM) {
        const u32 rot = ((op >> 8) & 15) * 2;
        op2 = ror32(op & 0xFF, rot);
        if (rot) carry = op2 >> 31;
        rnv = c.r[rn];
    } else if constexpr (!REGSHIFT) {
        op2 = c.shiftImm<S>(SHT, c.r[op & 15], (op >> 7) & 31, carry);
        rnv = c.r[rn];
    } else {
        // Register specified shift: PC operands read as +12.
        c.r[15] += 4;
        const u32 amt = c.r[(op >> 8) & 15] & 0xFF;
        op2 = c.shiftReg<S>(SHT, c.r[op & 15], amt, carry);
        rnv = c.r[rn];
        c.r[15] -= 4;
        c.idle(1);
    }

    u32 res = 0;
    if constexpr (OPC == 0x0) {  // AND
        res = rnv & op2;
        if (S) { c.setNZ(res); c.fC = carry; }
    } else if constexpr (OPC == 0x1) {  // EOR
        res = rnv ^ op2;
        if (S) { c.setNZ(res); c.fC = carry; }
    } else if constexpr (OPC == 0x2) {  // SUB
        res = S ? c.subFlags(rnv, op2) : rnv - op2;
    } else if constexpr (OPC == 0x3) {  // RSB
        res = S ? c.subFlags(op2, rnv) : op2 - rnv;
    } else if constexpr (OPC == 0x4) {  // ADD
        res = S ? c.addFlags(rnv, op2) : rnv + op2;
    } else if constexpr (OPC == 0x5) {  // ADC
        res = S ? c.adcFlags(rnv, op2, c.fC) : rnv + op2 + c.fC;
    } else if constexpr (OPC == 0x6) {  // SBC
        res = S ? c.sbcFlags(rnv, op2, c.fC) : rnv - op2 - (c.fC ^ 1);
    } else if constexpr (OPC == 0x7) {  // RSC
        res = S ? c.sbcFlags(op2, rnv, c.fC) : op2 - rnv - (c.fC ^ 1);
    } else if constexpr (OPC == 0x8) {  // TST
        c.setNZ(rnv & op2);
        c.fC = carry;
    } else if constexpr (OPC == 0x9) {  // TEQ
        c.setNZ(rnv ^ op2);
        c.fC = carry;
    } else if constexpr (OPC == 0xA) {  // CMP
        c.subFlags(rnv, op2);
    } else if constexpr (OPC == 0xB) {  // CMN
        c.addFlags(rnv, op2);
    } else if constexpr (OPC == 0xC) {  // ORR
        res = rnv | op2;
        if (S) { c.setNZ(res); c.fC = carry; }
    } else if constexpr (OPC == 0xD) {  // MOV
        res = op2;
        if (S) { c.setNZ(res); c.fC = carry; }
    } else if constexpr (OPC == 0xE) {  // BIC
        res = rnv & ~op2;
        if (S) { c.setNZ(res); c.fC = carry; }
    } else {  // MVN
        res = ~op2;
        if (S) { c.setNZ(res); c.fC = carry; }
    }

    if constexpr (OPC >= 0x8 && OPC <= 0xB) {
        if (rd == 15 && c.hasSpsr()) {
            // Legacy "P" form: restore CPSR from SPSR.
            c.setCpsr(c.spsr);
        }
        return;
    } else {
        if (rd == 15) {
            if (S && c.hasSpsr()) c.setCpsr(c.spsr);
            c.branchTo(res);
        } else {
            c.r[rd] = res;
        }
    }
}

// ---------------------------------------------------------------- multiply
template <bool ACC, bool S>
static void armMul(Cpu& c, u32 op) {
    const u32 rd = (op >> 16) & 15, rn = (op >> 12) & 15, rs = (op >> 8) & 15, rm = op & 15;
    u32 res = c.r[rm] * c.r[rs];
    if (ACC) res += c.r[rn];
    c.idle(Cpu::mulCycles(c.r[rs], true) + (ACC ? 1 : 0));
    if (S) c.setNZ(res);
    c.r[rd] = res;
}

template <bool SIGNED, bool ACC, bool S>
static void armMulLong(Cpu& c, u32 op) {
    const u32 rdhi = (op >> 16) & 15, rdlo = (op >> 12) & 15, rs = (op >> 8) & 15, rm = op & 15;
    u64 res;
    if (SIGNED)
        res = (u64)((s64)(s32)c.r[rm] * (s64)(s32)c.r[rs]);
    else
        res = (u64)c.r[rm] * (u64)c.r[rs];
    if (ACC) res += ((u64)c.r[rdhi] << 32) | c.r[rdlo];
    c.idle(Cpu::mulCycles(c.r[rs], SIGNED) + 1 + (ACC ? 1 : 0));
    c.r[rdlo] = (u32)res;
    c.r[rdhi] = (u32)(res >> 32);
    if (S) {
        c.fN = (u32)(res >> 63);
        c.fZ = res == 0;
    }
}

// ---------------------------------------------------------------- single data transfer
template <bool REGOFF, bool PRE, bool UP, bool BYTE, bool WB, bool LOAD, u32 SHT>
static void armSdt(Cpu& c, u32 op) {
    const u32 rn = (op >> 16) & 15, rd = (op >> 12) & 15;
    u32 off;
    if constexpr (REGOFF) {
        u32 dummy = 0;
        off = c.shiftImm<false>(SHT, c.r[op & 15], (op >> 7) & 31, dummy);
    } else {
        off = op & 0xFFF;
    }
    const u32 base = c.r[rn];
    const u32 offAddr = UP ? base + off : base - off;
    const u32 addr = PRE ? offAddr : base;
    Bus& b = c.g->bus;
    if constexpr (LOAD) {
        u32 v;
        if (BYTE)
            v = b.read<u8>(addr);
        else
            v = ror32(b.read<u32>(addr), (addr & 3) * 8);
        c.idle(1);
        if (!PRE || WB) c.r[rn] = offAddr;
        if (rd == 15)
            c.branchTo(v);
        else
            c.r[rd] = v;
    } else {
        const u32 v = c.r[rd] + (rd == 15 ? 4 : 0);
        if (BYTE)
            b.write<u8>(addr, (u8)v);
        else
            b.write<u32>(addr, v);
        if (!PRE || WB) c.r[rn] = offAddr;
    }
}

// ---------------------------------------------------------------- halfword / signed transfer
template <bool PRE, bool UP, bool IMMOFF, bool WB, bool LOAD, u32 SH>
static void armHdt(Cpu& c, u32 op) {
    const u32 rn = (op >> 16) & 15, rd = (op >> 12) & 15;
    const u32 off = IMMOFF ? (((op >> 4) & 0xF0) | (op & 0xF)) : c.r[op & 15];
    const u32 base = c.r[rn];
    const u32 offAddr = UP ? base + off : base - off;
    const u32 addr = PRE ? offAddr : base;
    Bus& b = c.g->bus;
    if constexpr (LOAD) {
        u32 v;
        if constexpr (SH == 1) {
            v = ror32(b.read<u16>(addr), (addr & 1) * 8);
        } else if constexpr (SH == 2) {
            v = (u32)(s32)(s8)b.read<u8>(addr);
        } else {
            if (addr & 1)
                v = (u32)(s32)(s8)b.read<u8>(addr);
            else
                v = (u32)(s32)(s16)b.read<u16>(addr);
        }
        c.idle(1);
        if (!PRE || WB) c.r[rn] = offAddr;
        if (rd == 15)
            c.branchTo(v);
        else
            c.r[rd] = v;
    } else {
        if constexpr (SH == 1) {
            const u32 v = c.r[rd] + (rd == 15 ? 4 : 0);
            b.write<u16>(addr, (u16)v);
        }
        // SH 2/3 stores (LDRD/STRD) do not exist on ARMv4: no transfer.
        if (!PRE || WB) c.r[rn] = offAddr;
    }
}

template <bool BYTE>
static void armSwap(Cpu& c, u32 op) {
    const u32 rn = (op >> 16) & 15, rd = (op >> 12) & 15, rm = op & 15;
    const u32 addr = c.r[rn];
    const u32 src = c.r[rm];
    Bus& b = c.g->bus;
    u32 tmp;
    if (BYTE) {
        tmp = b.read<u8>(addr);
        b.write<u8>(addr, (u8)src);
    } else {
        tmp = ror32(b.read<u32>(addr), (addr & 3) * 8);
        b.write<u32>(addr, src);
    }
    c.idle(1);
    c.r[rd] = tmp;
}

// ---------------------------------------------------------------- block transfer
template <bool PRE, bool UP, bool S, bool WB, bool LOAD>
static void armBlock(Cpu& c, u32 op) {
    const u32 rn = (op >> 16) & 15;
    u32 list = op & 0xFFFF;
    u32 n = (u32)__builtin_popcount(list);
    if (list == 0) {
        list = 0x8000;
        n = 16;
    }
    const u32 base = c.r[rn];
    u32 start, final;
    if (UP) {
        final = base + n * 4;
        start = PRE ? base + 4 : base;
    } else {
        final = base - n * 4;
        start = PRE ? final : final + 4;
    }
    const bool userBank = S && !(LOAD && (list & 0x8000));
    const u32 oldMode = c.mode;
    if (userBank) c.switchMode(MODE_USR);

    Bus& b = c.g->bus;
    u32 addr = start;
    bool seq = false;
    if constexpr (LOAD) {
        if (WB) c.r[rn] = final;
        u32 pcVal = 0;
        for (u32 i = 0; i < 16; i++) {
            if (!(list & (1u << i))) continue;
            u32 v = b.read<u32>(addr, seq);
            seq = true;
            if (i == 15)
                pcVal = v;
            else
                c.r[i] = v;
            addr += 4;
        }
        c.idle(1);
        if (userBank) c.switchMode(oldMode);
        if (list & 0x8000) {
            if (S && c.hasSpsr()) c.setCpsr(c.spsr);
            c.branchTo(pcVal);
        }
    } else {
        bool first = true;
        for (u32 i = 0; i < 16; i++) {
            if (!(list & (1u << i))) continue;
            u32 v = (i == 15) ? c.r[15] + 4 : c.r[i];
            b.write<u32>(addr, v, seq);
            seq = true;
            if (first && WB) c.r[rn] = final;
            first = false;
            addr += 4;
        }
        if (userBank) c.switchMode(oldMode);
    }
}

// ---------------------------------------------------------------- branches / misc
template <bool LINK>
static void armBranch(Cpu& c, u32 op) {
    const u32 off = (u32)((s32)(op << 8) >> 6);
    if (LINK) c.r[14] = c.r[15] - 4;
    c.branchTo(c.r[15] + off);
}

static void armBx(Cpu& c, u32 op) {
    const u32 v = c.r[op & 15];
    c.thumb = v & 1;
    c.branchTo(v);
}

template <bool SPSR>
static void armMrs(Cpu& c, u32 op) {
    const u32 rd = (op >> 12) & 15;
    c.r[rd] = SPSR ? (c.hasSpsr() ? c.spsr : c.cpsr()) : c.cpsr();
}

template <bool IMM, bool SPSR>
static void armMsr(Cpu& c, u32 op) {
    const u32 v = IMM ? ror32(op & 0xFF, ((op >> 8) & 15) * 2) : c.r[op & 15];
    u32 mask = 0;
    if (op & (1u << 19)) mask |= 0xFF000000;
    if (op & (1u << 18)) mask |= 0x00FF0000;
    if (op & (1u << 17)) mask |= 0x0000FF00;
    if (op & (1u << 16)) mask |= 0x000000FF;
    if (SPSR) {
        if (c.hasSpsr()) c.spsr = (c.spsr & ~mask) | (v & mask);
    } else {
        if (c.mode == MODE_USR) mask &= 0xFF000000;
        u32 nv = (c.cpsr() & ~mask) | (v & mask);
        nv = (nv & ~0x20u) | (c.thumb ? 0x20u : 0u);
        c.setCpsr(nv);
    }
}

static void armSwi(Cpu& c, u32) { c.raiseSwi(); }

static void armUndefined(Cpu& c, u32 op) {
    const u32 pc = c.r[15] - 8;
    if (pc < 0x4000 && (op & kHleTrapMask) == kHleTrapBase) {
        c.g->hleCall((op & 0xF) | ((op >> 4) & 0xFF0));
        return;
    }
    c.raiseUndefined();
}

// ---------------------------------------------------------------- decoding
// idx = bits 27..20 << 4 | bits 7..4
enum ArmKind : u32 {
    AK_UNDEF,
    AK_DP_REG,
    AK_DP_IMM,
    AK_MUL,
    AK_MULL,
    AK_SWP,
    AK_HDT,
    AK_BX,
    AK_MRS,
    AK_MSR_REG,
    AK_MSR_IMM,
    AK_SDT_IMM,
    AK_SDT_REG,
    AK_BLOCK,
    AK_BRANCH,
    AK_SWI,
};

static constexpr u32 armKind(u32 idx) {
    const u32 hi = idx >> 4, lo = idx & 0xF;
    switch (hi >> 5) {
        case 0:
            if (lo == 0x9) {
                if ((hi & 0xFC) == 0x00) return AK_MUL;
                if ((hi & 0xF8) == 0x08) return AK_MULL;
                if ((hi & 0xFB) == 0x10) return AK_SWP;
                return AK_UNDEF;
            }
            if ((lo & 0x9) == 0x9) return AK_HDT;
            if ((hi & 0xF9) == 0x10) {
                if (hi == 0x12 && lo == 0x1) return AK_BX;
                if ((hi & 0xFB) == 0x10 && lo == 0) return AK_MRS;
                if ((hi & 0xFB) == 0x12 && lo == 0) return AK_MSR_REG;
                return AK_UNDEF;
            }
            return AK_DP_REG;
        case 1:
            if ((hi & 0xF9) == 0x30) return (hi & 0xFB) == 0x32 ? AK_MSR_IMM : AK_UNDEF;
            return AK_DP_IMM;
        case 2: return AK_SDT_IMM;
        case 3: return (lo & 1) ? AK_UNDEF : AK_SDT_REG;
        case 4: return AK_BLOCK;
        case 5: return AK_BRANCH;
        case 6: return AK_UNDEF;
        default: return (hi & 0x10) ? AK_SWI : AK_UNDEF;
    }
}

// Reduce the index to the bits a handler actually depends on (fewer instantiations).
static constexpr u32 armCanon(u32 idx) {
    const u32 hi = idx >> 4, lo = idx & 0xF;
    switch (armKind(idx)) {
        case AK_UNDEF: return 0xE00 | 0x1;  // canonical undefined slot (cond. space 111, bit4)
        case AK_DP_REG: return (hi << 4) | ((lo & 1) ? (lo & 0x7) : (lo & 0x6));
        case AK_DP_IMM: return hi << 4;
        case AK_MUL:
        case AK_MULL:
        case AK_SWP: return idx;
        case AK_HDT: return idx;
        case AK_BX: return idx;
        case AK_MRS:
        case AK_MSR_REG: return idx;
        case AK_MSR_IMM: return hi << 4;
        case AK_SDT_IMM: return hi << 4;
        case AK_SDT_REG: return (hi << 4) | (lo & 0x6);
        case AK_BLOCK: return hi << 4;
        case AK_BRANCH: return (hi & 0xF0) << 4;
        default: return 0xF00;  // SWI
    }
}

template <u32 IDX>
static void armExec(Cpu& c, u32 op) {
    constexpr u32 hi = IDX >> 4, lo = IDX & 0xF;
    constexpr u32 kind = armKind(IDX);
    if constexpr (IDX == (0xE00 | 0x1)) {
        armUndefined(c, op);
    } else if constexpr (kind == AK_DP_REG) {
        armDataProc<(hi >> 1) & 15, (hi & 1) != 0, false, (lo >> 1) & 3, (lo & 1) != 0>(c, op);
    } else if constexpr (kind == AK_DP_IMM) {
        armDataProc<(hi >> 1) & 15, (hi & 1) != 0, true, 0, false>(c, op);
    } else if constexpr (kind == AK_MUL) {
        armMul<(hi & 2) != 0, (hi & 1) != 0>(c, op);
    } else if constexpr (kind == AK_MULL) {
        armMulLong<(hi & 4) != 0, (hi & 2) != 0, (hi & 1) != 0>(c, op);
    } else if constexpr (kind == AK_SWP) {
        armSwap<(hi & 4) != 0>(c, op);
    } else if constexpr (kind == AK_HDT) {
        armHdt<(hi & 0x10) != 0, (hi & 8) != 0, (hi & 4) != 0, (hi & 2) != 0, (hi & 1) != 0, (lo >> 1) & 3>(c, op);
    } else if constexpr (kind == AK_BX) {
        armBx(c, op);
    } else if constexpr (kind == AK_MRS) {
        armMrs<(hi & 4) != 0>(c, op);
    } else if constexpr (kind == AK_MSR_REG) {
        armMsr<false, (hi & 4) != 0>(c, op);
    } else if constexpr (kind == AK_MSR_IMM) {
        armMsr<true, (hi & 4) != 0>(c, op);
    } else if constexpr (kind == AK_SDT_IMM) {
        armSdt<false, (hi & 0x10) != 0, (hi & 8) != 0, (hi & 4) != 0, (hi & 2) != 0, (hi & 1) != 0, 0>(c, op);
    } else if constexpr (kind == AK_SDT_REG) {
        armSdt<true, (hi & 0x10) != 0, (hi & 8) != 0, (hi & 4) != 0, (hi & 2) != 0, (hi & 1) != 0, (lo >> 1) & 3>(
            c, op);
    } else if constexpr (kind == AK_BLOCK) {
        armBlock<(hi & 0x10) != 0, (hi & 8) != 0, (hi & 4) != 0, (hi & 2) != 0, (hi & 1) != 0>(c, op);
    } else if constexpr (kind == AK_BRANCH) {
        armBranch<(hi & 0x10) != 0>(c, op);
    } else if constexpr (kind == AK_SWI) {
        armSwi(c, op);
    } else {
        armUndefined(c, op);
    }
}

template <u32... I>
static constexpr std::array<ArmHandler, 4096> makeArmTable(std::integer_sequence<u32, I...>) {
    return {{&armExec<armCanon(I)>...}};
}

static const std::array<ArmHandler, 4096> kArmTable = makeArmTable(std::make_integer_sequence<u32, 4096>{});

static constexpr u16 makeCondMask(u32 cond) {
    u16 m = 0;
    for (u32 f = 0; f < 16; f++) {
        const bool n = f & 8, z = f & 4, c = f & 2, v = f & 1;
        bool r = false;
        switch (cond) {
            case 0x0: r = z; break;
            case 0x1: r = !z; break;
            case 0x2: r = c; break;
            case 0x3: r = !c; break;
            case 0x4: r = n; break;
            case 0x5: r = !n; break;
            case 0x6: r = v; break;
            case 0x7: r = !v; break;
            case 0x8: r = c && !z; break;
            case 0x9: r = !c || z; break;
            case 0xA: r = n == v; break;
            case 0xB: r = n != v; break;
            case 0xC: r = !z && n == v; break;
            case 0xD: r = z || n != v; break;
            case 0xE: r = true; break;
            default: r = false; break;
        }
        if (r) m |= (u16)(1u << f);
    }
    return m;
}

static constexpr u16 kCondTable[16] = {
    makeCondMask(0), makeCondMask(1), makeCondMask(2),  makeCondMask(3),  makeCondMask(4),  makeCondMask(5),
    makeCondMask(6), makeCondMask(7), makeCondMask(8),  makeCondMask(9),  makeCondMask(10), makeCondMask(11),
    makeCondMask(12), makeCondMask(13), makeCondMask(14), makeCondMask(15),
};

void Cpu::stepArm() {
    const u32 pc = r[15] - 8;
    const u32 op = g->bus.fetch32(pc, true);
    const u32 cond = op >> 28;
    if (RETRA_LIKELY(cond == 0xE) ||
        ((kCondTable[cond] >> ((fN << 3) | (fZ << 2) | (fC << 1) | fV)) & 1)) {
        kArmTable[((op >> 16) & 0xFF0) | ((op >> 4) & 0xF)](*this, op);
    }
    r[15] += thumb ? 2 : 4;
}

}  // namespace retra

// Retra GBA core - barrel shifter (shared by ARM and THUMB).
#pragma once

#include "cpu.h"

namespace retra {

// Immediate shift amount (0..31) with the ARM encodings for #0 (LSR/ASR #32, RRX).
template <bool SETC>
RETRA_INLINE u32 Cpu::shiftImm(u32 type, u32 v, u32 amt, u32& carry) const {
    switch (type) {
        case 0:  // LSL
            if (amt == 0) return v;
            if (SETC) carry = (v >> (32 - amt)) & 1;
            return v << amt;
        case 1:  // LSR
            if (amt == 0) {
                if (SETC) carry = v >> 31;
                return 0;
            }
            if (SETC) carry = (v >> (amt - 1)) & 1;
            return v >> amt;
        case 2:  // ASR
            if (amt == 0) {
                if (SETC) carry = v >> 31;
                return (u32)((s32)v >> 31);
            }
            if (SETC) carry = ((u32)((s32)v >> (amt - 1))) & 1;
            return (u32)((s32)v >> amt);
        default:  // ROR / RRX
            if (amt == 0) {
                const u32 res = (fC << 31) | (v >> 1);
                if (SETC) carry = v & 1;
                return res;
            }
            if (SETC) carry = (v >> (amt - 1)) & 1;
            return ror32(v, amt);
    }
}

// Register specified shift amount (bottom byte of Rs).
template <bool SETC>
RETRA_INLINE u32 Cpu::shiftReg(u32 type, u32 v, u32 amt, u32& carry) const {
    if (amt == 0) return v;
    switch (type) {
        case 0:  // LSL
            if (amt < 32) {
                if (SETC) carry = (v >> (32 - amt)) & 1;
                return v << amt;
            }
            if (SETC) carry = amt == 32 ? (v & 1) : 0;
            return 0;
        case 1:  // LSR
            if (amt < 32) {
                if (SETC) carry = (v >> (amt - 1)) & 1;
                return v >> amt;
            }
            if (SETC) carry = amt == 32 ? (v >> 31) : 0;
            return 0;
        case 2:  // ASR
            if (amt < 32) {
                if (SETC) carry = ((u32)((s32)v >> (amt - 1))) & 1;
                return (u32)((s32)v >> amt);
            }
            if (SETC) carry = v >> 31;
            return (u32)((s32)v >> 31);
        default: {  // ROR
            const u32 a = amt & 31;
            if (a == 0) {
                if (SETC) carry = v >> 31;
                return v;
            }
            if (SETC) carry = (v >> (a - 1)) & 1;
            return ror32(v, a);
        }
    }
}

}  // namespace retra

// Retra GBA core - THUMB (16-bit) instruction set.
#include <array>
#include <utility>

#include "bus_inl.h"
#include "cpu.h"
#include "cpu_shift.h"
#include "gba.h"

namespace retra {

using ThumbHandler = void (*)(Cpu&, u16);

// Format 1: move shifted register
template <u32 TYPE>
static void thShiftImm(Cpu& c, u16 op) {
    const u32 rd = op & 7, rs = (op >> 3) & 7, amt = (op >> 6) & 31;
    u32 carry = c.fC;
    const u32 res = c.shiftImm<true>(TYPE, c.r[rs], amt, carry);
    c.fC = carry;
    c.setNZ(res);
    c.r[rd] = res;
}

// Format 2: add/subtract
template <bool IMM, bool SUB>
static void thAddSub(Cpu& c, u16 op) {
    const u32 rd = op & 7, rs = (op >> 3) & 7, rn = (op >> 6) & 7;
    const u32 v = IMM ? rn : c.r[rn];
    c.r[rd] = SUB ? c.subFlags(c.r[rs], v) : c.addFlags(c.r[rs], v);
}

// Format 3: move/compare/add/subtract immediate
template <u32 OP>
static void thImm(Cpu& c, u16 op) {
    const u32 rd = (op >> 8) & 7, imm = op & 0xFF;
    switch (OP) {
        case 0: c.r[rd] = imm; c.setNZ(imm); break;
        case 1: c.subFlags(c.r[rd], imm); break;
        case 2: c.r[rd] = c.addFlags(c.r[rd], imm); break;
        default: c.r[rd] = c.subFlags(c.r[rd], imm); break;
    }
}

// Format 4: ALU operations
template <u32 OP>
static void thAlu(Cpu& c, u16 op) {
    const u32 rd = op & 7, rs = (op >> 3) & 7;
    const u32 a = c.r[rd], b = c.r[rs];
    u32 carry = c.fC;
    switch (OP) {
        case 0x0: c.r[rd] = a & b; c.setNZ(c.r[rd]); break;
        case 0x1: c.r[rd] = a ^ b; c.setNZ(c.r[rd]); break;
        case 0x2: c.r[rd] = c.shiftReg<true>(0, a, b & 0xFF, carry); c.fC = carry; c.setNZ(c.r[rd]); c.idle(1); break;
        case 0x3: c.r[rd] = c.shiftReg<true>(1, a, b & 0xFF, carry); c.fC = carry; c.setNZ(c.r[rd]); c.idle(1); break;
        case 0x4: c.r[rd] = c.shiftReg<true>(2, a, b & 0xFF, carry); c.fC = carry; c.setNZ(c.r[rd]); c.idle(1); break;
        case 0x5: c.r[rd] = c.adcFlags(a, b, c.fC); break;
        case 0x6: c.r[rd] = c.sbcFlags(a, b, c.fC); break;
        case 0x7: c.r[rd] = c.shiftReg<true>(3, a, b & 0xFF, carry); c.fC = carry; c.setNZ(c.r[rd]); c.idle(1); break;
        case 0x8: c.setNZ(a & b); break;
        case 0x9: c.r[rd] = c.subFlags(0, b); break;
        case 0xA: c.subFlags(a, b); break;
        case 0xB: c.addFlags(a, b); break;
        case 0xC: c.r[rd] = a | b; c.setNZ(c.r[rd]); break;
        case 0xD:
            c.idle(Cpu::mulCycles(a, true));
            c.r[rd] = a * b;
            c.setNZ(c.r[rd]);
            break;
        case 0xE: c.r[rd] = a & ~b; c.setNZ(c.r[rd]); break;
        default: c.r[rd] = ~b; c.setNZ(c.r[rd]); break;
    }
}

// Format 5: hi register operations / BX
template <u32 OP>
static void thHiReg(Cpu& c, u16 op) {
    const u32 rd = (op & 7) | ((op >> 4) & 8);
    const u32 rs = (op >> 3) & 15;
    const u32 v = c.r[rs];
    switch (OP) {
        case 0: {
            const u32 res = c.r[rd] + v;
            if (rd == 15)
                c.branchTo(res);
            else
                c.r[rd] = res;
            break;
        }
        case 1: c.subFlags(c.r[rd], v); break;
        case 2:
            if (rd == 15)
                c.branchTo(v);
            else
                c.r[rd] = v;
            break;
        default:
            c.thumb = v & 1;
            c.branchTo(v);
            break;
    }
}

// Format 6: PC-relative load
static void thLdrPc(Cpu& c, u16 op) {
    const u32 rd = (op >> 8) & 7;
    const u32 addr = (c.r[15] & ~2u) + ((op & 0xFF) << 2);
    c.r[rd] = c.g->bus.read<u32>(addr);
    c.idle(1);
}

// Format 7/8: load/store with register offset
template <u32 OP>
static void thLdStReg(Cpu& c, u16 op) {
    const u32 rd = op & 7, rb = (op >> 3) & 7, ro = (op >> 6) & 7;
    const u32 addr = c.r[rb] + c.r[ro];
    Bus& b = c.g->bus;
    switch (OP) {
        case 0: b.write<u32>(addr, c.r[rd]); break;                              // STR
        case 1: b.write<u16>(addr, (u16)c.r[rd]); break;                         // STRH
        case 2: b.write<u8>(addr, (u8)c.r[rd]); break;                           // STRB
        case 3: c.r[rd] = (u32)(s32)(s8)b.read<u8>(addr); c.idle(1); break;      // LDSB
        case 4: c.r[rd] = ror32(b.read<u32>(addr), (addr & 3) * 8); c.idle(1); break;  // LDR
        case 5: c.r[rd] = ror32(b.read<u16>(addr), (addr & 1) * 8); c.idle(1); break;  // LDRH
        case 6: c.r[rd] = b.read<u8>(addr); c.idle(1); break;                    // LDRB
        default:                                                                 // LDSH
            if (addr & 1)
                c.r[rd] = (u32)(s32)(s8)b.read<u8>(addr);
            else
                c.r[rd] = (u32)(s32)(s16)b.read<u16>(addr);
            c.idle(1);
            break;
    }
}

// Format 9: load/store with immediate offset
template <bool BYTE, bool LOAD>
static void thLdStImm(Cpu& c, u16 op) {
    const u32 rd = op & 7, rb = (op >> 3) & 7, off = (op >> 6) & 31;
    Bus& b = c.g->bus;
    if (BYTE) {
        const u32 addr = c.r[rb] + off;
        if (LOAD) {
            c.r[rd] = b.read<u8>(addr);
            c.idle(1);
        } else {
            b.write<u8>(addr, (u8)c.r[rd]);
        }
    } else {
        const u32 addr = c.r[rb] + (off << 2);
        if (LOAD) {
            c.r[rd] = ror32(b.read<u32>(addr), (addr & 3) * 8);
            c.idle(1);
        } else {
            b.write<u32>(addr, c.r[rd]);
        }
    }
}

// Format 10: load/store halfword
template <bool LOAD>
static void thLdStH(Cpu& c, u16 op) {
    const u32 rd = op & 7, rb = (op >> 3) & 7, off = ((op >> 6) & 31) << 1;
    const u32 addr = c.r[rb] + off;
    Bus& b = c.g->bus;
    if (LOAD) {
        c.r[rd] = ror32(b.read<u16>(addr), (addr & 1) * 8);
        c.idle(1);
    } else {
        b.write<u16>(addr, (u16)c.r[rd]);
    }
}

// Format 11: SP-relative load/store
template <bool LOAD>
static void thLdStSp(Cpu& c, u16 op) {
    const u32 rd = (op >> 8) & 7;
    const u32 addr = c.r[13] + ((op & 0xFF) << 2);
    Bus& b = c.g->bus;
    if (LOAD) {
        c.r[rd] = ror32(b.read<u32>(addr), (addr & 3) * 8);
        c.idle(1);
    } else {
        b.write<u32>(addr, c.r[rd]);
    }
}

// Format 12: load address
template <bool SP>
static void thAddr(Cpu& c, u16 op) {
    const u32 rd = (op >> 8) & 7;
    const u32 imm = (op & 0xFF) << 2;
    c.r[rd] = (SP ? c.r[13] : (c.r[15] & ~2u)) + imm;
}

// Format 13: add offset to SP
static void thAddSp(Cpu& c, u16 op) {
    const u32 imm = (op & 0x7F) << 2;
    if (op & 0x80)
        c.r[13] -= imm;
    else
        c.r[13] += imm;
}

// Format 14: push/pop
template <bool POP, bool R>
static void thPushPop(Cpu& c, u16 op) {
    u32 list = op & 0xFF;
    Bus& b = c.g->bus;
    bool seq = false;
    if (POP) {
        u32 addr = c.r[13];
        if (list == 0 && !R) {
            // Empty list quirk: PC is loaded, SP += 0x40.
            const u32 v = b.read<u32>(addr);
            c.r[13] = addr + 0x40;
            c.branchTo(v);
            return;
        }
        for (u32 i = 0; i < 8; i++) {
            if (list & (1u << i)) {
                c.r[i] = b.read<u32>(addr, seq);
                seq = true;
                addr += 4;
            }
        }
        c.idle(1);
        if (R) {
            const u32 v = b.read<u32>(addr, seq);
            addr += 4;
            c.r[13] = addr;
            c.branchTo(v);
        } else {
            c.r[13] = addr;
        }
    } else {
        if (list == 0 && !R) {
            c.r[13] -= 0x40;
            b.write<u32>(c.r[13], c.r[15] + 2);
            return;
        }
        const u32 n = (u32)__builtin_popcount(list) + (R ? 1 : 0);
        u32 addr = c.r[13] - n * 4;
        c.r[13] = addr;
        for (u32 i = 0; i < 8; i++) {
            if (list & (1u << i)) {
                b.write<u32>(addr, c.r[i], seq);
                seq = true;
                addr += 4;
            }
        }
        if (R) b.write<u32>(addr, c.r[14], seq);
    }
}

// Format 15: multiple load/store
template <bool LOAD>
static void thLdmStm(Cpu& c, u16 op) {
    const u32 rb = (op >> 8) & 7;
    const u32 list = op & 0xFF;
    Bus& b = c.g->bus;
    u32 addr = c.r[rb];
    if (list == 0) {
        if (LOAD) {
            const u32 v = b.read<u32>(addr);
            c.r[rb] = addr + 0x40;
            c.branchTo(v);
        } else {
            b.write<u32>(addr, c.r[15] + 2);
            c.r[rb] = addr + 0x40;
        }
        return;
    }
    const u32 final = addr + (u32)__builtin_popcount(list) * 4;
    bool seq = false;
    if (LOAD) {
        c.r[rb] = final;
        for (u32 i = 0; i < 8; i++) {
            if (list & (1u << i)) {
                c.r[i] = b.read<u32>(addr, seq);
                seq = true;
                addr += 4;
            }
        }
        c.idle(1);
    } else {
        bool first = true;
        for (u32 i = 0; i < 8; i++) {
            if (list & (1u << i)) {
                b.write<u32>(addr, c.r[i], seq);
                seq = true;
                if (first) c.r[rb] = final;
                first = false;
                addr += 4;
            }
        }
    }
}

// Format 16: conditional branch
template <u32 COND>
static void thBcond(Cpu& c, u16 op) {
    if (!c.condPassed(COND)) return;
    const u32 off = (u32)((s32)(s8)(op & 0xFF) << 1);
    c.branchTo(c.r[15] + off);
}

static void thSwi(Cpu& c, u16) { c.raiseSwi(); }
static void thUndef(Cpu& c, u16) { c.raiseUndefined(); }

// Format 18: unconditional branch
static void thB(Cpu& c, u16 op) {
    const u32 off = (u32)(((s32)(op & 0x7FF) << 21) >> 20);
    c.branchTo(c.r[15] + off);
}

// Format 19: long branch with link
static void thBlHi(Cpu& c, u16 op) {
    const u32 off = (u32)(((s32)(op & 0x7FF) << 21) >> 9);
    c.r[14] = c.r[15] + off;
}

static void thBlLo(Cpu& c, u16 op) {
    const u32 next = (c.r[15] - 2) | 1;
    const u32 target = c.r[14] + ((op & 0x7FF) << 1);
    c.r[14] = next;
    c.branchTo(target);
}

// ---------------------------------------------------------------- decoding (idx = op >> 6)
enum ThumbKind : u32 {
    TK_SHIFT,
    TK_ADDSUB,
    TK_IMM,
    TK_ALU,
    TK_HIREG,
    TK_LDRPC,
    TK_LDST_REG,
    TK_LDST_IMM,
    TK_LDST_H,
    TK_LDST_SP,
    TK_ADDR,
    TK_ADDSP,
    TK_PUSHPOP,
    TK_LDMSTM,
    TK_BCOND,
    TK_SWI,
    TK_B,
    TK_BLHI,
    TK_BLLO,
    TK_UNDEF,
};

static constexpr u32 thumbKind(u32 idx) {
    const u32 top5 = idx >> 5;
    if (top5 < 3) return TK_SHIFT;
    if (top5 == 3) return TK_ADDSUB;
    if ((top5 >> 2) == 1) return TK_IMM;
    if ((idx >> 4) == 0x10) return TK_ALU;  // 010000
    if ((idx >> 4) == 0x11) return TK_HIREG;
    if (top5 == 0x09) return TK_LDRPC;
    if ((top5 >> 1) == 0x5) return TK_LDST_REG;
    if ((top5 >> 2) == 0x3) return TK_LDST_IMM;
    if ((top5 >> 1) == 0x8) return TK_LDST_H;
    if ((top5 >> 1) == 0x9) return TK_LDST_SP;
    if ((top5 >> 1) == 0xA) return TK_ADDR;
    if ((idx >> 2) == 0xB0) return TK_ADDSP;
    if ((top5 >> 1) == 0xB) {
        if (((idx >> 2) & 0x6) == 0x4) return TK_PUSHPOP;  // 1011x10x
        return TK_UNDEF;
    }
    if ((top5 >> 1) == 0xC) return TK_LDMSTM;
    if ((top5 >> 1) == 0xD) {
        const u32 cond = (idx >> 2) & 15;
        if (cond == 15) return TK_SWI;
        if (cond == 14) return TK_UNDEF;
        return TK_BCOND;
    }
    if (top5 == 0x1C) return TK_B;
    if (top5 == 0x1E) return TK_BLHI;
    if (top5 == 0x1F) return TK_BLLO;
    return TK_UNDEF;
}

static constexpr u32 thumbCanon(u32 idx) {
    switch (thumbKind(idx)) {
        case TK_SHIFT: return idx & ~31u;
        case TK_ADDSUB: return idx & ~7u;
        case TK_IMM: return idx & ~31u;
        case TK_ALU: return idx;
        case TK_HIREG: return idx & ~3u;
        case TK_LDRPC: return idx & ~31u;
        case TK_LDST_REG: return idx & ~7u;
        case TK_LDST_IMM: return idx & ~31u;
        case TK_LDST_H: return idx & ~31u;
        case TK_LDST_SP: return idx & ~31u;
        case TK_ADDR: return idx & ~31u;
        case TK_ADDSP: return idx & ~3u;
        case TK_PUSHPOP: return idx & ~3u;
        case TK_LDMSTM: return idx & ~31u;
        case TK_BCOND: return idx & ~3u;
        case TK_SWI: return idx & ~3u;
        case TK_B: return idx & ~31u;
        case TK_BLHI: return idx & ~31u;
        case TK_BLLO: return idx & ~31u;
        default: return 0x3A0;  // 11101 -> undefined
    }
}

template <u32 IDX>
static void thumbExec(Cpu& c, u16 op) {
    constexpr u32 kind = thumbKind(IDX);
    if constexpr (kind == TK_SHIFT) {
        thShiftImm<(IDX >> 5) & 3>(c, op);
    } else if constexpr (kind == TK_ADDSUB) {
        thAddSub<(IDX & 0x10) != 0, (IDX & 0x8) != 0>(c, op);
    } else if constexpr (kind == TK_IMM) {
        thImm<(IDX >> 5) & 3>(c, op);
    } else if constexpr (kind == TK_ALU) {
        thAlu<IDX & 15>(c, op);
    } else if constexpr (kind == TK_HIREG) {
        thHiReg<(IDX >> 2) & 3>(c, op);
    } else if constexpr (kind == TK_LDRPC) {
        thLdrPc(c, op);
    } else if constexpr (kind == TK_LDST_REG) {
        thLdStReg<(IDX >> 3) & 7>(c, op);
    } else if constexpr (kind == TK_LDST_IMM) {
        thLdStImm<(IDX & 0x40) != 0, (IDX & 0x20) != 0>(c, op);
    } else if constexpr (kind == TK_LDST_H) {
        thLdStH<(IDX & 0x20) != 0>(c, op);
    } else if constexpr (kind == TK_LDST_SP) {
        thLdStSp<(IDX & 0x20) != 0>(c, op);
    } else if constexpr (kind == TK_ADDR) {
        thAddr<(IDX & 0x20) != 0>(c, op);
    } else if constexpr (kind == TK_ADDSP) {
        thAddSp(c, op);
    } else if constexpr (kind == TK_PUSHPOP) {
        thPushPop<(IDX & 0x20) != 0, (IDX & 0x4) != 0>(c, op);
    } else if constexpr (kind == TK_LDMSTM) {
        thLdmStm<(IDX & 0x20) != 0>(c, op);
    } else if constexpr (kind == TK_BCOND) {
        thBcond<(IDX >> 2) & 15>(c, op);
    } else if constexpr (kind == TK_SWI) {
        thSwi(c, op);
    } else if constexpr (kind == TK_B) {
        thB(c, op);
    } else if constexpr (kind == TK_BLHI) {
        thBlHi(c, op);
    } else if constexpr (kind == TK_BLLO) {
        thBlLo(c, op);
    } else {
        thUndef(c, op);
    }
}

template <u32... I>
static constexpr std::array<ThumbHandler, 1024> makeThumbTable(std::integer_sequence<u32, I...>) {
    return {{&thumbExec<thumbCanon(I)>...}};
}

static const std::array<ThumbHandler, 1024> kThumbTable =
    makeThumbTable(std::make_integer_sequence<u32, 1024>{});

void Cpu::stepThumb() {
    const u32 pc = r[15] - 4;
    const u16 op = g->bus.fetch16(pc, true);
    kThumbTable[op >> 6](*this, op);
    r[15] += thumb ? 2 : 4;
}

