// Retra GBA core - top level facade: loading, frame loop, events, save states.
#include "gba.h"

#include "bus_inl.h"
#include "state.h"

namespace retra {

constexpr u32 kHDrawCycles = 1006;

Gba::Gba()
    : bus(this), cpu(this), ppu(this), apu(this), dma(this), timers(this), save(this), rtc(this), cheats(this) {}

static std::string trimAscii(const u8* p, size_t n) {
    std::string s;
    for (size_t i = 0; i < n; i++) {
        char c = (char)p[i];
        if (c == 0) break;
        s.push_back((c >= 32 && c < 127) ? c : '?');
    }
    while (!s.empty() && s.back() == ' ') s.pop_back();
    return s;
}

static bool containsString(const u8* data, size_t size, const char* str) {
    const size_t n = std::strlen(str);
    if (size < n) return false;
    const u8 first = (u8)str[0];
    for (size_t i = 0; i + n <= size; i++) {
        if (data[i] == first && std::memcmp(data + i, str, n) == 0) return true;
    }
    return false;
}

RomHeaderInfo Gba::parseHeader(const u8* rom, size_t size) {
    RomHeaderInfo h;
    if (size >= 0xC0) {
        h.title = trimAscii(rom + 0xA0, 12);
        h.gameCode = trimAscii(rom + 0xAC, 4);
        h.makerCode = trimAscii(rom + 0xB0, 2);
        h.version = rom[0xBC];
    }
    bool unknown = false;
    h.saveKind = CartSave::detect(rom, size, &unknown);
    const std::string& c = h.gameCode;
    bool rtc = false;
    if (c.size() >= 3) {
        const std::string p = c.substr(0, 3);
        // Pokemon Ruby (AXV), Sapphire (AXP), Emerald (BPE), plus a few other RTC carts.
        if (p == "AXV" || p == "AXP" || p == "BPE" || p == "U3I" || p == "U32" || p == "A2Y" || p == "BR4" ||
            p == "BKA" || p == "U33" || p == "BKE")
            rtc = true;
    }
    if (!rtc && containsString(rom, size, "SIIRTC_V")) rtc = true;
    h.hasRtc = rtc;
    return h;
}

bool Gba::loadRom(const u8* rom, size_t romSize, const u8* bios, size_t biosSize, std::string& error) {
    if (!rom || romSize < 0xC0) {
        error = "ROM is too small to be a GBA image";
        return false;
    }
    if (romSize > kRomMax) {
        error = "ROM is larger than 32 MiB";
        return false;
    }
    if (bios && biosSize != 0x4000) {
        error = "BIOS image must be exactly 16 KiB";
        return false;
    }
    header = parseHeader(rom, romSize);
    bus.setRom(rom, romSize);
    bus.loadBios(bios, biosSize);
    bool unknown = false;
    SaveKind k = CartSave::detect(rom, romSize, &unknown);
    save.configure(k, unknown);
    rtc.enabled = header.hasRtc;
    romLoaded = true;
    reset();
    return true;
}

void Gba::reset() {
    sched.clear();
    bus.reset();
    cpu.reset();
    ppu.reset();
    apu.reset();
    dma.reset();
    timers.reset();
    save.resetState();
    rtc.reset();
    bus.updateGpioView();
    keyInput = 0x3FF;
    frameCount = 0;

    sched.schedule(EV_HBLANK, kHDrawCycles);
    sched.schedule(EV_APU_SAMPLE, kCyclesPerSample);

    if (bus.realBios) {
        cpu.setCpsr(0xD3);
        cpu.r[15] = 0 + 8;
    } else {
        bootDirect();
    }
    updateIrqLine();
}

void Gba::bootDirect() {
    // Register state as left by the BIOS boot sequence.
    cpu.setCpsr(0xD3);
    cpu.r[13] = 0x03007FE0;
    cpu.r[14] = 0;
    cpu.spsr = 0;
    cpu.setCpsr(0xD2);
    cpu.r[13] = 0x03007FA0;
    cpu.r[14] = 0;
    cpu.spsr = 0;
    cpu.setCpsr(0x1F);
    cpu.r[13] = 0x03007F00;
    for (int i = 0; i < 13; i++) cpu.r[i] = 0;
    cpu.r[14] = 0;
    cpu.r[15] = 0x08000000 + 8;
    bus.biosLatch = 0xE129F000;
    bus.io[0x300] = 1;  // POSTFLG
    bus.setIo16(0x000, 0x0080);
    // Affine BG identity matrices.
    bus.setIo16(0x020, 0x100);
    bus.setIo16(0x026, 0x100);
    bus.setIo16(0x030, 0x100);
    bus.setIo16(0x036, 0x100);
}

void Gba::setKeys(u16 pressedMask) {
    keyInput = (u16)(~pressedMask & 0x3FF);
    checkKeypadIrq();
}

void Gba::checkKeypadIrq() {
    const u16 cnt = bus.io16(0x132);
    if (!(cnt & 0x4000)) return;
    const u16 pressed = (u16)(~keyInput & 0x3FF);
    const u16 sel = cnt & 0x3FF;
    bool hit = (cnt & 0x8000) ? ((pressed & sel) == sel && sel) : ((pressed & sel) != 0);
    if (hit) raiseIrq(IRQ_KEYPAD);
}

void Gba::raiseIrq(u16 bits) {
    bus.setIo16(0x202, bus.io16(0x202) | bits);
    updateIrqLine();
}

void Gba::updateIrqLine() {
    const u16 pending = bus.io16(0x200) & bus.io16(0x202);
    if (pending) cpu.halted = false;
    cpu.irqLine = (bus.io16(0x208) & 1) && pending;
}

void Gba::processEvents() {
    for (;;) {
        u64 m = kNever;
        int e = -1;
        for (int i = 0; i < EV_COUNT; i++) {
            if (sched.when[i] < m) {
                m = sched.when[i];
                e = i;
            }
        }
        sched.next = m;
        if (e < 0 || m > sched.now) break;
        sched.when[e] = kNever;
        switch (e) {
            case EV_HBLANK:
                sched.when[EV_LINE_END] = m + (kCyclesPerLine - kHDrawCycles);
                ppu.onHBlank();
                break;
            case EV_LINE_END:
                sched.when[EV_HBLANK] = m + kHDrawCycles;
                ppu.onLineEnd();
                break;
            case EV_TIMER0:
            case EV_TIMER1:
            case EV_TIMER2:
            case EV_TIMER3: timers.onOverflowEvent(e - EV_TIMER0); break;
            case EV_APU_SAMPLE:
                sched.when[EV_APU_SAMPLE] = m + kCyclesPerSample;
                apu.sampleEvent();
                break;
            default: break;
        }
    }
}

int Gba::runFrame(u32* video, s16* audio, int maxAudioFrames) {
    if (!romLoaded) return 0;
    if (!cheats.empty()) cheats.apply();
    ppu.frameDone = false;
    // Safety bound: a frame is 280896 cycles; never loop forever.
    const u64 limit = sched.now + kCyclesPerFrame * 2;
    while (!ppu.frameDone && sched.now < limit) {
        cpu.run();
        processEvents();
    }
    frameCount++;
    if (video) std::memcpy(video, ppu.frame, sizeof(ppu.frame));
    int n = 0;
    if (audio && maxAudioFrames > 0) {
        n = (int)apu.drain(audio, (u32)maxAudioFrames);
    } else {
        apu.ringRead = apu.ringWrite;
    }
    return n;
}

// ------------------------------------------------------------------ save states

std::vector<u8> Gba::saveState() {
    StateWriter w;
    w.pod(kStateMagic);
    w.pod(kStateVersion);
    // identify the game
    w.bytes(&bus.rom[0xA0], 16);
    w.pod(sched.now);
    w.pod(sched.when);
    w.pod(keyInput);
    w.pod(frameCount);
    cpu.serialize(w);
    bus.serialize(w);
    ppu.serialize(w);
    apu.serialize(w);
    dma.serialize(w);
    timers.serialize(w);
    save.serialize(w);
    rtc.serialize(w);
    w.tag("END!");
    return w.buf;
}

bool Gba::loadState(const u8* d, size_t n) {
    if (!romLoaded || !d) return false;
    // Validate on a scratch copy first so a bad state cannot corrupt the running game.
    {
        StateReader rd(d, n);
        u32 magic = rd.get<u32>(), ver = rd.get<u32>();
        if (!rd.ok || magic != kStateMagic || ver != kStateVersion) return false;
        u8 id[16];
        rd.bytes(id, 16);
        if (!rd.ok || std::memcmp(id, &bus.rom[0xA0], 16) != 0) return false;
    }
    std::vector<u8> backup = saveState();
    StateReader rd(d, n);
    rd.get<u32>();
    rd.get<u32>();
    u8 id[16];
    rd.bytes(id, 16);
    rd.pod(sched.now);
    rd.pod(sched.when);
    rd.pod(keyInput);
    rd.pod(frameCount);
    cpu.deserialize(rd);
    bus.deserialize(rd);
    ppu.deserialize(rd);
    apu.deserialize(rd);
    dma.deserialize(rd);
    timers.deserialize(rd);
    save.deserialize(rd);
    rtc.deserialize(rd);
    rd.tag("END!");
    if (!rd.ok) {
        StateReader rb(backup.data(), backup.size());
        rb.get<u32>();
        rb.get<u32>();
        rb.bytes(id, 16);
        rb.pod(sched.now);
        rb.pod(sched.when);
        rb.pod(keyInput);
        rb.pod(frameCount);
        cpu.deserialize(rb);
        bus.deserialize(rb);
        ppu.deserialize(rb);
        apu.deserialize(rb);
        dma.deserialize(rb);
        timers.deserialize(rb);
        save.deserialize(rb);
        rtc.deserialize(rb);
        sched.recompute();
        bus.updateGpioView();
        updateIrqLine();
        return false;
    }
    sched.recompute();
    bus.updateGpioView();
    updateIrqLine();
    return true;
}

}  // namespace retra

// Retra GBA core - high level emulation of BIOS SWI functions.
// Reached through trap opcodes placed in the Retra replacement BIOS (bios/retra_bios.S).
#include <cmath>
#include <vector>

#include "bus_inl.h"
#include "gba.h"

namespace retra {

namespace {

struct SinTable {
    s16 v[256];
    SinTable() {
        for (int i = 0; i < 256; i++) v[i] = (s16)std::lround(std::sin(i * 3.14159265358979323846 * 2.0 / 256.0) * 16384.0);
    }
};
const SinTable& sinTable() {
    static const SinTable t;
    return t;
}

s32 biosArcTan(s32 i) {
    s32 a = -((i * i) >> 14);
    s32 b = ((0xA9 * a) >> 14) + 0x390;
    b = ((b * a) >> 14) + 0x91C;
    b = ((b * a) >> 14) + 0xFB6;
    b = ((b * a) >> 14) + 0x16AA;
    b = ((b * a) >> 14) + 0x2081;
    b = ((b * a) >> 14) + 0x3651;
    b = ((b * a) >> 14) + 0xA2F9;
    return (i * b) >> 16;
}

s32 biosArcTan2(s32 x, s32 y) {
    if (y == 0) return x >= 0 ? 0 : 0x8000;
    if (x == 0) return y >= 0 ? 0x4000 : 0xC000;
    if (y >= 0) {
        if (x >= 0) {
            if (x >= y) return biosArcTan((y << 14) / x);
        } else if (-x >= y) {
            return biosArcTan((y << 14) / x) + 0x8000;
        }
        return 0x4000 - biosArcTan((x << 14) / y);
    }
    if (x <= 0) {
        if (-x > -y) return biosArcTan((y << 14) / x) + 0x8000;
    } else if (x >= -y) {
        return biosArcTan((y << 14) / x) + 0x10000;
    }
    return 0xC000 - biosArcTan((x << 14) / y);
}

}  // namespace

void Gba::hleCall(u32 n) {
    Cpu& c = cpu;
    Bus& b = bus;
    u32* r = c.r;
    switch (n) {
        case 0x100:  // boot (reset vector)
        case 0x26: {  // HardReset
            bootDirect();
            c.r[15] = 0;  // will be replaced by branchTo below
            c.branchTo(0x08000000);
            return;
        }
        case 0x00: {  // SoftReset
            const u8 flag = b.peek<u8>(0x03007FFA);
            for (u32 a = 0x7E00; a < 0x8000; a++) b.iwram[a] = 0;
            c.setCpsr(0xD3);
            r[13] = 0x03007FE0;
            r[14] = 0;
            c.spsr = 0;
            c.setCpsr(0xD2);
            r[13] = 0x03007FA0;
            r[14] = 0;
            c.spsr = 0;
            c.setCpsr(0x1F);
            r[13] = 0x03007F00;
            for (int i = 0; i < 13; i++) r[i] = 0;
            r[14] = 0;
            c.branchTo(flag ? 0x02000000 : 0x08000000);
            return;
        }
        case 0x01: {  // RegisterRamReset
            const u32 f = r[0];
            b.ioWrite16(0x000, 0x0080);
            if (f & 0x01) std::memset(b.ewram, 0, sizeof(b.ewram));
            if (f & 0x02) std::memset(b.iwram, 0, 0x7E00);
            if (f & 0x04) std::memset(b.pram, 0, sizeof(b.pram));
            if (f & 0x08) std::memset(b.vram, 0, sizeof(b.vram));
            if (f & 0x10) std::memset(b.oam, 0, sizeof(b.oam));
            if (f & 0x20) {
                for (u32 a = 0x120; a < 0x160; a += 2) b.setIo16(a, 0);
                b.setIo16(0x134, 0x8000);
            }
            if (f & 0x40) {
                for (u32 a = 0x060; a < 0x0A8; a += 2) b.ioWrite16(a, 0);
                b.ioWrite16(0x084, 0);
                b.setIo16(0x088, 0x0200);
            }
            if (f & 0x80) {
                for (u32 a = 0x004; a < 0x060; a += 2) {
                    if (a == 0x006) continue;
                    b.ioWrite16(a, 0);
                }
                b.ioWrite16(0x020, 0x100);
                b.ioWrite16(0x026, 0x100);
                b.ioWrite16(0x030, 0x100);
                b.ioWrite16(0x036, 0x100);
                for (u32 a = 0x0B0; a < 0x0E0; a += 2) b.ioWrite16(a, 0);
                for (u32 a = 0x100; a < 0x110; a += 2) b.ioWrite16(a, 0);
                b.ioWrite16(0x132, 0);
                b.ioWrite16(0x200, 0);
                b.ioWrite16(0x202, 0xFFFF);
                b.ioWrite16(0x204, 0);
                b.ioWrite16(0x208, 0);
            }
            sched.now += 100;
            return;
        }
        case 0x06:    // Div
        case 0x07: {  // DivArm
            s32 num = (s32)r[0], den = (s32)r[1];
            if (n == 0x07) std::swap(num, den);
            if (den == 0) {
                r[0] = num < 0 ? (u32)-1 : 1;
                r[1] = (u32)num;
                r[3] = 1;
            } else if (num == INT32_MIN && den == -1) {
                r[0] = (u32)INT32_MIN;
                r[1] = 0;
                r[3] = 0x80000000u;
            } else {
                const s32 q = num / den;
                r[0] = (u32)q;
                r[1] = (u32)(num % den);
                r[3] = (u32)(q < 0 ? -q : q);
            }
            sched.now += 60;
            return;
        }
        case 0x08: {  // Sqrt
            u32 v = r[0], res = 0, bit = 1u << 30;
            while (bit > v) bit >>= 2;
            while (bit) {
                if (v >= res + bit) {
                    v -= res + bit;
                    res = (res >> 1) + bit;
                } else {
                    res >>= 1;
                }
                bit >>= 2;
            }
            r[0] = res;
            sched.now += 80;
            return;
        }
        case 0x09:  // ArcTan
            r[0] = (u32)biosArcTan((s32)(s16)r[0]);
            sched.now += 50;
            return;
        case 0x0A:  // ArcTan2
            r[0] = (u32)(biosArcTan2((s32)(s16)r[0], (s32)(s16)r[1]) & 0xFFFF);
            sched.now += 60;
            return;
        case 0x0B: {  // CpuSet
            u32 src = r[0], dst = r[1];
            const u32 cnt = r[2] & 0x1FFFFF;
            const bool fill = (r[2] >> 24) & 1;
            const bool word = (r[2] >> 26) & 1;
            if ((src & 0x0E000000) == 0) return;  // BIOS protection
            if (word) {
                src &= ~3u;
                dst &= ~3u;
                const u32 v0 = fill ? b.read<u32>(src) : 0;
                for (u32 i = 0; i < cnt; i++) {
                    u32 v = fill ? v0 : b.read<u32>(src + i * 4, i != 0);
                    b.write<u32>(dst + i * 4, v, i != 0);
                }
            } else {
                src &= ~1u;
                dst &= ~1u;
                const u16 v0 = fill ? b.read<u16>(src) : 0;
                for (u32 i = 0; i < cnt; i++) {
                    u16 v = fill ? v0 : b.read<u16>(src + i * 2, i != 0);
                    b.write<u16>(dst + i * 2, v, i != 0);
                }
            }
            return;
        }
        case 0x0C: {  // CpuFastSet
            u32 src = r[0] & ~3u, dst = r[1] & ~3u;
            const u32 cnt = ((r[2] & 0x1FFFFF) + 7) & ~7u;
            const bool fill = (r[2] >> 24) & 1;
            if ((src & 0x0E000000) == 0) return;
            const u32 v0 = fill ? b.read<u32>(src) : 0;
            for (u32 i = 0; i < cnt; i++) {
                u32 v = fill ? v0 : b.read<u32>(src + i * 4, (i & 7) != 0);
                b.write<u32>(dst + i * 4, v, (i & 7) != 0);
            }
            return;
        }
        case 0x0D:  // GetBiosChecksum
            r[0] = 0xBAAE187F;
            sched.now += 100;
            return;
        case 0x0E: {  // BgAffineSet
            u32 src = r[0], dst = r[1];
            const auto& st = sinTable();
            for (u32 i = 0; i < r[2]; i++) {
                const s32 ox = (s32)b.read<u32>(src);
                const s32 oy = (s32)b.read<u32>(src + 4);
                const s32 dx = (s16)b.read<u16>(src + 8);
                const s32 dy = (s16)b.read<u16>(src + 10);
                const s32 sx = (s16)b.read<u16>(src + 12);
                const s32 sy = (s16)b.read<u16>(src + 14);
                const u32 theta = (b.read<u16>(src + 16) >> 8) & 0xFF;
                const s32 sn = st.v[theta], cs = st.v[(theta + 64) & 0xFF];
                const s32 pa = (sx * cs) >> 14;
                const s32 pb = -((sx * sn) >> 14);
                const s32 pc = (sy * sn) >> 14;
                const s32 pd = (sy * cs) >> 14;
                const s32 x = ox - (pa * dx + pb * dy);
                const s32 y = oy - (pc * dx + pd * dy);
                b.write<u16>(dst, (u16)pa);
                b.write<u16>(dst + 2, (u16)pb);
                b.write<u16>(dst + 4, (u16)pc);
                b.write<u16>(dst + 6, (u16)pd);
                b.write<u32>(dst + 8, (u32)x);
                b.write<u32>(dst + 12, (u32)y);
                src += 20;
                dst += 16;
            }
            return;
        }
        case 0x0F: {  // ObjAffineSet
            u32 src = r[0], dst = r[1];
            const u32 off = r[3];
            const auto& st = sinTable();
            for (u32 i = 0; i < r[2]; i++) {
                const s32 sx = (s16)b.read<u16>(src);
                const s32 sy = (s16)b.read<u16>(src + 2);
                const u32 theta = (b.read<u16>(src + 4) >> 8) & 0xFF;
                const s32 sn = st.v[theta], cs = st.v[(theta + 64) & 0xFF];
                b.write<u16>(dst, (u16)((sx * cs) >> 14));
                b.write<u16>(dst + off, (u16)(-((sx * sn) >> 14)));
                b.write<u16>(dst + off * 2, (u16)((sy * sn) >> 14));
                b.write<u16>(dst + off * 3, (u16)((sy * cs) >> 14));
                src += 8;
                dst += off * 4;
            }
            return;
        }
        case 0x10: {  // BitUnPack
            u32 src = r[0], dst = r[1];
            const u32 info = r[2];
            const u32 len = b.read<u16>(info);
            const u32 sw = b.read<u8>(info + 2);
            const u32 dw = b.read<u8>(info + 3);
            const u32 offRaw = b.read<u32>(info + 4);
            const u32 offset = offRaw & 0x7FFFFFFF;
            const bool zeroFlag = offRaw >> 31;
            if (!(sw == 1 || sw == 2 || sw == 4 || sw == 8)) return;
            if (!(dw == 1 || dw == 2 || dw == 4 || dw == 8 || dw == 16 || dw == 32)) return;
            u32 out = 0, bits = 0;
            const u32 smask = (1u << sw) - 1;
            for (u32 i = 0; i < len; i++) {
                const u8 byte = b.read<u8>(src + i);
                for (u32 s = 0; s < 8; s += sw) {
                    u32 v = (byte >> s) & smask;
                    if (v || zeroFlag) v += offset;
                    if (dw < 32) v &= (1u << dw) - 1;
                    out |= v << bits;
                    bits += dw;
                    if (bits >= 32) {
                        b.write<u32>(dst, out);
                        dst += 4;
                        out = 0;
                        bits = 0;
                    }
                }
            }
            return;
        }
        case 0x11:    // LZ77UnCompWram
        case 0x12: {  // LZ77UnCompVram
            u32 src = r[0], dst = r[1];
            const u32 hdr = b.read<u32>(src);
            const u32 size = hdr >> 8;
            if ((src & 0x0E000000) == 0 || size == 0) return;
            src += 4;
            std::vector<u8> out;
            out.reserve(size);
            while (out.size() < size) {
                u8 flags = b.read<u8>(src++);
                for (int k = 0; k < 8 && out.size() < size; k++, flags <<= 1) {
                    if (flags & 0x80) {
                        const u8 b0 = b.read<u8>(src++), b1 = b.read<u8>(src++);
                        const u32 len = (b0 >> 4) + 3;
                        const u32 disp = (((b0 & 0xF) << 8) | b1) + 1;
                        for (u32 j = 0; j < len && out.size() < size; j++) {
                            const size_t from = out.size() >= disp ? out.size() - disp : 0;
                            out.push_back(out.empty() ? 0 : out[from]);
                        }
                    } else {
                        out.push_back(b.read<u8>(src++));
                    }
                }
            }
            if (n == 0x11) {
                for (u32 i = 0; i < size; i++) b.write<u8>(dst + i, out[i], i != 0);
            } else {
                for (u32 i = 0; i < size; i += 2) {
                    u16 v = out[i] | (u16)((i + 1 < size ? out[i + 1] : 0) << 8);
                    b.write<u16>(dst + i, v, i != 0);
                }
            }
            return;
        }
        case 0x13: {  // HuffUnComp
            u32 src = r[0] & ~3u, dst = r[1];
            const u32 hdr = b.read<u32>(src);
            const u32 size = hdr >> 8;
            u32 bitsPer = hdr & 0xF;
            if (bitsPer != 4 && bitsPer != 8) bitsPer = 8;
            const u32 treeBase = src + 4;
            const u32 treeSize = (b.read<u8>(treeBase) + 1) * 2;
            u32 stream = treeBase + treeSize;
            const u32 root = treeBase + 1;
            u32 node = root;
            u32 out = 0, outBits = 0, written = 0;
            while (written < size) {
                const u32 word = b.read<u32>(stream);
                stream += 4;
                for (int bit = 31; bit >= 0 && written < size; bit--) {
                    const u8 nv = b.read<u8>(node);
                    const u32 dir = (word >> bit) & 1;
                    const u32 child = (node & ~1u) + (nv & 0x3F) * 2 + 2 + dir;
                    const bool leaf = dir ? (nv & 0x40) : (nv & 0x80);
                    if (leaf) {
                        const u32 val = b.read<u8>(child) & ((1u << bitsPer) - 1);
                        out |= val << outBits;
                        outBits += bitsPer;
                        if (outBits == 32) {
                            b.write<u32>(dst, out);
                            dst += 4;
                            written += 4;
                            out = 0;
                            outBits = 0;
                        }
                        node = root;
                    } else {
                        node = child;
                    }
                }
            }
            return;
        }
        case 0x14:    // RLUnCompWram
        case 0x15: {  // RLUnCompVram
            u32 src = r[0], dst = r[1];
            const u32 hdr = b.read<u32>(src);
            const u32 size = hdr >> 8;
            if ((src & 0x0E000000) == 0) return;
            src += 4;
            std::vector<u8> out;
            out.reserve(size);
            while (out.size() < size) {
                const u8 flag = b.read<u8>(src++);
                if (flag & 0x80) {
                    const u32 len = (flag & 0x7F) + 3;
                    const u8 v = b.read<u8>(src++);
                    for (u32 j = 0; j < len && out.size() < size; j++) out.push_back(v);
                } else {
                    const u32 len = (flag & 0x7F) + 1;
                    for (u32 j = 0; j < len && out.size() < size; j++) out.push_back(b.read<u8>(src++));
                }
            }
            if (n == 0x14) {
                for (u32 i = 0; i < size; i++) b.write<u8>(dst + i, out[i], i != 0);
            } else {
                for (u32 i = 0; i < size; i += 2) {
                    u16 v = out[i] | (u16)((i + 1 < size ? out[i + 1] : 0) << 8);
                    b.write<u16>(dst + i, v, i != 0);
                }
            }
            return;
        }
        case 0x16:    // Diff8bitUnFilterWram
        case 0x17: {  // Diff8bitUnFilterVram
            u32 src = r[0], dst = r[1];
            const u32 size = b.read<u32>(src) >> 8;
            src += 4;
            u8 acc = 0;
            std::vector<u8> out(size);
            for (u32 i = 0; i < size; i++) {
                acc = (u8)(acc + b.read<u8>(src + i));
                out[i] = acc;
            }
            if (n == 0x16) {
                for (u32 i = 0; i < size; i++) b.write<u8>(dst + i, out[i], i != 0);
            } else {
                for (u32 i = 0; i < size; i += 2) {
                    u16 v = out[i] | (u16)((i + 1 < size ? out[i + 1] : 0) << 8);
                    b.write<u16>(dst + i, v, i != 0);
                }
            }
            return;
        }
        case 0x18: {  // Diff16bitUnFilter
            u32 src = r[0], dst = r[1];
            const u32 size = b.read<u32>(src) >> 8;
            src += 4;
            u16 acc = 0;
            for (u32 i = 0; i + 1 < size + 1 && i < size; i += 2) {
                acc = (u16)(acc + b.read<u16>(src + i));
                b.write<u16>(dst + i, acc, i != 0);
            }
            return;
        }
        case 0x19: {  // SoundBias
            u16 bias = b.io16(0x088);
            bias = (u16)((bias & ~0x3FEu) | (r[0] ? 0x200 : 0));
            b.ioWrite16(0x088, bias);
            return;
        }
        case 0x1F: {  // MidiKey2Freq
            const u32 freq = b.read<u32>(r[0] + 4);
            const double e = (180.0 - (double)r[1] - (double)(r[2] & 0xFF) / 256.0) / 12.0;
            r[0] = (u32)((double)freq / std::pow(2.0, e));
            sched.now += 100;
            return;
        }
        case 0x25:  // MultiBoot: no link partner
            r[0] = 1;
            return;
        default:
            // Sound driver functions (BIOS m4a) and other rarely used calls: no-op.
            return;
    }
}

}  // namespace retra

// Retra GBA core - PPU: scanline renderer for modes 0-5, sprites, windows, blending, mosaic.
#include "ppu.h"

#include <algorithm>
#include <cmath>

#include "gba.h"
#include "state.h"

namespace retra {

namespace {
constexpr u16 kTransparent = 0x8000;

// OBJ sizes [shape][size] -> width, height
constexpr u8 kObjW[4][4] = {{8, 16, 32, 64}, {16, 32, 32, 64}, {8, 8, 16, 32}, {8, 8, 8, 8}};
constexpr u8 kObjH[4][4] = {{8, 16, 32, 64}, {8, 8, 16, 32}, {16, 32, 32, 64}, {8, 8, 8, 8}};

// objAttr bits
constexpr u8 OA_PRIO = 0x03;
constexpr u8 OA_SEMI = 0x04;
constexpr u8 OA_OPAQUE = 0x08;
constexpr u8 OA_WIN = 0x10;
}  // namespace

Ppu::Ppu(Gba* gba) : g(gba) {
    buildLut();
    reset();
}

void Ppu::reset() {
    std::fill(std::begin(frame), std::end(frame), 0xFF000000u);
    frameDone = false;
    vcount = 0;
    refX[0] = refX[1] = refY[0] = refY[1] = 0;
}

void Ppu::setColorCorrection(bool on) {
    if (on == colorCorrection) return;
    colorCorrection = on;
    buildLut();
}

void Ppu::buildLut() {
    for (u32 c = 0; c < 32768; c++) {
        u32 r = c & 31, gr = (c >> 5) & 31, b = (c >> 10) & 31;
        u32 R, G, B;
        if (!colorCorrection) {
            R = (r << 3) | (r >> 2);
            G = (gr << 3) | (gr >> 2);
            B = (b << 3) | (b >> 2);
        } else {
            // Approximation of the GBA's reflective LCD: dark gamma, slight channel cross-talk.
            const double lr = std::pow(r / 31.0, 4.0 / 2.2 * 1.0);
            const double lg = std::pow(gr / 31.0, 4.0 / 2.2 * 1.0);
            const double lb = std::pow(b / 31.0, 4.0 / 2.2 * 1.0);
            double rr = 0.82 * lr + 0.24 * lg - 0.06 * lb;
            double gg = 0.10 * lr + 0.69 * lg + 0.21 * lb;
            double bb = 0.17 * lr + 0.12 * lg + 0.71 * lb;
            auto enc = [](double v) {
                v = v < 0 ? 0 : (v > 1 ? 1 : v);
                return (u32)std::lround(std::pow(v, 1.0 / 1.45) * 255.0);
            };
            R = enc(rr);
            G = enc(gg);
            B = enc(bb);
        }
        lut[c] = 0xFF000000u | (R << 16) | (G << 8) | B;
    }
}

static inline s32 signExtend28(u32 v) { return (s32)(v << 4) >> 4; }

void Ppu::onAffineWrite(u32 addr) {
    Bus& b = g->bus;
    const int i = addr >= 0x38 ? 1 : 0;
    const u32 base = i ? 0x38 : 0x28;
    if (addr == base || addr == base + 2)
        refX[i] = signExtend28(b.io16(base) | ((u32)b.io16(base + 2) << 16));
    else
        refY[i] = signExtend28(b.io16(base + 4) | ((u32)b.io16(base + 6) << 16));
}

void Ppu::checkVcount() {
    Bus& b = g->bus;
    u16 stat = b.io16(4);
    const bool match = vcount == (u32)(stat >> 8);
    if (match) {
        if (!(stat & 4) && (stat & 0x20)) g->raiseIrq(IRQ_VCOUNT);
        stat |= 4;
    } else {
        stat &= ~4;
    }
    b.setIo16(4, stat);
}

void Ppu::onDispstatWrite() {
    Bus& b = g->bus;
    u16 stat = b.io16(4);
    if (vcount == (u32)(stat >> 8))
        stat |= 4;
    else
        stat &= ~4;
    b.setIo16(4, stat);
}

void Ppu::onHBlank() {
    Bus& b = g->bus;
    u16 stat = b.io16(4) | 2;
    b.setIo16(4, stat);
    if (stat & 0x10) g->raiseIrq(IRQ_HBLANK);
    if (vcount < 160) {
        renderLine(vcount);
        // advance affine reference points by (PB, PD)
        refX[0] += (s16)b.io16(0x22);
        refY[0] += (s16)b.io16(0x26);
        refX[1] += (s16)b.io16(0x32);
        refY[1] += (s16)b.io16(0x36);
        g->dma.trigger(DMA_HBLANK);
    }
    if (vcount >= 2 && vcount < 162) g->dma.videoCapture(vcount);
}

void Ppu::onLineEnd() {
    Bus& b = g->bus;
    vcount = vcount + 1;
    if (vcount >= kLinesPerFrame) vcount = 0;
    b.setIo16(6, (u16)vcount);
    u16 stat = b.io16(4) & ~2;
    if (vcount == 160) {
        stat |= 1;
        b.setIo16(4, stat);
        if (stat & 8) g->raiseIrq(IRQ_VBLANK);
        // reload affine reference points
        refX[0] = signExtend28(b.io16(0x28) | ((u32)b.io16(0x2A) << 16));
        refY[0] = signExtend28(b.io16(0x2C) | ((u32)b.io16(0x2E) << 16));
        refX[1] = signExtend28(b.io16(0x38) | ((u32)b.io16(0x3A) << 16));
        refY[1] = signExtend28(b.io16(0x3C) | ((u32)b.io16(0x3E) << 16));
        g->dma.trigger(DMA_VBLANK);
        frameDone = true;
    } else {
        if (vcount == 227) stat &= ~1;
        b.setIo16(4, stat);
    }
    checkVcount();
}

// ------------------------------------------------------------------ rendering

void Ppu::renderLine(u32 y) {
    Bus& b = g->bus;
    const u16 dispcnt = b.io16(0);
    u32* out = &frame[y * 240];
    if (dispcnt & 0x80) {
        for (int x = 0; x < 240; x++) out[x] = lut[0x7FFF];
        return;
    }
    const u32 mode = dispcnt & 7;
    u32 bgEnable = (dispcnt >> 8) & 0xF;
    switch (mode) {
        case 0: break;
        case 1: bgEnable &= 0x7; break;
        case 2: bgEnable &= 0xC; break;
        case 3:
        case 4:
        case 5: bgEnable &= 0x4; break;
        default: bgEnable = 0; break;
    }

    for (int bg = 0; bg < 4; bg++) {
        if (!(bgEnable & (1u << bg))) continue;
        if (mode == 0 || (mode == 1 && bg < 2))
            renderTextBg(bg, y);
        else if (mode <= 2)
            renderAffineBg(bg, y);
        else
            renderBitmap(mode, y);
    }

    std::fill(std::begin(objLine), std::end(objLine), kTransparent);
    std::memset(objAttr, 0, sizeof(objAttr));
    if (dispcnt & 0x1000) renderObjs(y);

    buildWindows(y);
    lastBgEnable = bgEnable;
    compose(y);
}

void Ppu::applyMosaicH(u16* line, u32 mosH) {
    if (mosH <= 1) return;
    for (u32 x = 0; x < 240; x++) line[x] = line[x - (x % mosH)];
}

void Ppu::renderTextBg(int bg, u32 y) {
    Bus& b = g->bus;
    const u16 cnt = b.io16(0x08 + bg * 2);
    const u32 hofs = b.io16(0x10 + bg * 4) & 0x1FF;
    const u32 vofs = b.io16(0x12 + bg * 4) & 0x1FF;
    const u32 charBase = ((cnt >> 2) & 3) * 0x4000;
    const u32 screenBase = ((cnt >> 8) & 31) * 0x800;
    const bool c256 = cnt & 0x80;
    const u32 size = (cnt >> 14) & 3;
    const u32 wMask = (size & 1) ? 511 : 255;
    const u32 hMask = (size & 2) ? 511 : 255;
    const u16 mosaic = b.io16(0x4C);
    u32 yy = y;
    if (cnt & 0x40) {
        const u32 mv = ((mosaic >> 4) & 15) + 1;
        yy = y - (y % mv);
    }
    const u32 ty = (yy + vofs) & hMask;
    u16* line = bgLine[bg];
    const u8* vram = b.vram;
    const u8* pram = b.pram;

    u32 lastTileCol = 0xFFFFFFFF;
    u16 entry = 0;
    for (u32 x = 0; x < 240; x++) {
        const u32 tx = (x + hofs) & wMask;
        const u32 tileCol = tx >> 3;
        if (tileCol != lastTileCol) {
            lastTileCol = tileCol;
            u32 block = 0;
            if (tx >= 256) block += 1;
            if (ty >= 256) block += (size == 3) ? 2 : 1;
            const u32 addr = screenBase + block * 0x800 + ((ty >> 3) & 31) * 64 + (tileCol & 31) * 2;
            entry = loadLE<u16>(&vram[addr & 0xFFFF]);
        }
        u32 px = tx & 7, py = ty & 7;
        if (entry & 0x400) px = 7 - px;
        if (entry & 0x800) py = 7 - py;
        const u32 tile = entry & 0x3FF;
        u32 color;
        if (c256) {
            const u32 addr = charBase + tile * 64 + py * 8 + px;
            if (addr >= 0x10000) {
                line[x] = kTransparent;
                continue;
            }
            color = vram[addr];
            if (!color) {
                line[x] = kTransparent;
                continue;
            }
            line[x] = loadLE<u16>(&pram[color * 2]) & 0x7FFF;
        } else {
            const u32 addr = charBase + tile * 32 + py * 4 + (px >> 1);
            if (addr >= 0x10000) {
                line[x] = kTransparent;
                continue;
            }
            color = (vram[addr] >> ((px & 1) * 4)) & 15;
            if (!color) {
                line[x] = kTransparent;
                continue;
            }
            line[x] = loadLE<u16>(&pram[((entry >> 12) * 16 + color) * 2]) & 0x7FFF;
        }
    }
    if (cnt & 0x40) applyMosaicH(line, (mosaic & 15) + 1);
}

void Ppu::renderAffineBg(int bg, u32 y) {
    (void)y;
    Bus& b = g->bus;
    const u16 cnt = b.io16(0x08 + bg * 2);
    const int i = bg - 2;
    const u32 regBase = 0x20 + i * 0x10;
    const s32 pa = (s16)b.io16(regBase + 0);
    const s32 pc = (s16)b.io16(regBase + 4);
    s32 rx = refX[i], ry = refY[i];
    const u16 mosaic = b.io16(0x4C);
    if (cnt & 0x40) {
        const u32 mv = ((mosaic >> 4) & 15) + 1;
        const u32 back = y % mv;
        rx -= (s32)back * (s16)b.io16(regBase + 2);
        ry -= (s32)back * (s16)b.io16(regBase + 6);
    }
    const u32 charBase = ((cnt >> 2) & 3) * 0x4000;
    const u32 screenBase = ((cnt >> 8) & 31) * 0x800;
    const bool wrap = cnt & 0x2000;
    const u32 sizePx = 128u << ((cnt >> 14) & 3);
    const u32 tilesPerRow = sizePx >> 3;
    const u8* vram = b.vram;
    const u8* pram = b.pram;
    u16* line = bgLine[bg];
    for (u32 x = 0; x < 240; x++, rx += pa, ry += pc) {
        s32 tx = rx >> 8, ty = ry >> 8;
        if (wrap) {
            tx &= (s32)(sizePx - 1);
            ty &= (s32)(sizePx - 1);
        } else if (tx < 0 || ty < 0 || tx >= (s32)sizePx || ty >= (s32)sizePx) {
            line[x] = kTransparent;
            continue;
        }
        const u32 mapAddr = screenBase + (u32)(ty >> 3) * tilesPerRow + (u32)(tx >> 3);
        const u32 tile = vram[mapAddr & 0xFFFF];
        const u32 addr = charBase + tile * 64 + (u32)(ty & 7) * 8 + (u32)(tx & 7);
        const u32 color = addr < 0x10000 ? vram[addr] : 0;
        line[x] = color ? (loadLE<u16>(&pram[color * 2]) & 0x7FFF) : kTransparent;
    }
    if (cnt & 0x40) applyMosaicH(line, (mosaic & 15) + 1);
}

void Ppu::renderBitmap(u32 mode, u32 y) {
    Bus& b = g->bus;
    const u16 dispcnt = b.io16(0);
    const u16 cnt = b.io16(0x0C);
    const s32 pa = (s16)b.io16(0x20);
    const s32 pc = (s16)b.io16(0x24);
    s32 rx = refX[0], ry = refY[0];
    const u16 mosaic = b.io16(0x4C);
    if (cnt & 0x40) {
        const u32 mv = ((mosaic >> 4) & 15) + 1;
        const u32 back = y % mv;
        rx -= (s32)back * (s16)b.io16(0x22);
        ry -= (s32)back * (s16)b.io16(0x26);
    }
    const u8* vram = b.vram;
    const u8* pram = b.pram;
    u16* line = bgLine[2];
    const u32 page = (dispcnt & 0x10) ? 0xA000 : 0;
    const s32 w = mode == 5 ? 160 : 240;
    const s32 h = mode == 5 ? 128 : 160;
    for (u32 x = 0; x < 240; x++, rx += pa, ry += pc) {
        const s32 tx = rx >> 8, ty = ry >> 8;
        if (tx < 0 || ty < 0 || tx >= w || ty >= h) {
            line[x] = kTransparent;
            continue;
        }
        if (mode == 3) {
            line[x] = loadLE<u16>(&vram[(ty * 240 + tx) * 2]) & 0x7FFF;
        } else if (mode == 4) {
            const u32 idx = vram[page + ty * 240 + tx];
            line[x] = idx ? (loadLE<u16>(&pram[idx * 2]) & 0x7FFF) : kTransparent;
        } else {
            line[x] = loadLE<u16>(&vram[page + (ty * 160 + tx) * 2]) & 0x7FFF;
        }
    }
    if (cnt & 0x40) applyMosaicH(line, (mosaic & 15) + 1);
}

void Ppu::renderObjs(u32 y) {
    Bus& b = g->bus;
    const u16 dispcnt = b.io16(0);
    const bool map1d = dispcnt & 0x40;
    const bool bitmapMode = (dispcnt & 7) >= 3;
    const u16 mosaic = b.io16(0x4C);
    const u32 mosH = ((mosaic >> 8) & 15) + 1;
    const u32 mosV = ((mosaic >> 12) & 15) + 1;
    const u8* oam = b.oam;
    const u8* vram = b.vram;
    const u8* pram = b.pram;

    for (int i = 0; i < 128; i++) {
        const u16 a0 = loadLE<u16>(&oam[i * 8]);
        const u16 a1 = loadLE<u16>(&oam[i * 8 + 2]);
        const u16 a2 = loadLE<u16>(&oam[i * 8 + 4]);
        const bool affine = a0 & 0x100;
        if (!affine && (a0 & 0x200)) continue;  // disabled
        const u32 objMode = (a0 >> 10) & 3;
        if (objMode == 3) continue;
        const u32 shape = (a0 >> 14) & 3;
        const u32 sz = (a1 >> 14) & 3;
        const s32 w = kObjW[shape][sz], h = kObjH[shape][sz];
        const bool dbl = affine && (a0 & 0x200);
        const s32 bw = dbl ? w * 2 : w, bh = dbl ? h * 2 : h;
        s32 oy = a0 & 0xFF;
        if (oy + bh > 256) oy -= 256;
        s32 ly = (s32)y - oy;
        if (ly < 0 || ly >= bh) continue;
        s32 ox = a1 & 0x1FF;
        if (ox >= 240) ox -= 512;
        if (ox + bw <= 0) continue;

        const bool mos = a0 & 0x1000;
        if (mos) {
            // vertical mosaic relative to screen line
            const s32 my = (s32)y - ((s32)y % (s32)mosV);
            ly = my - oy;
            if (ly < 0) ly = 0;
        }
        const bool c256 = a0 & 0x2000;
        const u32 tileBase = a2 & 0x3FF;
        if (bitmapMode && tileBase < 512) continue;
        const u32 prio = (a2 >> 10) & 3;
        const u32 palBank = (a2 >> 12) & 15;

        s32 pa = 0x100, pb = 0, pc = 0, pd = 0x100;
        if (affine) {
            const u32 pi = (a1 >> 9) & 31;
            pa = (s16)loadLE<u16>(&oam[pi * 32 + 6]);
            pb = (s16)loadLE<u16>(&oam[pi * 32 + 14]);
            pc = (s16)loadLE<u16>(&oam[pi * 32 + 22]);
            pd = (s16)loadLE<u16>(&oam[pi * 32 + 30]);
        }
        const bool hflip = !affine && (a1 & 0x1000);
        const bool vflip = !affine && (a1 & 0x2000);
        const u32 rowTiles = map1d ? (u32)(w >> 3) * (c256 ? 2 : 1) : 32;

        const s32 x0 = ox < 0 ? 0 : ox;
        const s32 x1 = ox + bw > 240 ? 240 : ox + bw;
        const s32 cx = bw / 2, cy = bh / 2;
        const s32 dy = ly - cy;
        for (s32 sx = x0; sx < x1; sx++) {
            s32 lx = sx - ox;
            if (mos) {
                s32 mx = sx - (sx % (s32)mosH);
                lx = mx - ox;
                if (lx < 0) lx = 0;
            }
            s32 tx, ty;
            if (affine) {
                const s32 dx = lx - cx;
                tx = ((pa * dx + pb * dy) >> 8) + w / 2;
                ty = ((pc * dx + pd * dy) >> 8) + h / 2;
                if (tx < 0 || ty < 0 || tx >= w || ty >= h) continue;
            } else {
                tx = hflip ? w - 1 - lx : lx;
                ty = vflip ? h - 1 - ly : ly;
            }
            u32 tile;
            u32 color;
            if (c256) {
                tile = (tileBase & ~1u) + (u32)(ty >> 3) * rowTiles + (u32)(tx >> 3) * 2;
                const u32 addr = 0x10000 + ((tile * 32 + (u32)(ty & 7) * 8 + (u32)(tx & 7)) & 0x7FFF);
                const u32 idx = vram[addr];
                if (!idx) continue;
                color = loadLE<u16>(&pram[0x200 + idx * 2]) & 0x7FFF;
            } else {
                tile = tileBase + (u32)(ty >> 3) * rowTiles + (u32)(tx >> 3);
                const u32 addr = 0x10000 + ((tile * 32 + (u32)(ty & 7) * 4 + (u32)((tx & 7) >> 1)) & 0x7FFF);
                const u32 idx = (vram[addr] >> ((tx & 1) * 4)) & 15;
                if (!idx) continue;
                color = loadLE<u16>(&pram[0x200 + (palBank * 16 + idx) * 2]) & 0x7FFF;
            }
            if (objMode == 2) {
                objAttr[sx] |= OA_WIN;
                continue;
            }
            const u8 cur = objAttr[sx];
            if (!(cur & OA_OPAQUE) || prio < (u32)(cur & OA_PRIO)) {
                objLine[sx] = (u16)color;
                objAttr[sx] = (u8)((cur & OA_WIN) | OA_OPAQUE | prio | (objMode == 1 ? OA_SEMI : 0));
            }
        }
    }
}

void Ppu::buildWindows(u32 y) {
    Bus& b = g->bus;
    const u16 dispcnt = b.io16(0);
    if (!(dispcnt & 0xE000)) {
        std::memset(winMask, 0x3F, sizeof(winMask));
        return;
    }
    const u16 winin = b.io16(0x48), winout = b.io16(0x4A);
    std::memset(winMask, winout & 0x3F, sizeof(winMask));
    if ((dispcnt & 0x8000) && (dispcnt & 0x1000)) {
        const u8 m = (winout >> 8) & 0x3F;
        for (int x = 0; x < 240; x++)
            if (objAttr[x] & OA_WIN) winMask[x] = m;
    }
    for (int w = 1; w >= 0; w--) {
        if (!(dispcnt & (0x2000 << w))) continue;
        const u16 h = b.io16(0x40 + w * 2), v = b.io16(0x44 + w * 2);
        u32 x1 = h >> 8, x2 = h & 0xFF;
        const u32 y1 = v >> 8, y2 = v & 0xFF;
        bool inY;
        if (y1 <= y2)
            inY = y >= y1 && y < y2;
        else
            inY = y >= y1 || y < y2;
        if (!inY) continue;
        if (x2 > 240) x2 = 240;
        const u8 m = (winin >> (w * 8)) & 0x3F;
        if (x1 <= x2) {
            for (u32 x = x1; x < x2; x++) winMask[x] = m;
        } else {
            for (u32 x = 0; x < x2; x++) winMask[x] = m;
            for (u32 x = x1; x < 240; x++) winMask[x] = m;
        }
    }
}

void Ppu::compose(u32 y) {
    Bus& b = g->bus;
    u32* out = &frame[y * 240];
    const u16 backdrop = loadLE<u16>(&b.pram[0]) & 0x7FFF;
    const u16 bldcnt = b.io16(0x50);
    const u16 bldalpha = b.io16(0x52);
    const u32 eva = std::min<u32>(bldalpha & 31, 16);
    const u32 evb = std::min<u32>((bldalpha >> 8) & 31, 16);
    const u32 evy = std::min<u32>(b.io16(0x54) & 31, 16);
    const u32 blendMode = (bldcnt >> 6) & 3;
    const u32 target1 = bldcnt & 0x3F;
    const u32 target2 = (bldcnt >> 8) & 0x3F;

    // BG order by priority then index
    int order[4];
    int nbg = 0;
    u32 prio[4];
    for (int bg = 0; bg < 4; bg++) prio[bg] = b.io16(0x08 + bg * 2) & 3;
    for (u32 p = 0; p < 4; p++)
        for (int bg = 0; bg < 4; bg++)
            if ((lastBgEnable & (1u << bg)) && prio[bg] == p) order[nbg++] = bg;

    for (u32 x = 0; x < 240; x++) {
        const u32 mask = winMask[x];
        u16 col[2] = {backdrop, backdrop};
        u32 layer[2] = {5, 5};
        int n = 0;
        const u8 oa = objAttr[x];
        const bool objVisible = (oa & OA_OPAQUE) && (mask & 0x10);
        const u32 objPrio = objVisible ? (oa & OA_PRIO) : 4;
        bool objPlaced = !objVisible;
        for (int k = 0; k < nbg && n < 2; k++) {
            const int bg = order[k];
            if (!(mask & (1u << bg))) continue;
            const u16 c = bgLine[bg][x];
            if (c & kTransparent) continue;
            if (!objPlaced && objPrio <= prio[bg]) {
                col[n] = objLine[x];
                layer[n] = 4;
                n++;
                objPlaced = true;
                if (n >= 2) break;
            }
            col[n] = c;
            layer[n] = (u32)bg;
            n++;
        }
        if (!objPlaced && n < 2) {
            if (n == 0) {
                col[1] = col[0];
                layer[1] = layer[0];
            }
            col[n] = objLine[x];
            layer[n] = 4;
            n++;
            if (n == 1) {
                col[1] = backdrop;
                layer[1] = 5;
            }
        }

        u16 c = col[0];
        if (mask & 0x20) {
            const bool semi = layer[0] == 4 && (oa & OA_SEMI);
            const bool secondIsTarget = (target2 >> layer[1]) & 1;
            if (semi && secondIsTarget) {
                c = blendAlpha(col[0], col[1], eva, evb);
            } else if ((target1 >> layer[0]) & 1) {
                if (blendMode == 1) {
                    if (secondIsTarget) c = blendAlpha(col[0], col[1], eva, evb);
                } else if (blendMode == 2) {
                    c = brighten(col[0], evy);
                } else if (blendMode == 3) {
                    c = darken(col[0], evy);
                }
            }
        }
        out[x] = lut[c & 0x7FFF];
    }
}

u16 Ppu::blendAlpha(u16 a, u16 bcol, u32 eva, u32 evb) {
    u32 r = ((a & 31) * eva + (bcol & 31) * evb) >> 4;
    u32 gg = (((a >> 5) & 31) * eva + ((bcol >> 5) & 31) * evb) >> 4;
    u32 bb = (((a >> 10) & 31) * eva + ((bcol >> 10) & 31) * evb) >> 4;
    if (r > 31) r = 31;
    if (gg > 31) gg = 31;
    if (bb > 31) bb = 31;
    return (u16)(r | (gg << 5) | (bb << 10));
}

u16 Ppu::brighten(u16 a, u32 evy) {
    u32 r = a & 31, gg = (a >> 5) & 31, bb = (a >> 10) & 31;
    r += ((31 - r) * evy) >> 4;
    gg += ((31 - gg) * evy) >> 4;
    bb += ((31 - bb) * evy) >> 4;
    return (u16)(r | (gg << 5) | (bb << 10));
}

u16 Ppu::darken(u16 a, u32 evy) {
    u32 r = a & 31, gg = (a >> 5) & 31, bb = (a >> 10) & 31;
    r -= (r * evy) >> 4;
    gg -= (gg * evy) >> 4;
    bb -= (bb * evy) >> 4;
    return (u16)(r | (gg << 5) | (bb << 10));
}

void Ppu::serialize(StateWriter& w) const {
    w.tag("PPU0");
    w.pod(vcount);
    w.pod(refX);
    w.pod(refY);
}

void Ppu::deserialize(StateReader& rd) {
    rd.tag("PPU0");
    rd.pod(vcount);
    rd.pod(refX);
    rd.pod(refY);
    if (vcount >= kLinesPerFrame) vcount = 0;
}

}  // namespace retra

