// Retra GBA core - DMA controller.
#include "dma.h"

#include "bus_inl.h"
#include "gba.h"
#include "state.h"

namespace retra {

static constexpr u32 kSrcMask[4] = {0x07FFFFFF, 0x0FFFFFFF, 0x0FFFFFFF, 0x0FFFFFFF};
static constexpr u32 kDstMask[4] = {0x07FFFFFF, 0x07FFFFFF, 0x07FFFFFF, 0x0FFFFFFF};

void Dma::reset() {
    for (auto& ch : c) ch = Channel{};
    running = false;
    pending = 0;
}

void Dma::writeControl(int ch, u16 value) {
    Channel& d = c[ch];
    const bool was = d.cnt & 0x8000;
    d.cnt = value & (ch == 3 ? 0xFFE0 : 0xF7E0);
    g->bus.setIo16(0xBA + ch * 12, d.cnt);
    if (!(d.cnt & 0x8000)) {
        pending &= ~(1u << ch);
        return;
    }
    if (!was) start(ch);
}

void Dma::start(int ch) {
    Channel& d = c[ch];
    Bus& b = g->bus;
    const u32 base = 0xB0 + ch * 12;
    d.src = (b.io16(base) | ((u32)b.io16(base + 2) << 16)) & kSrcMask[ch];
    d.dst = (b.io16(base + 4) | ((u32)b.io16(base + 6) << 16)) & kDstMask[ch];
    u32 count = b.io16(base + 8);
    if (ch < 3) count &= 0x3FFF;
    if (count == 0) count = ch == 3 ? 0x10000 : 0x4000;
    d.count = count;
    const u32 timing = (d.cnt >> 12) & 3;
    d.fifoMode = timing == DMA_SPECIAL && (ch == 1 || ch == 2);
    if (timing == DMA_NOW) {
        pending |= 1u << ch;
        runPending();
    }
}

void Dma::trigger(DmaTiming timing) {
    bool any = false;
    for (int ch = 0; ch < 4; ch++) {
        const Channel& d = c[ch];
        if ((d.cnt & 0x8000) && ((d.cnt >> 12) & 3) == timing) {
            pending |= 1u << ch;
            any = true;
        }
    }
    if (any) runPending();
}

void Dma::requestFifo(int fifo) {
    const u32 addr = 0x040000A0 + fifo * 4;
    for (int ch = 1; ch <= 2; ch++) {
        const Channel& d = c[ch];
        if ((d.cnt & 0x8000) && d.fifoMode && d.dst == addr) {
            pending |= 1u << ch;
            runPending();
            return;
        }
    }
}

void Dma::videoCapture(u32 vcount) {
    Channel& d = c[3];
    if (!(d.cnt & 0x8000) || ((d.cnt >> 12) & 3) != DMA_SPECIAL) return;
    if (vcount == 161) {
        d.cnt &= ~0x8000;
        g->bus.setIo16(0xDE, d.cnt);
        return;
    }
    pending |= 1u << 3;
    runPending();
}

void Dma::runPending() {
    if (running) return;
    running = true;
    while (pending) {
        const int ch = __builtin_ctz(pending);
        pending &= ~(1u << ch);
        if (c[ch].cnt & 0x8000) transfer(ch);
    }
    running = false;
}

void Dma::transfer(int ch) {
    Channel& d = c[ch];
    Bus& b = g->bus;
    const u32 timing = (d.cnt >> 12) & 3;
    const u32 dstCtl = (d.cnt >> 5) & 3;
    u32 srcCtl = (d.cnt >> 7) & 3;
    bool word = d.cnt & 0x400;
    u32 count = d.count;
    if (d.fifoMode) {
        word = true;
        count = 4;
    }
    const u32 unit = word ? 4 : 2;
    if (d.src >= 0x08000000 && d.src < 0x0E000000) srcCtl = 0;  // ROM: always increments
    const s32 srcStep = srcCtl == 0 ? (s32)unit : (srcCtl == 1 ? -(s32)unit : 0);
    s32 dstStep = (dstCtl == 0 || dstCtl == 3) ? (s32)unit : (dstCtl == 1 ? -(s32)unit : 0);
    if (d.fifoMode) dstStep = 0;

    if (ch == 3 && (d.dst >> 24) == 0xD && g->save.isEeprom()) g->save.eepromDmaHint(count);

    g->sched.now += 2;
    u32 src = d.src, dst = d.dst;
    for (u32 i = 0; i < count; i++) {
        const bool seq = i != 0;
        if (word) {
            u32 v;
            if (src >= 0x02000000) {
                v = b.read<u32>(src, seq);
                b.dmaLatch = v;
            } else {
                g->sched.now += 1;
                v = b.dmaLatch;
            }
            b.write<u32>(dst, v, seq);
        } else {
            u16 v;
            if (src >= 0x02000000) {
                v = b.read<u16>(src, seq);
                b.dmaLatch = v | ((u32)v << 16);
            } else {
                g->sched.now += 1;
                v = (u16)(b.dmaLatch >> ((dst & 2) * 8));
            }
            b.write<u16>(dst, v, seq);
        }
        src += (u32)srcStep;
        dst += (u32)dstStep;
    }
    d.src = src & kSrcMask[ch];
    d.dst = dst & kDstMask[ch];

    if (d.cnt & 0x4000) g->raiseIrq((u16)(IRQ_DMA0 << ch));

    if ((d.cnt & 0x200) && timing != DMA_NOW) {
        // repeat: reload count (and destination when "increment/reload")
        const u32 base = 0xB0 + ch * 12;
        u32 cnt = b.io16(base + 8);
        if (ch < 3) cnt &= 0x3FFF;
        if (cnt == 0) cnt = ch == 3 ? 0x10000 : 0x4000;
        d.count = cnt;
        if (dstCtl == 3) d.dst = (b.io16(base + 4) | ((u32)b.io16(base + 6) << 16)) & kDstMask[ch];
    } else {
        d.cnt &= ~0x8000;
        b.setIo16(0xBA + ch * 12, d.cnt);
    }
}

void Dma::serialize(StateWriter& w) const {
    w.tag("DMA0");
    w.pod(c);
    w.pod(pending);
}

void Dma::deserialize(StateReader& rd) {
    rd.tag("DMA0");
    rd.pod(c);
    rd.pod(pending);
    running = false;
}

}  // namespace retra

// Retra GBA core - timers. Counters are evaluated lazily from the scheduler clock;
// overflow events are only scheduled when something observes them (IRQ, cascade, sound FIFO).
#include "timer.h"

#include "gba.h"
#include "state.h"

namespace retra {

static constexpr u32 kShift[4] = {0, 6, 8, 10};

void Timers::reset() {
    for (auto& tm : t) tm = Timer{};
}

void Timers::syncCounter(int i) {
    Timer& tm = t[i];
    if (!tm.running) return;
    const u64 now = g->sched.now;
    if (now <= tm.start) return;
    const u64 ticks = (now - tm.start) >> tm.shift;
    if (!ticks) return;
    u64 v = (u64)tm.counter + ticks;
    if (v >= 0x10000) {
        const u64 period = 0x10000 - tm.reload;
        v = tm.reload + (v - 0x10000) % period;
    }
    tm.counter = (u16)v;
    tm.start += ticks << tm.shift;
}

u16 Timers::readCounter(int i) {
    syncCounter(i);
    return t[i].counter;
}

bool Timers::needsEvents(int i) const {
    const Timer& tm = t[i];
    if (!tm.running) return false;
    if (tm.control & 0x40) return true;
    if (i < 3 && (t[i + 1].control & 0x80) && t[i + 1].cascade) return true;
    return g->apu.timerUsedForFifo(i);
}

void Timers::schedule(int i) {
    Timer& tm = t[i];
    if (needsEvents(i)) {
        syncCounter(i);
        const u64 when = tm.start + ((u64)(0x10000 - tm.counter) << tm.shift);
        g->sched.schedule(EV_TIMER0 + i, when);
        tm.scheduled = true;
    } else if (tm.scheduled) {
        tm.scheduled = false;
        g->sched.cancel(EV_TIMER0 + i);
    }
}

void Timers::reschedule() {
    for (int i = 0; i < 4; i++) schedule(i);
}

void Timers::writeControl(int i, u16 v) {
    Timer& tm = t[i];
    syncCounter(i);
    const bool was = tm.control & 0x80;
    tm.control = v & 0xC7;
    tm.shift = kShift[v & 3];
    tm.cascade = i > 0 && (v & 4);
    const bool enabled = v & 0x80;
    if (!was && enabled) {
        tm.counter = tm.reload;
        tm.start = g->sched.now;
    } else if (enabled && tm.running && tm.cascade) {
        // switched to cascade: counter freezes at current value
    } else if (enabled && !tm.running && !tm.cascade) {
        tm.start = g->sched.now;  // switched from cascade to free running
    }
    tm.running = enabled && !tm.cascade;
    reschedule();
}

void Timers::onOverflowEvent(int i) {
    Timer& tm = t[i];
    tm.scheduled = false;
    if (!tm.running) return;
    const u64 when = tm.start + ((u64)(0x10000 - tm.counter) << tm.shift);
    tm.counter = tm.reload;
    tm.start = when;
    overflow(i, 1);
    schedule(i);
}

void Timers::overflow(int i, u32 times) {
    (void)times;
    Timer& tm = t[i];
    if (tm.control & 0x40) g->raiseIrq((u16)(IRQ_TIMER0 << i));
    if (i < 2) g->apu.onTimerOverflow(i);
    if (i < 3) {
        Timer& nx = t[i + 1];
        if ((nx.control & 0x80) && nx.cascade) {
            if (nx.counter == 0xFFFF) {
                nx.counter = nx.reload;
                overflow(i + 1, 1);
            } else {
                nx.counter++;
            }
        }
    }
}

void Timers::serialize(StateWriter& w) const {
    w.tag("TMR0");
    w.pod(t);
}

void Timers::deserialize(StateReader& rd) {
    rd.tag("TMR0");
    rd.pod(t);
}

}  // namespace retra

// Retra GBA core - APU. PSG channels are integrated over each 512-cycle output period
// (box filter, avoids most aliasing); Direct Sound FIFOs are sample-and-hold like hardware.
#include "apu.h"

#include "gba.h"
#include "state.h"

namespace retra {

static constexpr u8 kDuty[4] = {0x01, 0x81, 0x87, 0x7E};

void Apu::reset() {
    sq[0] = SquareCh{};
    sq[1] = SquareCh{};
    wave = WaveCh{};
    noise = NoiseCh{};
    seqStep = 0;
    seqCycles = 0;
    master = false;
    for (auto& f : fifo) f = Fifo{};
    std::memset(waveRam, 0, sizeof(waveRam));
    std::memset(ring, 0, sizeof(ring));
    ringWrite = ringRead = 0;
}

bool Apu::timerUsedForFifo(int timer) const {
    if (!master || timer > 1) return false;
    const u16 h = g->bus.io16(0x82);
    if ((h & 0x0300) && (u32)((h >> 10) & 1) == (u32)timer) return true;
    if ((h & 0x3000) && (u32)((h >> 14) & 1) == (u32)timer) return true;
    return false;
}

u16 Apu::read16(u32 addr) {
    Bus& b = g->bus;
    switch (addr) {
        case 0x60: return b.io16(addr) & 0x007F;
        case 0x62: return b.io16(addr) & 0xFFC0;
        case 0x64: return b.io16(addr) & 0x4000;
        case 0x68: return b.io16(addr) & 0xFFC0;
        case 0x6C: return b.io16(addr) & 0x4000;
        case 0x70: return b.io16(addr) & 0x00E0;
        case 0x72: return b.io16(addr) & 0xE000;
        case 0x74: return b.io16(addr) & 0x4000;
        case 0x78: return b.io16(addr) & 0xFF00;
        case 0x7C: return b.io16(addr) & 0x40FF;
        case 0x80: return b.io16(addr) & 0xFF77;
        case 0x82: return b.io16(addr) & 0x770F;
        case 0x84:
            return (u16)((master ? 0x80 : 0) | (sq[0].on ? 1 : 0) | (sq[1].on ? 2 : 0) | (wave.on ? 4 : 0) |
                         (noise.on ? 8 : 0));
        case 0x88: return b.io16(addr);
        default:
            if (addr >= 0x90 && addr < 0xA0) {
                const u32 o = addr - 0x90;
                const u8* bank = waveRam[wave.bank ^ 1];
                return (u16)(bank[o] | (bank[o + 1] << 8));
            }
            return 0;
    }
}

void Apu::write16(u32 addr, u16 v) {
    Bus& b = g->bus;
    if (addr >= 0x90 && addr < 0xA0) {
        u8* bank = waveRam[wave.bank ^ 1];
        bank[addr - 0x90] = (u8)v;
        bank[addr - 0x90 + 1] = (u8)(v >> 8);
        return;
    }
    if (addr == 0x84) {
        const bool on = v & 0x80;
        if (master && !on) {
            for (u32 a = 0x60; a < 0x82; a += 2) b.setIo16(a, 0);
            sq[0] = SquareCh{};
            sq[1] = SquareCh{};
            const bool bank = wave.bank;
            wave = WaveCh{};
            wave.bank = bank;
            noise = NoiseCh{};
        }
        master = on;
        b.setIo16(0x84, v & 0x80);
        g->timers.reschedule();
        return;
    }
    if (addr == 0x88) {
        b.setIo16(0x88, v & 0xC3FE);
        return;
    }
    if (addr == 0x82) {
        b.setIo16(0x82, v & 0x770F);
        if (v & 0x0800) fifoReset(0);
        if (v & 0x8000) fifoReset(1);
        g->timers.reschedule();
        return;
    }
    if (!master) return;  // PSG registers are read-only while the APU is off
    const bool trigger = v & 0x8000;
    switch (addr) {
        case 0x60: {
            b.setIo16(addr, v);
            SquareCh& c = sq[0];
            c.sweepShift = v & 7;
            c.sweepNeg = (v >> 3) & 1;
            c.sweepPeriod = (v >> 4) & 7;
            break;
        }
        case 0x62:
        case 0x68: {
            b.setIo16(addr, v);
            SquareCh& c = sq[addr == 0x62 ? 0 : 1];
            c.length = 64 - (v & 63);
            c.duty = (v >> 6) & 3;
            c.env.load(v);
            if (!c.env.dacOn()) c.on = false;
            break;
        }
        case 0x64:
        case 0x6C: {
            b.setIo16(addr, v & 0x7FFF);
            const int i = addr == 0x64 ? 0 : 1;
            SquareCh& c = sq[i];
            c.freq = v & 0x7FF;
            c.lengthEnable = v & 0x4000;
            if (trigger) triggerSquare(i);
            break;
        }
        case 0x70:
            b.setIo16(addr, v);
            wave.dim64 = v & 0x20;
            wave.bank = (v >> 6) & 1;
            wave.dac = v & 0x80;
            if (!wave.dac) wave.on = false;
            break;
        case 0x72:
            b.setIo16(addr, v);
            wave.length = 256 - (v & 0xFF);
            wave.volCode = (v >> 13) & 3;
            wave.force75 = v & 0x8000;
            break;
        case 0x74:
            b.setIo16(addr, v & 0x7FFF);
            wave.freq = v & 0x7FF;
            wave.lengthEnable = v & 0x4000;
            if (trigger) triggerWave();
            break;
        case 0x78:
            b.setIo16(addr, v);
            noise.length = 64 - (v & 63);
            noise.env.load(v);
            if (!noise.env.dacOn()) noise.on = false;
            break;
        case 0x7C: {
            b.setIo16(addr, v & 0x7FFF);
            const u32 r = v & 7, s = (v >> 4) & 15;
            noise.narrow = v & 8;
            noise.period = (r ? (r << 6) : 32u) << s;
            noise.lengthEnable = v & 0x4000;
            if (trigger) triggerNoise();
            break;
        }
        case 0x80: b.setIo16(addr, v & 0xFF77); break;
        default: b.setIo16(addr, v); break;
    }
}

void Apu::triggerSquare(int i) {
    SquareCh& c = sq[i];
    c.on = c.env.dacOn();
    if (c.length == 0) c.length = 64;
    c.timer = (s32)((2048 - c.freq) * 16);
    c.env.trigger();
    if (i == 0) {
        c.shadow = c.freq;
        c.sweepTimer = c.sweepPeriod ? c.sweepPeriod : 8;
        c.sweepOn = c.sweepPeriod || c.sweepShift;
        if (c.sweepShift && sweepCalc() > 2047) c.on = false;
    }
}

void Apu::triggerWave() {
    wave.on = wave.dac;
    if (wave.length == 0) wave.length = 256;
    wave.timer = (s32)((2048 - wave.freq) * 8);
    wave.pos = 0;
}

void Apu::triggerNoise() {
    noise.on = noise.env.dacOn();
    if (noise.length == 0) noise.length = 64;
    noise.env.trigger();
    noise.lfsr = noise.narrow ? 0x7F : 0x7FFF;
    noise.timer = (s32)noise.period;
}

u32 Apu::sweepCalc() {
    SquareCh& c = sq[0];
    const u32 d = c.shadow >> c.sweepShift;
    return c.sweepNeg ? c.shadow - d : c.shadow + d;
}

void Apu::clockLength() {
    for (auto& c : sq)
        if (c.lengthEnable && c.length && --c.length == 0) c.on = false;
    if (wave.lengthEnable && wave.length && --wave.length == 0) wave.on = false;
    if (noise.lengthEnable && noise.length && --noise.length == 0) noise.on = false;
}

void Apu::clockSweep() {
    SquareCh& c = sq[0];
    if (--c.sweepTimer == 0) {
        c.sweepTimer = c.sweepPeriod ? c.sweepPeriod : 8;
        if (c.sweepOn && c.sweepPeriod) {
            const u32 nf = sweepCalc();
            if (nf > 2047) {
                c.on = false;
            } else if (c.sweepShift) {
                c.shadow = nf;
                c.freq = nf;
                if (sweepCalc() > 2047) c.on = false;
            }
        }
    }
}

void Apu::clockEnvelope() {
    sq[0].env.clock();
    sq[1].env.clock();
    noise.env.clock();
}

// Returns the channel output integrated over 'cycles' (amplitude units * cycles).
s32 Apu::squareOut(int i, u32 cycles) {
    SquareCh& c = sq[i];
    const u32 period = (2048 - c.freq) * 16;
    if (!c.on) {
        // keep phase running
        return 0;
    }
    const s32 vol = (s32)c.env.vol;
    const u8 pattern = kDuty[c.duty];
    s32 acc = 0;
    u32 rem = cycles;
    while (rem) {
        const u32 step = (u32)c.timer < rem ? (u32)c.timer : rem;
        acc += ((pattern >> c.pos) & 1) ? vol * (s32)step : -vol * (s32)step;
        c.timer -= (s32)step;
        rem -= step;
        if (c.timer <= 0) {
            c.timer += (s32)period;
            c.pos = (c.pos + 1) & 7;
        }
    }
    return acc;
}

s32 Apu::waveOut(u32 cycles) {
    if (!wave.on) return 0;
    static constexpr s32 kVolMul[4] = {0, 4, 2, 1};
    const s32 mul = wave.force75 ? 3 : kVolMul[wave.volCode];
    const u32 period = (2048 - wave.freq) * 8;
    s32 acc = 0;
    u32 rem = cycles;
    while (rem) {
        const u32 step = (u32)wave.timer < rem ? (u32)wave.timer : rem;
        const u32 bankSel = wave.dim64 ? (wave.bank ^ (wave.pos >> 5)) : wave.bank;
        const u32 idx = wave.pos & 31;
        const u8 byte = waveRam[bankSel][idx >> 1];
        const s32 s = (idx & 1) ? (byte & 15) : (byte >> 4);
        acc += ((2 * s - 15) * mul / 4) * (s32)step;
        wave.timer -= (s32)step;
        rem -= step;
        if (wave.timer <= 0) {
            wave.timer += (s32)period;
            wave.pos = (wave.pos + 1) & (wave.dim64 ? 63 : 31);
        }
    }
    return acc;
}

s32 Apu::noiseOut(u32 cycles) {
    if (!noise.on) return 0;
    const s32 vol = (s32)noise.env.vol;
    s32 acc = 0;
    u32 rem = cycles;
    while (rem) {
        const u32 step = (u32)noise.timer < rem ? (u32)noise.timer : rem;
        acc += (noise.lfsr & 1) ? -vol * (s32)step : vol * (s32)step;
        noise.timer -= (s32)step;
        rem -= step;
        if (noise.timer <= 0) {
            noise.timer += (s32)noise.period;
            const u32 bit = (noise.lfsr ^ (noise.lfsr >> 1)) & 1;
            noise.lfsr = (noise.lfsr >> 1) | (bit << 14);
            if (noise.narrow) noise.lfsr = (noise.lfsr & ~0x40u) | (bit << 6);
        }
    }
    return acc;
}

void Apu::fifoReset(int ch) {
    Fifo& f = fifo[ch];
    f.r = f.w = f.count = 0;
}

void Apu::fifoWrite(int ch, const u8* bytes, int n) {
    Fifo& f = fifo[ch];
    for (int i = 0; i < n; i++) {
        if (f.count >= 32) {
            // overflow: hardware drops the FIFO contents
            f.r = f.w = f.count = 0;
        }
        f.data[f.w] = (s8)bytes[i];
        f.w = (f.w + 1) & 31;
        f.count++;
    }
}

void Apu::onTimerOverflow(int timer) {
    if (!master) return;
    const u16 h = g->bus.io16(0x82);
    for (int ch = 0; ch < 2; ch++) {
        const u32 sel = (h >> (10 + ch * 4)) & 1;
        if (sel != (u32)timer) continue;
        if (!(h & (0x300 << (ch * 4)))) continue;
        Fifo& f = fifo[ch];
        if (f.count) {
            f.cur = f.data[f.r];
            f.r = (f.r + 1) & 31;
            f.count--;
        }
        if (f.count <= 16) g->dma.requestFifo(ch);
    }
}

void Apu::sampleEvent() {
    Bus& b = g->bus;
    s32 left = 0, right = 0;
    if (master) {
        const u32 cyc = kCyclesPerSample;
        s32 o[4];
        o[0] = squareOut(0, cyc);
        o[1] = squareOut(1, cyc);
        o[2] = waveOut(cyc);
        o[3] = noiseOut(cyc);
        const u16 l = b.io16(0x80);
        const u16 h = b.io16(0x82);
        s32 pr = 0, pl = 0;
        for (int i = 0; i < 4; i++) {
            if (l & (0x100 << i)) pr += o[i];
            if (l & (0x1000 << i)) pl += o[i];
        }
        // average over the period, apply master volume (1..8)
        pr = pr * (s32)((l & 7) + 1) / (s32)cyc;
        pl = pl * (s32)(((l >> 4) & 7) + 1) / (s32)cyc;
        const u32 ratio = h & 3;
        const int psgShift = ratio == 0 ? 2 : (ratio == 1 ? 1 : 0);
        right = pr >> psgShift;
        left = pl >> psgShift;
        for (int ch = 0; ch < 2; ch++) {
            const s32 s = (s32)fifo[ch].cur * ((h & (4 << ch)) ? 4 : 2);
            if (h & (0x100 << (ch * 4))) right += s;
            if (h & (0x200 << (ch * 4))) left += s;
        }
    }
    // frame sequencer (512 Hz)
    seqCycles += kCyclesPerSample;
    if (seqCycles >= 32768) {
        seqCycles -= 32768;
        switch (seqStep) {
            case 0:
            case 4: clockLength(); break;
            case 2:
            case 6:
                clockLength();
                clockSweep();
                break;
            case 7: clockEnvelope(); break;
            default: break;
        }
        seqStep = (seqStep + 1) & 7;
    }
    const s32 bias = b.io16(0x88) & 0x3FE;
    auto out = [bias](s32 v) -> s16 {
        s32 t = v + bias;
        if (t < 0) t = 0;
        if (t > 0x3FF) t = 0x3FF;
        s32 o = (t - bias) * 64;
        if (o > 32767) o = 32767;
        if (o < -32768) o = -32768;
        return (s16)o;
    };
    if (ringWrite - ringRead >= kRing) ringRead = ringWrite - kRing + 1;
    const u32 idx = (ringWrite % kRing) * 2;
    ring[idx] = out(left);
    ring[idx + 1] = out(right);
    ringWrite++;
}

u32 Apu::drain(s16* out, u32 maxFrames) {
    u32 n = available();
    if (n > maxFrames) {
        // keep the newest samples
        ringRead = ringWrite - maxFrames;
        n = maxFrames;
    }
    for (u32 i = 0; i < n; i++) {
        const u32 idx = ((ringRead + i) % kRing) * 2;
        out[i * 2] = ring[idx];
        out[i * 2 + 1] = ring[idx + 1];
    }
    ringRead += n;
    return n;
}

void Apu::serialize(StateWriter& w) const {
    w.tag("APU0");
    w.pod(sq);
    w.pod(wave);
    w.pod(noise);
    w.pod(seqStep);
    w.pod(seqCycles);
    w.pod(master);
    w.pod(fifo);
    w.pod(waveRam);
}

void Apu::deserialize(StateReader& rd) {
    rd.tag("APU0");
    rd.pod(sq);
    rd.pod(wave);
    rd.pod(noise);
    rd.pod(seqStep);
    rd.pod(seqCycles);
    rd.pod(master);
    rd.pod(fifo);
    rd.pod(waveRam);
    for (auto& f : fifo) {
        f.r &= 31;
        f.w &= 31;
        if (f.count > 32) f.count = 0;
    }
    seqStep &= 7;
    ringRead = ringWrite;
}

}  // namespace retra

// Retra GBA core - cartridge backup memory.
#include "cart_save.h"

#include "gba.h"
#include "state.h"

namespace retra {

static constexpr u8 kFlash64Maker = 0x32, kFlash64Device = 0x1B;    // Panasonic MN63F805MNP
static constexpr u8 kFlash128Maker = 0xC2, kFlash128Device = 0x09;  // Macronix MX29L010

SaveKind CartSave::detect(const u8* rom, size_t size, bool* eepromUnknownSize) {
    if (eepromUnknownSize) *eepromUnknownSize = false;
    // Library ID strings are word aligned in practice; scan aligned first, then unaligned.
    struct Sig {
        const char* s;
        SaveKind k;
    };
    static const Sig sigs[] = {
        {"EEPROM_V", SaveKind::EEPROM_8K}, {"SRAM_F_V", SaveKind::SRAM},      {"SRAM_V", SaveKind::SRAM},
        {"FLASH1M_V", SaveKind::FLASH_128K}, {"FLASH512_V", SaveKind::FLASH_64K}, {"FLASH_V", SaveKind::FLASH_64K},
    };
    for (int pass = 0; pass < 2; pass++) {
        const size_t stepSize = pass == 0 ? 4 : 1;
        for (size_t i = 0; i + 12 <= size; i += stepSize) {
            const u8 c0 = rom[i];
            if (c0 != 'E' && c0 != 'S' && c0 != 'F') continue;
            for (const Sig& sg : sigs) {
                const size_t n = std::strlen(sg.s);
                if (i + n <= size && std::memcmp(rom + i, sg.s, n) == 0) {
                    if (sg.k == SaveKind::EEPROM_8K && eepromUnknownSize) *eepromUnknownSize = true;
                    return sg.k;
                }
            }
        }
    }
    return SaveKind::NONE;
}

void CartSave::configure(SaveKind k, bool eepromUnknown) {
    kind = k;
    eepromSizeUnknown = eepromUnknown && isEeprom();
    size_t n = 0;
    switch (k) {
        case SaveKind::SRAM: n = 0x8000; break;
        case SaveKind::FLASH_64K: n = 0x10000; break;
        case SaveKind::FLASH_128K: n = 0x20000; break;
        case SaveKind::EEPROM_512: n = 512; break;
        case SaveKind::EEPROM_8K: n = 8192; break;
        default: n = 0; break;
    }
    data.assign(n, 0xFF);
    dirty = false;
    resetState();
}

void CartSave::resetState() {
    flashState = 0;
    flashId = flashErasePrep = flashWriteNext = flashBankNext = false;
    flashBank = 0;
    eepState = 0;
    eepBits = 0;
    eepBuffer = 0;
    eepAddr = 0;
    eepCmd = 0;
    eepReadData = 0;
    eepReadPos = 0;
}

size_t CartSave::saveSize() const { return data.size(); }

bool CartSave::load(const u8* d, size_t n) {
    if (!d || n == 0 || kind == SaveKind::NONE) return false;
    if (isFlash()) {
        if (n >= 0x20000 && kind == SaveKind::FLASH_64K) configure(SaveKind::FLASH_128K, false);
        else if (n >= 0x10000 && n < 0x20000 && kind == SaveKind::FLASH_128K) configure(SaveKind::FLASH_64K, false);
    } else if (isEeprom()) {
        if (n >= 8192) configure(SaveKind::EEPROM_8K, false);
        else if (n >= 512) configure(SaveKind::EEPROM_512, false);
    }
    const size_t m = n < data.size() ? n : data.size();
    std::memcpy(data.data(), d, m);
    dirty = false;
    return true;
}

u8 CartSave::read8(u32 addr) {
    if (kind == SaveKind::SRAM) return data[addr & 0x7FFF];
    if (isFlash()) {
        const u32 off = addr & 0xFFFF;
        if (flashId && off < 2) {
            if (kind == SaveKind::FLASH_128K) return off == 0 ? kFlash128Maker : kFlash128Device;
            return off == 0 ? kFlash64Maker : kFlash64Device;
        }
        return data[(flashBank * 0x10000 + off) % data.size()];
    }
    return 0xFF;
}

void CartSave::write8(u32 addr, u8 v) {
    if (kind == SaveKind::SRAM) {
        u8& d = data[addr & 0x7FFF];
        if (d != v) {
            d = v;
            dirty = true;
        }
        return;
    }
    if (!isFlash()) return;
    const u32 off = addr & 0xFFFF;
    if (flashWriteNext) {
        data[(flashBank * 0x10000 + off) % data.size()] = v;
        flashWriteNext = false;
        dirty = true;
        return;
    }
    if (flashBankNext) {
        flashBankNext = false;
        if (off == 0) {
            flashBank = (kind == SaveKind::FLASH_128K) ? (v & 1) : 0;
            return;
        }
    }
    switch (flashState) {
        case 0:
            if (off == 0x5555 && v == 0xAA)
                flashState = 1;
            else if (v == 0xF0)
                flashId = false;
            break;
        case 1: flashState = (off == 0x2AAA && v == 0x55) ? 2 : 0; break;
        case 2:
            flashState = 0;
            if (off == 0x5555) {
                switch (v) {
                    case 0x90: flashId = true; break;
                    case 0xF0: flashId = false; break;
                    case 0x80: flashErasePrep = true; break;
                    case 0x10:
                        if (flashErasePrep) {
                            std::fill(data.begin(), data.end(), 0xFF);
                            dirty = true;
                        }
                        flashErasePrep = false;
                        break;
                    case 0xA0: flashWriteNext = true; break;
                    case 0xB0: flashBankNext = kind == SaveKind::FLASH_128K; break;
                    default: break;
                }
            } else if (flashErasePrep && v == 0x30) {
                const u32 base = (flashBank * 0x10000 + (off & 0xF000)) % data.size();
                std::fill(data.begin() + base, data.begin() + base + 0x1000, 0xFF);
                flashErasePrep = false;
                dirty = true;
            }
            break;
    }
}

void CartSave::eepromDmaHint(u32 count) {
    if (!eepromSizeUnknown) return;
    if (count == 9 || count == 73) {
        eepromSizeUnknown = false;
        kind = SaveKind::EEPROM_512;
        data.resize(512);
    } else if (count == 17 || count == 81) {
        eepromSizeUnknown = false;
        kind = SaveKind::EEPROM_8K;
        data.resize(8192, 0xFF);
    }
}

u16 CartSave::eepromRead() {
    if (eepState == 4) {
        u16 bit = 0;
        if (eepReadPos >= 4) bit = (u16)((eepReadData >> (63 - (eepReadPos - 4))) & 1);
        if (++eepReadPos >= 68) eepState = 0;
        return bit;
    }
    return 1;  // ready
}

void CartSave::eepromWrite(u16 v) {
    const u32 bit = v & 1;
    if (eepState == 4) {
        // A new command interrupts a pending read.
        eepState = 0;
        eepBits = 0;
        eepBuffer = 0;
    }
    switch (eepState) {
        case 0:
            eepBuffer = (eepBuffer << 1) | bit;
            if (++eepBits == 2) {
                eepCmd = (u32)(eepBuffer & 3);
                eepBits = 0;
                eepBuffer = 0;
                if (eepCmd == 3 || eepCmd == 2) eepState = 1;
            }
            break;
        case 1:
            eepBuffer = (eepBuffer << 1) | bit;
            if (++eepBits == eepAddrBits()) {
                const u32 blocks = (u32)(data.size() / 8);
                eepAddr = (u32)(eepBuffer % (blocks ? blocks : 1));
                eepBits = 0;
                eepBuffer = 0;
                eepState = eepCmd == 3 ? 2 : 3;
            }
            break;
        case 2: {  // end bit of read request
            u64 d = 0;
            for (int i = 0; i < 8; i++) d = (d << 8) | data[eepAddr * 8 + i];
            eepReadData = d;
            eepReadPos = 0;
            eepState = 4;
            break;
        }
        case 3:
            eepBuffer = (eepBuffer << 1) | bit;
            if (++eepBits == 64) {
                eepState = 5;
                eepBits = 0;
            }
            break;
        case 5: {  // end bit of write request
            u64 d = eepBuffer;
            for (int i = 7; i >= 0; i--) {
                data[eepAddr * 8 + i] = (u8)d;
                d >>= 8;
            }
            dirty = true;
            eepBuffer = 0;
            eepState = 0;
            break;
        }
        default: eepState = 0; break;
    }
}

void CartSave::serialize(StateWriter& w) const {
    w.tag("SAV0");
    w.pod(kind);
    w.u8v(data);
    w.pod(eepromSizeUnknown);
    w.pod(flashState);
    w.pod(flashId);
    w.pod(flashErasePrep);
    w.pod(flashWriteNext);
    w.pod(flashBankNext);
    w.pod(flashBank);
    w.pod(eepState);
    w.pod(eepBits);
    w.pod(eepBuffer);
    w.pod(eepAddr);
    w.pod(eepCmd);
    w.pod(eepReadData);
    w.pod(eepReadPos);
}

void CartSave::deserialize(StateReader& rd) {
    rd.tag("SAV0");
    rd.pod(kind);
    rd.u8v(data, 0x20000);
    rd.pod(eepromSizeUnknown);
    rd.pod(flashState);
    rd.pod(flashId);
    rd.pod(flashErasePrep);
    rd.pod(flashWriteNext);
    rd.pod(flashBankNext);
    rd.pod(flashBank);
    rd.pod(eepState);
    rd.pod(eepBits);
    rd.pod(eepBuffer);
    rd.pod(eepAddr);
    rd.pod(eepCmd);
    rd.pod(eepReadData);
    rd.pod(eepReadPos);
    flashBank &= 1;
    // States restore the save memory too (the game's view must match the state);
    // mark dirty so the host persists it.
    dirty = true;
}

}  // namespace retra

// Retra GBA core - GPIO + Seiko S-3511 RTC (3-wire serial: SCK=bit0, SIO=bit1, CS=bit2).
// Commands are sent MSB first as 0110 CCC R; data bytes travel LSB first.
#include "rtc.h"

#include <ctime>

#include "gba.h"
#include "state.h"

namespace retra {

static u8 toBcd(int v) { return (u8)(((v / 10) % 10) << 4 | (v % 10)); }
static int fromBcd(u8 v) { return ((v >> 4) & 15) * 10 + (v & 15); }

void Rtc::reset() {
    pinsOut = 0;
    direction = 0;
    control = 0;
    sioOut = 0;
    status = 0x40;
    sck = cs = false;
    state = 0;
    bitPos = bytePos = byteCount = 0;
    cmd = cur = 0;
    std::memset(buf, 0, sizeof(buf));
}

u16 Rtc::read(u32 addr) const {
    switch (addr & 0xF) {
        case 0x4: {
            // Input pins (direction bit 0) read the device; outputs read back the latch.
            u8 v = pinsOut & direction;
            if (!(direction & 2)) v |= (u8)(sioOut << 1);
            return v & 0xF;
        }
        case 0x6: return direction & 0xF;
        case 0x8: return control & 1;
        default: return 0;
    }
}

void Rtc::write(u32 addr, u16 v) {
    switch (addr & 0xF) {
        case 0x4: writePins((u8)(v & 0xF)); break;
        case 0x6: direction = (u8)(v & 0xF); break;
        case 0x8: control = (u8)(v & 1); break;
        default: break;
    }
}

void Rtc::latchTime() {
    std::time_t t = std::time(nullptr) + (std::time_t)(userOffset + gameOffset);
    std::tm tmv{};
#if defined(_WIN32)
    localtime_s(&tmv, &t);
#else
    localtime_r(&t, &tmv);
#endif
    buf[0] = toBcd(tmv.tm_year % 100);
    buf[1] = toBcd(tmv.tm_mon + 1);
    buf[2] = toBcd(tmv.tm_mday);
    buf[3] = toBcd(tmv.tm_wday);
    int hour = tmv.tm_hour;
    if (status & 0x40) {
        buf[4] = toBcd(hour);
    } else {
        buf[4] = toBcd(hour % 12);
        if (hour >= 12) buf[4] |= 0x40;
    }
    if (hour >= 12) buf[4] |= 0x80;  // AM/PM flag (games mask it out)
    buf[5] = toBcd(tmv.tm_min);
    buf[6] = toBcd(tmv.tm_sec);
}

void Rtc::beginCommand() {
    // cmd: 0110 CCC R (as received MSB first). Some software sends it reversed.
    u8 c = cmd;
    if ((c & 0xF0) != 0x60) {
        u8 r = 0;
        for (int i = 0; i < 8; i++)
            if (c & (1 << i)) r |= (u8)(0x80 >> i);
        c = r;
    }
    const u32 code = (c >> 1) & 7;
    const bool rd = c & 1;
    bytePos = 0;
    bitPos = 0;
    switch (code) {
        case 0:  // reset
            status = 0;
            gameOffset = 0;
            state = 0;
            byteCount = 0;
            return;
        case 1: byteCount = 1; if (rd) buf[0] = status; break;   // status register
        case 2: byteCount = 7; if (rd) latchTime(); break;       // date + time
        case 3:                                                  // time only
            byteCount = 3;
            if (rd) {
                latchTime();
                buf[0] = buf[4];
                buf[1] = buf[5];
                buf[2] = buf[6];
            }
            break;
        case 6: byteCount = 1; if (rd) buf[0] = 0; break;  // IRQ/alarm (unused)
        default: byteCount = 0; break;
    }
    cmd = c;
    state = byteCount == 0 ? 0 : (rd ? 2 : 3);
}

void Rtc::applyWrite() {
    const u32 code = (cmd >> 1) & 7;
    if (code == 1) {
        status = buf[0] & 0x6A;
    } else if (code == 2 || code == 3) {
        // Game set the clock: remember the difference to the host clock.
        std::time_t now = std::time(nullptr) + (std::time_t)userOffset;
        std::tm tmv{};
#if defined(_WIN32)
        localtime_s(&tmv, &now);
#else
        localtime_r(&now, &tmv);
#endif
        std::tm want = tmv;
        if (code == 2) {
            want.tm_year = 100 + fromBcd(buf[0]);
            want.tm_mon = fromBcd(buf[1] & 0x1F) - 1;
            want.tm_mday = fromBcd(buf[2] & 0x3F);
            want.tm_hour = fromBcd(buf[4] & 0x3F);
            want.tm_min = fromBcd(buf[5] & 0x7F);
            want.tm_sec = fromBcd(buf[6] & 0x7F);
        } else {
            want.tm_hour = fromBcd(buf[0] & 0x3F);
            want.tm_min = fromBcd(buf[1] & 0x7F);
            want.tm_sec = fromBcd(buf[2] & 0x7F);
        }
        want.tm_isdst = -1;
        std::time_t wt = std::mktime(&want);
        if (wt != (std::time_t)-1) gameOffset = (s64)(wt - now);
    }
}

void Rtc::writePins(u8 v) {
    // Only pins configured as outputs are driven by the GBA.
    pinsOut = (u8)((pinsOut & ~direction) | (v & direction));
    const bool nsck = pinsOut & 1;
    const bool nsio = (pinsOut >> 1) & 1;
    const bool ncs = (pinsOut >> 2) & 1;

    if (!ncs) {
        state = 0;
        bitPos = 0;
        cmd = 0;
        cs = false;
        sck = nsck;
        return;
    }
    if (!cs) {
        // chip select rising edge: start receiving a command
        cs = true;
        state = 1;
        bitPos = 0;
        cmd = 0;
        sck = nsck;
        return;
    }
    const bool rising = !sck && nsck;
    sck = nsck;
    if (!rising) return;

    switch (state) {
        case 1:  // command byte, MSB first
            cmd = (u8)((cmd << 1) | (nsio ? 1 : 0));
            if (++bitPos == 8) beginCommand();
            break;
        case 2: {  // reading: present next bit (LSB first)
            if (bytePos < byteCount) {
                sioOut = (buf[bytePos] >> bitPos) & 1;
                if (++bitPos == 8) {
                    bitPos = 0;
                    bytePos++;
                }
            } else {
                sioOut = 0;
            }
            break;
        }
        case 3:  // writing: receive bits LSB first
            if (bytePos < byteCount) {
                if (bitPos == 0) cur = 0;
                cur |= (u8)((nsio ? 1 : 0) << bitPos);
                if (++bitPos == 8) {
                    buf[bytePos++] = cur;
                    bitPos = 0;
                    if (bytePos == byteCount) {
                        applyWrite();
                        state = 0;
                    }
                }
            }
            break;
        default: break;
    }
}

void Rtc::serialize(StateWriter& w) const {
    w.tag("RTC0");
    w.pod(enabled);
    w.pod(gameOffset);
    w.pod(pinsOut);
    w.pod(direction);
    w.pod(control);
    w.pod(sioOut);
    w.pod(status);
    w.pod(sck);
    w.pod(cs);
    w.pod(state);
    w.pod(bitPos);
    w.pod(bytePos);
    w.pod(byteCount);
    w.pod(cmd);
    w.pod(cur);
    w.pod(buf);
}

void Rtc::deserialize(StateReader& rd) {
    rd.tag("RTC0");
    rd.pod(enabled);
    rd.pod(gameOffset);
    rd.pod(pinsOut);
    rd.pod(direction);
    rd.pod(control);
    rd.pod(sioOut);
    rd.pod(status);
    rd.pod(sck);
    rd.pod(cs);
    rd.pod(state);
    rd.pod(bitPos);
    rd.pod(bytePos);
    rd.pod(byteCount);
    rd.pod(cmd);
    rd.pod(cur);
    rd.pod(buf);
    if (byteCount > 8) byteCount = 0;
    if (bytePos > 8) bytePos = 0;
    bitPos &= 7;
}

}  // namespace retra

// Retra GBA core - cheat engine.
//  Raw:          "AAAAAAAA:VV" / "AAAAAAAA:VVVV" / "AAAAAAAA:VVVVVVVV" (also "AAAAAAAA VV")
//  CodeBreaker:  "XXXXXXXX YYYY" (unencrypted)
//  GameShark v1/v2 and Pro Action Replay v3: "XXXXXXXX YYYYYYYY" (encrypted, auto-detected;
//                force with a leading "GS:" / "AR:" / "PAR:" / "ARV3:" tag).
#include "cheats.h"

#include <cctype>

#include "bus_inl.h"
#include "gba.h"

namespace retra {

const u32 Cheats::kGsSeeds[4] = {0x09F4FBBD, 0x9681884A, 0x352027E9, 0xF3DEE5A7};
const u32 Cheats::kAr3Seeds[4] = {0x7AA9648F, 0x7FAE6994, 0xC0EFAAD5, 0x42712C57};

void Cheats::gsDecrypt(u32& a, u32& v, const u32 s[4]) {
    u32 sum = 0xC6EF3720;
    for (int i = 0; i < 32; i++) {
        v -= ((a << 4) + s[2]) ^ (a + sum) ^ ((a >> 5) + s[3]);
        a -= ((v << 4) + s[0]) ^ (v + sum) ^ ((v >> 5) + s[1]);
        sum -= 0x9E3779B9;
    }
}

namespace {

enum Forced { F_AUTO = 0, F_GS = 1, F_AR3 = 2, F_CB = 3, F_RAW = 4 };

bool isHex(char c) { return std::isxdigit((unsigned char)c) != 0; }

bool validRamAddr(u32 a) {
    const u32 r = a >> 24;
    return r == 0x02 || r == 0x03 || r == 0x04 || r == 0x05 || r == 0x06 || r == 0x07;
}

// Plausibility of a decrypted GameShark v1/v2 code.
bool plausibleGs(u32 a, u32 v) {
    if (v == 0x001DC0DE) return true;
    if (a == 0xDEADFACE) return false;
    switch (a >> 28) {
        case 0x0: return validRamAddr(a & 0x0FFFFFFF) && v <= 0xFF;
        case 0x1: return validRamAddr(a & 0x0FFFFFFF) && v <= 0xFFFF;
        case 0x2: return validRamAddr(a & 0x0FFFFFFF);
        case 0x3: return (a & 0x0FFF0000) == 0;
        case 0x6: return (a & 0x0F000000) == 0;
        case 0xD: return validRamAddr(a & 0x0FFFFFFF) && v <= 0xFFFF;
        case 0xE: return validRamAddr(v & 0x0FFFFFFF);
        case 0xF: return ((a & 0x0FFFFFFF) >> 24) >= 8 && ((a & 0x0FFFFFFF) >> 24) <= 9;
        default: return false;
    }
}

u32 ar3Addr(u32 a) { return ((a & 0x00F00000) << 4) | (a & 0x000FFFFF); }

bool plausibleAr3(u32 a, u32 v) {
    if (v == 0x001DC0DE) return true;
    if (a == 0) return true;  // special codes
    const u32 t = a >> 24;
    switch (t) {
        case 0x00:
        case 0x02:
        case 0x04:
        case 0x40:
        case 0x42:
        case 0x44:
        case 0x80:
        case 0x82:
        case 0x84: return validRamAddr(ar3Addr(a));
        case 0xC4:
        case 0xC6:
        case 0xC7: return true;
        default:
            if ((a & 0x38000000) != 0) return validRamAddr(ar3Addr(a));
            return false;
    }
}

}  // namespace

bool Cheats::parseLine(const std::string& lineIn, int forced, std::vector<Code>& out, bool& cbEncrypted) {
    // Extract hex digit groups.
    std::string line;
    for (char ch : lineIn) line.push_back((char)std::toupper((unsigned char)ch));
    const bool hasColon = line.find(':') != std::string::npos;
    std::vector<std::string> groups;
    std::string cur;
    for (char ch : line) {
        if (isHex(ch)) {
            cur.push_back(ch);
        } else {
            if (!cur.empty()) groups.push_back(cur);
            cur.clear();
        }
    }
    if (!cur.empty()) groups.push_back(cur);
    if (groups.size() == 1 && groups[0].size() == 16) {
        groups = {groups[0].substr(0, 8), groups[0].substr(8)};
    }
    if (groups.size() != 2 || groups[0].size() != 8) return false;
    const std::string& vs = groups[1];
    if (vs.size() != 2 && vs.size() != 4 && vs.size() != 6 && vs.size() != 8) return false;
    const u32 a = (u32)std::stoul(groups[0], nullptr, 16);
    const u32 v = (u32)std::stoul(vs, nullptr, 16);

    if (forced == F_RAW || (hasColon && forced == F_AUTO) || (vs.size() == 2 && forced == F_AUTO)) {
        if (vs.size() == 6) return false;
        Code c{Kind::RAW, a, v};
        // encode width in the top bits of the kind-specific value: keep width via digit count
        c.a = a;
        c.v = v;
        out.push_back(c);
        out.back().kind = Kind::RAW;
        // width marker stored separately in high byte of a? Use digit count encoded in vector below.
        rawWidth.push_back((u8)(vs.size() / 2));
        return true;
    }
    if (vs.size() == 4 || vs.size() == 6 || forced == F_CB) {
        // CodeBreaker (6-digit values only appear in multi-line parameter rows)
        if (cbEncrypted) return false;
        if ((a >> 28) == 0x9) {
            cbEncrypted = true;  // encrypted CodeBreaker lists are not supported
            return false;
        }
        out.push_back(Code{Kind::CB, a, v});
        rawWidth.push_back(0);
        return true;
    }
    // 16 digit encrypted codes
    u32 ga = a, gv = v;
    gsDecrypt(ga, gv, kGsSeeds);
    u32 ra = a, rv = v;
    gsDecrypt(ra, rv, kAr3Seeds);
    if (forced == F_GS || (forced == F_AUTO && plausibleGs(ga, gv))) {
        out.push_back(Code{Kind::GS, ga, gv});
        rawWidth.push_back(0);
        return true;
    }
    if (forced == F_AR3 || (forced == F_AUTO && plausibleAr3(ra, rv))) {
        out.push_back(Code{Kind::AR3, ra, rv});
        rawWidth.push_back(0);
        return true;
    }
    // Possibly an already-decrypted (raw) GameShark code.
    if (forced == F_AUTO && plausibleGs(a, v)) {
        out.push_back(Code{Kind::GS, a, v});
        rawWidth.push_back(0);
        return true;
    }
    return false;
}

int Cheats::set(const std::vector<std::string>& codes) {
    restoreRomPatches();
    list.clear();
    rawWidth.clear();
    int accepted = 0;
    for (const std::string& entry : codes) {
        int forced = F_AUTO;
        bool cbEncrypted = false;
        size_t start = 0;
        std::string s = entry;
        // optional tag
        auto stripTag = [&](const char* tag, int f) {
            const size_t n = std::strlen(tag);
            if (s.size() >= n) {
                std::string head;
                for (size_t i = 0; i < n; i++) head.push_back((char)std::toupper((unsigned char)s[i]));
                if (head == tag) {
                    forced = f;
                    s = s.substr(n);
                    return true;
                }
            }
            return false;
        };
        while (!s.empty() && std::isspace((unsigned char)s[0])) s.erase(0, 1);
        stripTag("ARV3:", F_AR3) || stripTag("PAR:", F_AR3) || stripTag("AR:", F_AR3) || stripTag("GS:", F_GS) ||
            stripTag("CB:", F_CB) || stripTag("RAW:", F_RAW);
        // split into lines
        std::vector<Code> parsed;
        size_t pos = start;
        while (pos <= s.size()) {
            size_t e = s.find_first_of("\n\r;,", pos);
            if (e == std::string::npos) e = s.size();
            std::string line = s.substr(pos, e - pos);
            bool hasHex = false;
            for (char ch : line) hasHex |= isHex(ch);
            if (hasHex && parseLine(line, forced, list, cbEncrypted)) accepted++;
            pos = e + 1;
        }
    }
    return accepted;
}

void Cheats::restoreRomPatches() {
    Bus& b = g->bus;
    for (auto it = romPatches.rbegin(); it != romPatches.rend(); ++it) {
        if (it->offset + 1 < b.rom.size()) storeLE<u16>(&b.rom[it->offset], it->original);
    }
    romPatches.clear();
}

void Cheats::romPatch(u32 offset, u16 value) {
    Bus& b = g->bus;
    offset &= 0x1FFFFFE;
    if (offset + 1 >= b.rom.size()) return;
    for (const auto& p : romPatches)
        if (p.offset == offset) {
            storeLE<u16>(&b.rom[offset], value);
            return;
        }
    romPatches.push_back(RomPatch{offset, loadLE<u16>(&b.rom[offset])});
    storeLE<u16>(&b.rom[offset], value);
}

void Cheats::apply() {
    size_t i = 0;
    while (i < list.size()) {
        switch (list[i].kind) {
            case Kind::RAW: {
                Bus& b = g->bus;
                const Code& c = list[i];
                const u8 w = rawWidth[i];
                if (w == 1) b.poke<u8>(c.a, (u8)c.v);
                else if (w == 2) b.poke<u16>(c.a, (u16)c.v);
                else b.poke<u32>(c.a, c.v);
                i++;
                break;
            }
            case Kind::CB: runCodeBreaker(i); break;
            case Kind::GS: runGameShark(i); break;
            case Kind::AR3: runAr3(i); break;
        }
        if (stopAll) {
            stopAll = false;
            return;
        }
    }
}

void Cheats::runCodeBreaker(size_t& i) {
    Bus& b = g->bus;
    const Code c = list[i];
    const u32 addr = c.a & 0x0FFFFFFF;
    const u16 v = (u16)c.v;
    i++;
    auto skipNext = [&](bool cond) {
        if (!cond && i < list.size()) i++;
    };
    switch (c.a >> 28) {
        case 0x0:
        case 0x1:
        case 0x9: break;  // game id / hook / encryption seed
        case 0x2: b.poke<u16>(addr, (u16)(b.peek<u16>(addr) | v)); break;
        case 0x3: b.poke<u8>(addr, (u8)v); break;
        case 0x4: {
            if (i >= list.size()) break;
            const Code p = list[i++];
            const u32 inc = p.a >> 16, count = p.a & 0xFFFF, step = p.v & 0xFFFF;
            for (u32 k = 0; k < count; k++) b.poke<u16>(addr + k * step, (u16)(v + k * inc));
            break;
        }
        case 0x5: {
            u32 count = v;
            u32 a = addr;
            while (count && i < list.size()) {
                const Code p = list[i++];
                const u8 bytes[6] = {(u8)(p.a >> 24), (u8)(p.a >> 16), (u8)(p.a >> 8),
                                     (u8)p.a,         (u8)(p.v >> 8),  (u8)p.v};
                for (int k = 0; k < 6 && count; k++, count--) b.poke<u8>(a++, bytes[k]);
            }
            break;
        }
        case 0x6: b.poke<u16>(addr, (u16)(b.peek<u16>(addr) & v)); break;
        case 0x7: skipNext(b.peek<u16>(addr) == v); break;
        case 0x8: b.poke<u16>(addr, v); break;
        case 0xA: skipNext(b.peek<u16>(addr) != v); break;
        case 0xB: skipNext((s16)b.peek<u16>(addr) > (s16)v); break;
        case 0xC: skipNext((s16)b.peek<u16>(addr) < (s16)v); break;
        case 0xD: skipNext((g->keyInput & v) == 0); break;
        case 0xE: b.poke<u16>(addr, (u16)(b.peek<u16>(addr) + v)); break;
        case 0xF: skipNext((b.peek<u16>(addr) & v) != 0); break;
    }
}

void Cheats::runGameShark(size_t& i) {
    Bus& b = g->bus;
    const Code c = list[i];
    i++;
    if (c.v == 0x001DC0DE) return;  // game id
    const u32 addr = c.a & 0x0FFFFFFF;
    switch (c.a >> 28) {
        case 0x0: b.poke<u8>(addr, (u8)c.v); break;
        case 0x1: b.poke<u16>(addr, (u16)c.v); break;
        case 0x2: b.poke<u32>(addr, c.v); break;
        case 0x3: {
            u32 count = c.a & 0xFFFF;
            const u32 value = c.v;
            while (count && i < list.size()) {
                const Code p = list[i++];
                b.poke<u32>(p.a & 0x0FFFFFFF, value);
                if (--count && p.v) {
                    b.poke<u32>(p.v & 0x0FFFFFFF, value);
                    --count;
                }
            }
            break;
        }
        case 0x6: romPatch((c.a & 0x00FFFFFF) * 2, (u16)c.v); break;
        case 0xD:
            if (b.peek<u16>(addr) != (u16)c.v && i < list.size()) i++;
            break;
        case 0xE: {
            const u32 n = (c.a >> 16) & 0xFF;
            if (b.peek<u16>(c.v & 0x0FFFFFFF) != (u16)(c.a & 0xFFFF)) i += n;
            break;
        }
        default: break;  // hook, button codes, seeds: ignored
    }
}

void Cheats::runAr3(size_t& i) {
    Bus& b = g->bus;
    const Code c = list[i];
    i++;
    if (c.v == 0x001DC0DE) return;
    if (c.a == 0) {
        // special codes
        const u32 t = c.v >> 24;
        if (c.v == 0) {
            stopAll = true;  // end of list
            return;
        }
        if (c.v == 0x60000000 || c.v == 0x40000000) return;  // ELSE / ENDIF markers
        if (i >= list.size()) return;
        const Code p = list[i++];
        const u32 addr = ar3Addr(c.v & 0x00FFFFFF);
        switch (t) {
            case 0x18:
            case 0x1A:
            case 0x1C:
            case 0x1E: romPatch((c.v & 0x00FFFFFF) * 2, (u16)p.a); break;
            case 0x80:
            case 0x82:
            case 0x84: {
                // slide: p.a = value, p.v = ssccssss
                u32 value = p.a;
                const u32 vinc = p.v >> 24, count = (p.v >> 16) & 0xFF, ainc = p.v & 0xFFFF;
                u32 a = addr;
                for (u32 k = 0; k < count; k++) {
                    if (t == 0x80) {
                        b.poke<u8>(a, (u8)value);
                        a += ainc;
                    } else if (t == 0x82) {
                        b.poke<u16>(a, (u16)value);
                        a += ainc * 2;
                    } else {
                        b.poke<u32>(a, value);
                        a += ainc * 4;
                    }
                    value += vinc;
                }
                break;
            }
            default: break;  // button codes ignored
        }
        return;
    }
    const u32 t = c.a >> 24;
    const u32 addr = ar3Addr(c.a);
    if ((c.a & 0x38000000) == 0 || t == 0xC4 || t == 0xC6 || t == 0xC7) {
        switch (t) {
            case 0x00: {
                const u32 n = (c.v >> 8) + 1;
                for (u32 k = 0; k < n && k < 0x10000; k++) b.poke<u8>(addr + k, (u8)c.v);
                break;
            }
            case 0x02: {
                const u32 n = (c.v >> 16) + 1;
                for (u32 k = 0; k < n; k++) b.poke<u16>(addr + k * 2, (u16)c.v);
                break;
            }
            case 0x04: b.poke<u32>(addr, c.v); break;
            case 0x40: b.poke<u8>(b.peek<u32>(addr) + (c.v >> 8), (u8)c.v); break;
            case 0x42: b.poke<u16>(b.peek<u32>(addr) + (c.v >> 16) * 2, (u16)c.v); break;
            case 0x44: b.poke<u32>(b.peek<u32>(addr), c.v); break;
            case 0x80: b.poke<u8>(addr, (u8)(b.peek<u8>(addr) + c.v)); break;
            case 0x82: b.poke<u16>(addr, (u16)(b.peek<u16>(addr) + c.v)); break;
            case 0x84: b.poke<u32>(addr, b.peek<u32>(addr) + c.v); break;
            case 0xC6: b.poke<u16>(0x04000000 | (c.a & 0x00FFFFFF), (u16)c.v); break;
            case 0xC7: b.poke<u32>(0x04000000 | (c.a & 0x00FFFFFF), c.v); break;
            default: break;
        }
        return;
    }
    // conditional
    const u32 cond = c.a & 0x38000000;
    const u32 size = (c.a >> 25) & 3;
    const u32 act = c.a & 0xC0000000;
    u32 cur, val;
    if (size == 0) {
        cur = b.peek<u8>(addr);
        val = c.v & 0xFF;
    } else if (size == 1) {
        cur = b.peek<u16>(addr);
        val = c.v & 0xFFFF;
    } else if (size == 2) {
        cur = b.peek<u32>(addr);
        val = c.v;
    } else {
        cur = 0;
        val = 0;
    }
    bool res = false;
    if (size != 3) {
        switch (cond >> 27) {
            case 1: res = cur == val; break;
            case 2: res = cur != val; break;
            case 3: res = (s32)cur < (s32)val; break;
            case 4: res = (s32)cur > (s32)val; break;
            case 5: res = cur < val; break;
            case 6: res = cur > val; break;
            case 7: res = (cur & val) != 0; break;
            default: res = false; break;
        }
    }
    if (res) return;
    switch (act) {
        case 0x00000000: i += 1; break;
        case 0x40000000: i += 2; break;
        case 0x80000000:
            while (i < list.size()) {
                const Code& n = list[i++];
                if (n.kind == Kind::AR3 && n.a == 0 && (n.v == 0x60000000 || n.v == 0x40000000)) break;
            }
            break;
        default: stopAll = true; break;
    }
}

}  // namespace retra

