void Cpu::idleCheck() {
    const u32 pc = r[15];
    const u32 fl = cpsr();
    const u32 writes = g->bus.writeCount;
    if (pc == idlePc && writes == idleWrites && fl == idleFlags && std::memcmp(r, idleRegs, sizeof(idleRegs)) == 0) {
        Scheduler& s = g->sched;
        if (s.next > s.now && s.next != kNever) s.now = s.next;
        return;
    }
    idlePc = pc;
    idleFlags = fl;
    idleWrites = writes;
    std::memcpy(idleRegs, r, sizeof(idleRegs));
}

