package app.retra.patcher

/** Supported patch container formats. */
enum class PatchFormat { IPS, UPS, BPS, VCDIFF }

/**
 * Information that can be read from a patch without applying it.
 * Fields are null when the format does not record them (e.g. IPS has no checksums,
 * xdelta/VCDIFF does not record the source size or CRC).
 */
data class PatchInfo(
    val format: PatchFormat,
    val sourceSize: Long?,
    val targetSize: Long?,
    val sourceCrc32: Long?,
    val targetCrc32: Long?,
    val metadata: String?,
)

sealed interface PatchResult {
    class Ok(val output: ByteArray, val info: PatchInfo, val warnings: List<String>) : PatchResult {
        override fun equals(other: Any?): Boolean =
            other is Ok && output.contentEquals(other.output) && info == other.info && warnings == other.warnings

        override fun hashCode(): Int = (output.contentHashCode() * 31 + info.hashCode()) * 31 + warnings.hashCode()

        override fun toString(): String = "Ok(output=${output.size} bytes, info=$info, warnings=$warnings)"

        operator fun component1(): ByteArray = output
        operator fun component2(): PatchInfo = info
        operator fun component3(): List<String> = warnings

        fun copy(output: ByteArray = this.output, info: PatchInfo = this.info, warnings: List<String> = this.warnings) =
            Ok(output, info, warnings)
    }

    data class Error(val code: PatchError, val message: String) : PatchResult
}

enum class PatchError { UNKNOWN_FORMAT, CORRUPT_PATCH, SOURCE_MISMATCH, TARGET_MISMATCH, PATCH_CHECKSUM, UNSUPPORTED }

/** Internal control-flow exception carrying a user-facing message. */
internal class PatchException(val code: PatchError, message: String) : Exception(message)

/** Collects warnings and decides whether a soft failure is fatal (strict) or a warning (lenient). */
internal class ApplyContext(val strict: Boolean, private val progress: ((Float) -> Unit)?) {
    val warnings = ArrayList<String>()
    private var lastReported = -1

    /** Fatal in strict mode, warning otherwise. */
    fun soft(code: PatchError, message: String) {
        if (strict) throw PatchException(code, message)
        warnings += message
    }

    fun progress(done: Long, total: Long) {
        val p = progress ?: return
        if (total <= 0) return
        val pct = ((done * 100) / total).toInt().coerceIn(0, 100)
        if (pct != lastReported) {
            lastReported = pct
            p(pct / 100f)
        }
    }
}

object Patcher {
    /** Hard upper bound on output size; GBA ROMs are at most 32 MiB. */
    internal const val MAX_OUTPUT: Long = 512L * 1024 * 1024

    fun detect(patch: ByteArray): PatchFormat? = when {
        patch.startsWith("PATCH") -> PatchFormat.IPS
        patch.startsWith("UPS1") -> PatchFormat.UPS
        patch.startsWith("BPS1") -> PatchFormat.BPS
        patch.size >= 4 && patch[0] == 0xD6.toByte() && patch[1] == 0xC3.toByte() &&
            patch[2] == 0xC4.toByte() && patch[3] == 0.toByte() -> PatchFormat.VCDIFF
        else -> null
    }

    /** Reads header information; returns null for unknown or unreadable patches. */
    fun inspect(patch: ByteArray): PatchInfo? = try {
        when (detect(patch)) {
            PatchFormat.IPS -> Ips.inspect(patch)
            PatchFormat.UPS -> Ups.inspect(patch)
            PatchFormat.BPS -> Bps.inspect(patch)
            PatchFormat.VCDIFF -> Vcdiff.inspect(patch)
            null -> null
        }
    } catch (e: PatchException) {
        null
    } catch (e: RuntimeException) {
        null
    }

    /**
     * Applies [patch] to [source]. With [strict] = false, a base-ROM checksum mismatch (and the
     * resulting output checksum mismatch) is reported as a warning instead of an error, so the user
     * can force-apply. Structural corruption is always an error.
     */
    fun apply(
        source: ByteArray,
        patch: ByteArray,
        strict: Boolean = true,
        progress: ((Float) -> Unit)? = null,
    ): PatchResult {
        val format = detect(patch) ?: return PatchResult.Error(
            PatchError.UNKNOWN_FORMAT,
            if (patch.isEmpty()) "The patch file is empty."
            else "This file isn't a recognised patch. Supported formats are IPS, UPS, BPS and xdelta/VCDIFF.",
        )
        val ctx = ApplyContext(strict, progress)
        return try {
            val (out, info) = when (format) {
                PatchFormat.IPS -> Ips.apply(source, patch, ctx)
                PatchFormat.UPS -> Ups.apply(source, patch, ctx)
                PatchFormat.BPS -> Bps.apply(source, patch, ctx)
                PatchFormat.VCDIFF -> Vcdiff.apply(source, patch, ctx)
            }
            progress?.invoke(1f)
            PatchResult.Ok(out, info, ctx.warnings.toList())
        } catch (e: PatchException) {
            PatchResult.Error(e.code, e.message ?: e.code.name)
        } catch (e: OutOfMemoryError) {
            PatchResult.Error(PatchError.UNSUPPORTED, "Not enough memory to apply this patch.")
        } catch (e: IndexOutOfBoundsException) {
            PatchResult.Error(PatchError.CORRUPT_PATCH, "The ${formatName(format)} patch is damaged or incomplete (it ends unexpectedly). Try downloading it again.")
        } catch (e: RuntimeException) {
            PatchResult.Error(PatchError.CORRUPT_PATCH, "The ${formatName(format)} patch could not be read: ${e.message ?: e.javaClass.simpleName}")
        }
    }

    internal fun formatName(f: PatchFormat) = when (f) {
        PatchFormat.IPS -> "IPS"
        PatchFormat.UPS -> "UPS"
        PatchFormat.BPS -> "BPS"
        PatchFormat.VCDIFF -> "xdelta"
    }

    private fun ByteArray.startsWith(magic: String): Boolean {
        if (size < magic.length) return false
        for (i in magic.indices) if (this[i] != magic[i].code.toByte()) return false
        return true
    }
}

internal object Msg {
    fun hex(crc: Long) = "%08X".format(crc and 0xFFFFFFFFL)

    fun size(n: Long): String = when {
        n >= 1024 * 1024 && n % (1024 * 1024) == 0L -> "${n / (1024 * 1024)} MiB"
        n >= 1024 * 1024 -> "%.1f MiB".format(java.util.Locale.ROOT, n / (1024.0 * 1024.0))
        n >= 1024 -> "%.1f KiB".format(java.util.Locale.ROOT, n / 1024.0)
        else -> "$n bytes"
    }

    fun wrongSource(expectedCrc: Long, expectedSize: Long, actual: ByteArray, actualCrc: Long): String {
        val sizeNote = if (expectedSize != actual.size.toLong())
            " The expected ROM is ${size(expectedSize)}, yours is ${size(actual.size.toLong())}." else ""
        return "This patch expects a different base game (needs CRC32 ${hex(expectedCrc)}, you picked ${hex(actualCrc)}).$sizeNote"
    }

    fun corrupt(fmt: String, detail: String) = "The $fmt patch is damaged or incomplete ($detail). Try downloading it again."
}

/** Big helper for "beat"-style varints (UPS/BPS) and fixed-width reads. */
internal class BeatReader(val buf: ByteArray, var pos: Int, val end: Int, private val fmt: String) {
    fun u8(): Int {
        if (pos >= end) throw PatchException(PatchError.CORRUPT_PATCH, Msg.corrupt(fmt, "it ends unexpectedly"))
        return buf[pos++].toInt() and 0xFF
    }

    fun varint(): Long {
        var data = 0L
        var shift = 1L
        while (true) {
            val x = u8()
            data += (x and 0x7F) * shift
            if (data < 0 || shift > (1L shl 56)) throw PatchException(PatchError.CORRUPT_PATCH, Msg.corrupt(fmt, "invalid number"))
            if (x and 0x80 != 0) return data
            shift = shift shl 7
            data += shift
        }
    }

    fun le32(at: Int): Long =
        (buf[at].toLong() and 0xFF) or ((buf[at + 1].toLong() and 0xFF) shl 8) or
            ((buf[at + 2].toLong() and 0xFF) shl 16) or ((buf[at + 3].toLong() and 0xFF) shl 24)
}

package app.retra.patcher

import java.security.MessageDigest
import java.util.zip.CRC32

object Checksums {
    fun crc32(b: ByteArray): Long = crc32(b, 0, b.size)

    fun crc32(b: ByteArray, off: Int, len: Int): Long {
        val c = CRC32()
        c.update(b, off, len)
        return c.value
    }

    /** CRC32 as 8 uppercase hex digits, e.g. "1F1C08FB". */
    fun crc32Hex(b: ByteArray): String = Msg.hex(crc32(b))

    fun sha1Hex(b: ByteArray): String = digestHex("SHA-1", b)

    fun sha256Hex(b: ByteArray): String = digestHex("SHA-256", b)

    private fun digestHex(alg: String, b: ByteArray): String {
        val d = MessageDigest.getInstance(alg).digest(b)
        val hex = "0123456789abcdef"
        val sb = StringBuilder(d.size * 2)
        for (x in d) {
            sb.append(hex[(x.toInt() shr 4) and 0xF]).append(hex[x.toInt() and 0xF])
        }
        return sb.toString()
    }
}

package app.retra.patcher

import java.io.ByteArrayInputStream
import java.io.ByteArrayOutputStream
import java.util.zip.ZipInputStream

object PatchArchive {
    /** Entries larger than this are ignored (zip-bomb protection). */
    private const val MAX_ENTRY = 256L * 1024 * 1024

    private val PRIORITY = mapOf(
        "bps" to 0, "ups" to 1, "xdelta" to 2, "vcdiff" to 2, "xdelta3" to 2, "delta" to 2, "ips" to 3, "gba" to 4,
    )

    /**
     * Picks the best entry of a zip archive: a patch (.bps/.ups/.xdelta/.vcdiff/.ips) or, failing that,
     * a ROM (.gba). Entries with unknown extensions are used only if their content looks like a patch.
     * Among equal candidates the largest wins. Returns (file name without directories, bytes) or null.
     */
    fun extractSingle(zip: ByteArray): Pair<String, ByteArray>? {
        var best: Triple<Int, String, ByteArray>? = null
        try {
            ZipInputStream(ByteArrayInputStream(zip)).use { zin ->
                while (true) {
                    val e = zin.nextEntry ?: break
                    val path = e.name.replace('\\', '/')
                    val name = path.substringAfterLast('/')
                    if (e.isDirectory || name.isEmpty() || name.startsWith("._") || path.startsWith("__MACOSX/")) continue
                    val ext = name.substringAfterLast('.', "").lowercase()
                    var prio = PRIORITY[ext]
                    if (prio == null && e.size > MAX_ENTRY) continue
                    val bytes = readCapped(zin) ?: continue
                    if (prio == null) {
                        prio = if (Patcher.detect(bytes) != null) 5 else continue
                    }
                    val cur = best
                    if (cur == null || prio < cur.first || (prio == cur.first && bytes.size > cur.third.size)) {
                        best = Triple(prio, name, bytes)
                    }
                }
            }
        } catch (e: java.io.IOException) {
            // Corrupt or truncated archive: fall through with whatever we found so far.
        } catch (e: IllegalArgumentException) {
            // Malformed entry names (bad encoding).
        }
        return best?.let { it.second to it.third }
    }

    private fun readCapped(zin: ZipInputStream): ByteArray? {
        val out = ByteArrayOutputStream()
        val buf = ByteArray(64 * 1024)
        var total = 0L
        while (true) {
            val n = zin.read(buf)
            if (n < 0) break
            total += n
            if (total > MAX_ENTRY) return null
            out.write(buf, 0, n)
        }
        return out.toByteArray()
    }
}

package app.retra.patcher

/**
 * IPS: "PATCH", records of (u24 offset, u16 size, data) or RLE (size 0, u16 count, u8 value),
 * terminated by "EOF", optionally followed by a u24 truncation size (Lunar IPS extension).
 */
internal object Ips {
    private const val EOF_MARK = 0x454F46
    private const val FMT = "IPS"

    private class Scan(val maxEnd: Long, val truncate: Long?, val hasEof: Boolean, val records: Int)

    /** Walks all records, optionally applying them to [out]. */
    private fun walk(patch: ByteArray, out: ByteArray?, ctx: ApplyContext?): Scan {
        var p = 5
        var maxEnd = 0L
        var records = 0
        val n = patch.size
        while (true) {
            if (p == n) return Scan(maxEnd, null, false, records)
            if (p + 3 > n) throw corrupt("a record is cut off")
            val off = ((patch[p].toInt() and 0xFF) shl 16) or ((patch[p + 1].toInt() and 0xFF) shl 8) or
                (patch[p + 2].toInt() and 0xFF)
            p += 3
            if (off == EOF_MARK) {
                // Exactly at EOF marker. An offset of 0x454F46 followed by more records is ambiguous;
                // by convention it always means end of patch.
                val rest = n - p
                val truncate = if (rest >= 3) {
                    ((patch[p].toLong() and 0xFF) shl 16) or ((patch[p + 1].toLong() and 0xFF) shl 8) or
                        (patch[p + 2].toLong() and 0xFF)
                } else null
                return Scan(maxEnd, truncate, true, records)
            }
            if (p + 2 > n) throw corrupt("a record is cut off")
            val size = ((patch[p].toInt() and 0xFF) shl 8) or (patch[p + 1].toInt() and 0xFF)
            p += 2
            records++
            if (size == 0) {
                if (p + 3 > n) throw corrupt("a record is cut off")
                val count = ((patch[p].toInt() and 0xFF) shl 8) or (patch[p + 1].toInt() and 0xFF)
                val value = patch[p + 2]
                p += 3
                if (out != null) java.util.Arrays.fill(out, off, off + count, value)
                maxEnd = maxOf(maxEnd, off.toLong() + count)
            } else {
                if (p + size > n) throw corrupt("a record is cut off")
                if (out != null) System.arraycopy(patch, p, out, off, size)
                p += size
                maxEnd = maxOf(maxEnd, off.toLong() + size)
            }
            if (ctx != null && (records and 0xFFF) == 0) ctx.progress(p.toLong(), n.toLong())
        }
    }

    private fun corrupt(detail: String) = PatchException(PatchError.CORRUPT_PATCH, Msg.corrupt(FMT, detail))

    fun inspect(patch: ByteArray): PatchInfo {
        val s = walk(patch, null, null)
        return PatchInfo(PatchFormat.IPS, null, s.truncate, null, null, null)
    }

    fun apply(source: ByteArray, patch: ByteArray, ctx: ApplyContext): Pair<ByteArray, PatchInfo> {
        val scan = walk(patch, null, null)
        if (!scan.hasEof) ctx.warnings += "The IPS patch has no end marker; it may be incomplete."
        val size = scan.truncate ?: maxOf(source.size.toLong(), scan.maxEnd)
        if (size > Patcher.MAX_OUTPUT) throw PatchException(PatchError.UNSUPPORTED, "The patched game would be too large.")
        val out: ByteArray
        if (scan.truncate != null && scan.maxEnd > scan.truncate) {
            // Records write past the truncation point: apply on a full buffer then cut.
            val tmp = source.copyOf(maxOf(source.size.toLong(), scan.maxEnd).toInt())
            walk(patch, tmp, ctx)
            out = tmp.copyOf(size.toInt())
        } else {
            out = source.copyOf(size.toInt())
            walk(patch, out, ctx)
        }
        return out to PatchInfo(PatchFormat.IPS, source.size.toLong(), size, null, null, null)
    }
}

package app.retra.patcher

/** Shared logic for the "beat" family (UPS, BPS): 12-byte CRC32 footer and checks. */
internal object Beat {
    class Footer(val sourceCrc: Long, val targetCrc: Long, val patchCrc: Long)

    fun footer(patch: ByteArray, fmt: String, headerLen: Int): Footer {
        if (patch.size < headerLen + 12) throw PatchException(PatchError.CORRUPT_PATCH, Msg.corrupt(fmt, "it is too short"))
        val r = BeatReader(patch, 0, patch.size, fmt)
        val e = patch.size
        return Footer(r.le32(e - 12), r.le32(e - 8), r.le32(e - 4))
    }

    fun checkPatchCrc(patch: ByteArray, f: Footer, fmt: String, ctx: ApplyContext) {
        val actual = Checksums.crc32(patch, 0, patch.size - 4)
        if (actual != f.patchCrc) {
            ctx.soft(
                PatchError.PATCH_CHECKSUM,
                "The $fmt patch file is damaged (its checksum is ${Msg.hex(actual)}, expected ${Msg.hex(f.patchCrc)}). Try downloading it again.",
            )
        }
    }

    fun checkTarget(out: ByteArray, expectedCrc: Long, ctx: ApplyContext) {
        val crc = Checksums.crc32(out)
        if (crc != expectedCrc) {
            ctx.soft(
                PatchError.TARGET_MISMATCH,
                "The patched game doesn't match what the patch author intended (expected CRC32 ${Msg.hex(expectedCrc)}, got ${Msg.hex(crc)}). It may not work correctly.",
            )
        }
    }

    fun checkSize(n: Long, fmt: String) {
        if (n > Patcher.MAX_OUTPUT) throw PatchException(PatchError.UNSUPPORTED, "The $fmt patch describes a ${Msg.size(n)} file, which is too large.")
    }
}

internal object Ups {
    private const val FMT = "UPS"

    fun inspect(patch: ByteArray): PatchInfo {
        val f = Beat.footer(patch, FMT, 4)
        val r = BeatReader(patch, 4, patch.size - 12, FMT)
        val src = r.varint()
        val tgt = r.varint()
        return PatchInfo(PatchFormat.UPS, src, tgt, f.sourceCrc, f.targetCrc, null)
    }

    fun apply(source: ByteArray, patch: ByteArray, ctx: ApplyContext): Pair<ByteArray, PatchInfo> {
        val f = Beat.footer(patch, FMT, 4)
        Beat.checkPatchCrc(patch, f, FMT, ctx)
        val end = patch.size - 12
        val r = BeatReader(patch, 4, end, FMT)
        val srcSize = r.varint()
        val tgtSize = r.varint()
        Beat.checkSize(srcSize, FMT); Beat.checkSize(tgtSize, FMT)
        val info = PatchInfo(PatchFormat.UPS, srcSize, tgtSize, f.sourceCrc, f.targetCrc, null)

        // UPS is symmetric: it can turn the target back into the source as well.
        val crc = Checksums.crc32(source)
        val outSize: Long
        val expectCrc: Long
        if (source.size.toLong() == srcSize && crc == f.sourceCrc) {
            outSize = tgtSize; expectCrc = f.targetCrc
        } else if (source.size.toLong() == tgtSize && crc == f.targetCrc) {
            outSize = srcSize; expectCrc = f.sourceCrc
            ctx.warnings += "The selected ROM is already the patched version; the patch was applied in reverse to restore the original."
        } else {
            ctx.soft(PatchError.SOURCE_MISMATCH, Msg.wrongSource(f.sourceCrc, srcSize, source, crc))
            outSize = tgtSize; expectCrc = f.targetCrc
        }

        val n = outSize.toInt()
        val out = ByteArray(n)
        System.arraycopy(source, 0, out, 0, minOf(source.size, n))
        val buf = patch
        var pos = 0L
        var p = 4
        // Skip the two header varints again (cheap) using the reader position.
        p = r.pos
        var iter = 0
        while (p < end) {
            r.pos = p
            pos += r.varint()
            p = r.pos
            while (true) {
                if (p >= end) throw PatchException(PatchError.CORRUPT_PATCH, Msg.corrupt(FMT, "a record is cut off"))
                val x = buf[p++]
                if (pos < n) out[pos.toInt()] = (out[pos.toInt()].toInt() xor x.toInt()).toByte()
                pos++
                if (x.toInt() == 0) break
            }
            if ((++iter and 0x3FF) == 0) ctx.progress(p.toLong(), end.toLong())
        }
        Beat.checkTarget(out, expectCrc, ctx)
        return out to info
    }
}

internal object Bps {
    private const val FMT = "BPS"

    private class Header(val src: Long, val tgt: Long, val metadata: String?, val dataStart: Int)

    private fun header(patch: ByteArray): Header {
        val r = BeatReader(patch, 4, patch.size - 12, FMT)
        val src = r.varint()
        val tgt = r.varint()
        val metaLen = r.varint()
        if (metaLen > patch.size - 12 - r.pos) throw PatchException(PatchError.CORRUPT_PATCH, Msg.corrupt(FMT, "bad metadata length"))
        val meta = if (metaLen > 0) String(patch, r.pos, metaLen.toInt(), Charsets.UTF_8) else null
        return Header(src, tgt, meta, r.pos + metaLen.toInt())
    }

    fun inspect(patch: ByteArray): PatchInfo {
        val f = Beat.footer(patch, FMT, 4)
        val h = header(patch)
        return PatchInfo(PatchFormat.BPS, h.src, h.tgt, f.sourceCrc, f.targetCrc, h.metadata)
    }

    fun apply(source: ByteArray, patch: ByteArray, ctx: ApplyContext): Pair<ByteArray, PatchInfo> {
        val f = Beat.footer(patch, FMT, 4)
        Beat.checkPatchCrc(patch, f, FMT, ctx)
        val h = header(patch)
        Beat.checkSize(h.src, FMT); Beat.checkSize(h.tgt, FMT)
        val info = PatchInfo(PatchFormat.BPS, h.src, h.tgt, f.sourceCrc, f.targetCrc, h.metadata)
        val crc = Checksums.crc32(source)
        if (source.size.toLong() != h.src || crc != f.sourceCrc) {
            ctx.soft(PatchError.SOURCE_MISMATCH, Msg.wrongSource(f.sourceCrc, h.src, source, crc))
        }

        val end = patch.size - 12
        val r = BeatReader(patch, h.dataStart, end, FMT)
        val n = h.tgt.toInt()
        val out = ByteArray(n)
        var outOff = 0
        var srcRel = 0L
        var tgtRel = 0L
        var iter = 0
        while (r.pos < end) {
            val data = r.varint()
            val len = (data ushr 2) + 1
            if (len > n - outOff) throw PatchException(PatchError.CORRUPT_PATCH, Msg.corrupt(FMT, "it writes past the end of the game"))
            val l = len.toInt()
            when ((data and 3).toInt()) {
                0 -> { // SourceRead
                    if (outOff + l > source.size) throw tooSmall(source, h.src)
                    System.arraycopy(source, outOff, out, outOff, l)
                }
                1 -> { // TargetRead
                    if (l > end - r.pos) throw PatchException(PatchError.CORRUPT_PATCH, Msg.corrupt(FMT, "it ends unexpectedly"))
                    System.arraycopy(patch, r.pos, out, outOff, l)
                    r.pos += l
                }
                2 -> { // SourceCopy
                    val d = r.varint()
                    srcRel += if (d and 1L != 0L) -(d ushr 1) else (d ushr 1)
                    if (srcRel < 0) throw PatchException(PatchError.CORRUPT_PATCH, Msg.corrupt(FMT, "invalid source offset"))
                    if (srcRel + l > source.size) throw tooSmall(source, h.src)
                    System.arraycopy(source, srcRel.toInt(), out, outOff, l)
                    srcRel += l
                }
                else -> { // TargetCopy
                    val d = r.varint()
                    tgtRel += if (d and 1L != 0L) -(d ushr 1) else (d ushr 1)
                    if (tgtRel < 0 || tgtRel >= outOff) throw PatchException(PatchError.CORRUPT_PATCH, Msg.corrupt(FMT, "invalid target offset"))
                    var t = tgtRel.toInt()
                    if (t + l <= outOff) {
                        System.arraycopy(out, t, out, outOff, l)
                    } else {
                        // Overlapping copy (repeating pattern): must go byte by byte.
                        for (i in 0 until l) out[outOff + i] = out[t + i]
                    }
                    t += l
                    tgtRel = t.toLong()
                }
            }
            outOff += l
            if ((++iter and 0x3FF) == 0) ctx.progress(outOff.toLong(), n.toLong())
        }
        if (outOff != n) ctx.soft(PatchError.CORRUPT_PATCH, Msg.corrupt(FMT, "it produced only $outOff of $n bytes"))
        Beat.checkTarget(out, f.targetCrc, ctx)
        return out to info
    }

    private fun tooSmall(source: ByteArray, expected: Long) = PatchException(
        PatchError.SOURCE_MISMATCH,
        "This patch expects a different base game: it needs a ${Msg.size(expected)} ROM but yours is ${Msg.size(source.size.toLong())}.",
    )
}

package app.retra.patcher

/**
 * Minimal .xz (LZMA2-only) decoder, used for xdelta3's "lzma" secondary compression.
 * xdelta3 compresses each VCDIFF section with liblzma's easy encoder (xz container, no check).
 * Output size is known in advance, so the whole output buffer doubles as the LZ dictionary.
 */
internal object Xz {
    private fun corrupt(detail: String) = PatchException(PatchError.CORRUPT_PATCH, Msg.corrupt("xdelta", "compressed section: $detail"))

    fun decode(inp: ByteArray, off: Int, len: Int, outSize: Int): ByteArray {
        val end = off + len
        val magic = byteArrayOf(0xFD.toByte(), '7'.code.toByte(), 'z'.code.toByte(), 'X'.code.toByte(), 'Z'.code.toByte(), 0)
        if (len < 12 + 12) throw corrupt("too short")
        for (i in magic.indices) if (inp[off + i] != magic[i]) throw corrupt("bad xz header")
        if (inp[off + 6].toInt() != 0) throw corrupt("bad xz flags")
        val checkType = inp[off + 7].toInt() and 0x0F
        val checkSize = when (checkType) {
            0 -> 0
            in 1..3 -> 4
            in 4..6 -> 8
            in 7..9 -> 16
            in 10..12 -> 32
            else -> 64
        }
        val out = ByteArray(outSize)
        val lz = Lzma2Decoder(inp, out)
        var p = off + 12
        while (true) {
            if (p >= end) throw corrupt("truncated")
            val hb = inp[p].toInt() and 0xFF
            if (hb == 0) break // index: no more blocks
            val hSize = (hb + 1) * 4
            if (p + hSize > end) throw corrupt("truncated block header")
            val flags = inp[p + 1].toInt() and 0xFF
            val filters = (flags and 3) + 1
            var q = p + 2
            fun vli(): Long {
                var r = 0L
                var shift = 0
                while (true) {
                    if (q >= p + hSize || shift > 63) throw corrupt("bad block header")
                    val b = inp[q++].toInt() and 0xFF
                    r = r or ((b and 0x7F).toLong() shl shift)
                    if (b and 0x80 == 0) return r
                    shift += 7
                }
            }
            if (flags and 0x40 != 0) vli()
            if (flags and 0x80 != 0) vli()
            for (i in 0 until filters) {
                val id = vli()
                val propSize = vli()
                q += propSize.toInt()
                if (id != 0x21L || filters != 1) {
                    throw PatchException(PatchError.UNSUPPORTED, "This xdelta patch uses an unsupported xz filter (0x${id.toString(16)}).")
                }
            }
            p += hSize
            p = lz.decode(p, end)
            while ((p - off) and 3 != 0) p++ // block padding
            p += checkSize
        }
        if (lz.outPos != outSize) throw corrupt("decompressed ${lz.outPos} of $outSize bytes")
        return out
    }
}

internal class Lzma2Decoder(private val inp: ByteArray, private val out: ByteArray) {
    var outPos = 0
        private set

    private var ip = 0
    private var ipEnd = 0
    private var range = 0
    private var code = 0

    private var lc = 0
    private var lp = 0
    private var pb = 0
    private var state = 0
    private var rep0 = 0
    private var rep1 = 0
    private var rep2 = 0
    private var rep3 = 0
    private var dictStart = 0
    private var pending = 0
    private var needDictReset = true
    private var needProps = true

    private val probs = ShortArray(TOTAL)

    private fun corrupt(detail: String) = PatchException(PatchError.CORRUPT_PATCH, Msg.corrupt("xdelta", "LZMA data: $detail"))

    /** Decodes LZMA2 chunks starting at [start]; returns the position after the end marker. */
    fun decode(start: Int, limit: Int): Int {
        var p = start
        while (true) {
            if (p >= limit) throw corrupt("truncated")
            val c = inp[p++].toInt() and 0xFF
            if (c == 0) return p
            if (c == 1 || c == 2) {
                if (c == 1) {
                    dictStart = outPos; needDictReset = false
                } else if (needDictReset) throw corrupt("missing dictionary reset")
                if (p + 2 > limit) throw corrupt("truncated")
                val size = (((inp[p].toInt() and 0xFF) shl 8) or (inp[p + 1].toInt() and 0xFF)) + 1
                p += 2
                if (p + size > limit || outPos + size > out.size) throw corrupt("bad chunk size")
                System.arraycopy(inp, p, out, outPos, size)
                outPos += size
                p += size
                continue
            }
            if (c < 0x80) throw corrupt("bad chunk type")
            if (p + 4 > limit) throw corrupt("truncated")
            val uSize = ((c and 0x1F) shl 16) + ((inp[p].toInt() and 0xFF) shl 8) + (inp[p + 1].toInt() and 0xFF) + 1
            val cSize = ((inp[p + 2].toInt() and 0xFF) shl 8) + (inp[p + 3].toInt() and 0xFF) + 1
            p += 4
            val reset = (c ushr 5) and 3
            if (reset == 3) {
                dictStart = outPos; needDictReset = false
            } else if (needDictReset) throw corrupt("missing dictionary reset")
            if (reset >= 2) {
                if (p >= limit) throw corrupt("truncated")
                var props = inp[p++].toInt() and 0xFF
                if (props > 224) throw corrupt("bad properties")
                pb = props / 45; props %= 45
                lp = props / 9; lc = props % 9
                if (lc + lp > 4) throw corrupt("bad properties")
                needProps = false
            } else if (needProps) throw corrupt("missing properties")
            if (reset >= 1) resetState()
            if (p + cSize > limit || cSize < 5) throw corrupt("bad chunk size")
            if (outPos + uSize > out.size) throw corrupt("too much data")
            ip = p
            ipEnd = p + cSize
            if (inp[ip].toInt() != 0) throw corrupt("bad range coder start")
            code = ((inp[ip + 1].toInt() and 0xFF) shl 24) or ((inp[ip + 2].toInt() and 0xFF) shl 16) or
                ((inp[ip + 3].toInt() and 0xFF) shl 8) or (inp[ip + 4].toInt() and 0xFF)
            ip += 5
            range = -1
            decodeChunk(outPos + uSize)
            p += cSize
        }
    }

    private fun resetState() {
        java.util.Arrays.fill(probs, 1024.toShort())
        state = 0
        rep0 = 0; rep1 = 0; rep2 = 0; rep3 = 0
        pending = 0
    }

    private fun bit(i: Int): Int {
        if (range and 0xFF000000.toInt() == 0) {
            if (ip >= ipEnd) throw corrupt("truncated chunk")
            code = (code shl 8) or (inp[ip++].toInt() and 0xFF)
            range = range shl 8
        }
        val prob = probs[i].toInt()
        val bound = (range ushr 11) * prob
        return if ((code xor Int.MIN_VALUE) < (bound xor Int.MIN_VALUE)) {
            range = bound
            probs[i] = (prob + ((2048 - prob) ushr 5)).toShort()
            0
        } else {
            range -= bound
            code -= bound
            probs[i] = (prob - (prob ushr 5)).toShort()
            1
        }
    }

    private fun tree(base: Int, size: Int): Int {
        var s = 1
        while (s < size) s = (s shl 1) or bit(base + s)
        return s - size
    }

    private fun reverseTree(base: Int, size: Int): Int {
        var s = 1
        var i = 0
        var result = 0
        do {
            val b = bit(base + s)
            s = (s shl 1) or b
            result = result or (b shl i++)
        } while (s < size)
        return result
    }

    private fun direct(count: Int): Int {
        var result = 0
        repeat(count) {
            if (range and 0xFF000000.toInt() == 0) {
                if (ip >= ipEnd) throw corrupt("truncated chunk")
                code = (code shl 8) or (inp[ip++].toInt() and 0xFF)
                range = range shl 8
            }
            range = range ushr 1
            val t = (code - range) ushr 31
            code -= range and (t - 1)
            result = (result shl 1) or (1 - t)
        }
        return result
    }

    private fun length(base: Int, posState: Int): Int {
        if (bit(base) == 0) return tree(base + 2 + posState * 8, 8) + 2
        if (bit(base + 1) == 0) return tree(base + 2 + 128 + posState * 8, 8) + 10
        return tree(base + 2 + 256, 256) + 18
    }

    private fun copyMatch(len: Int, limit: Int) {
        val dist = rep0 + 1
        val n = minOf(len, limit - outPos)
        var src = outPos - dist
        if (dist >= n) {
            System.arraycopy(out, src, out, outPos, n)
            outPos += n
        } else {
            for (k in 0 until n) out[outPos++] = out[src++]
        }
        pending = len - n
    }

    private fun decodeChunk(limit: Int) {
        if (pending > 0) copyMatch(pending, limit)
        val pbMask = (1 shl pb) - 1
        val lpMask = (1 shl lp) - 1
        while (outPos < limit) {
            val posState = outPos and pbMask
            if (bit(IS_MATCH + (state shl 4) + posState) == 0) {
                val prev = if (outPos > dictStart) out[outPos - 1].toInt() and 0xFF else 0
                val base = LITERAL + 0x300 * (((outPos and lpMask) shl lc) + (prev ushr (8 - lc)))
                var s = 1
                if (state < 7) {
                    while (s < 0x100) s = (s shl 1) or bit(base + s)
                } else {
                    var matchByte = out[outPos - rep0 - 1].toInt() and 0xFF
                    var offset = 0x100
                    while (s < 0x100) {
                        matchByte = matchByte shl 1
                        val matchBit = matchByte and offset
                        val b = bit(base + offset + matchBit + s)
                        s = (s shl 1) or b
                        offset = offset and ((0 - b) xor matchBit.inv())
                    }
                }
                out[outPos++] = s.toByte()
                state = if (state < 4) 0 else if (state < 10) state - 3 else state - 6
                continue
            }
            val len: Int
            if (bit(IS_REP + state) == 0) {
                state = if (state < 7) 7 else 10
                rep3 = rep2; rep2 = rep1; rep1 = rep0
                len = length(MATCH_LEN, posState)
                val slot = tree(DIST_SLOT + (minOf(len - 2, 3) shl 6), 64)
                if (slot < 4) {
                    rep0 = slot
                } else {
                    val bits = (slot ushr 1) - 1
                    var d = (2 or (slot and 1)) shl bits
                    if (slot < 14) {
                        d = d or reverseTree(SPECIAL_OFF[slot - 4], 1 shl bits)
                    } else {
                        d = d or (direct(bits - 4) shl 4)
                        d = d or reverseTree(ALIGN, 16)
                    }
                    rep0 = d
                }
            } else {
                if (bit(IS_REP0 + state) == 0) {
                    if (bit(IS_REP0_LONG + (state shl 4) + posState) == 0) {
                        state = if (state < 7) 9 else 11
                        if (rep0 < 0 || rep0 >= outPos - dictStart) throw corrupt("bad distance")
                        out[outPos] = out[outPos - rep0 - 1]
                        outPos++
                        continue
                    }
                } else {
                    val tmp: Int
                    if (bit(IS_REP1 + state) == 0) {
                        tmp = rep1
                    } else {
                        if (bit(IS_REP2 + state) == 0) {
                            tmp = rep2
                        } else {
                            tmp = rep3; rep3 = rep2
                        }
                        rep2 = rep1
                    }
                    rep1 = rep0; rep0 = tmp
                }
                state = if (state < 7) 8 else 11
                len = length(REP_LEN, posState)
            }
            if (rep0 < 0 || rep0 >= outPos - dictStart) throw corrupt("bad distance")
            copyMatch(len, limit)
        }
    }

    private companion object {
        const val IS_MATCH = 0
        const val IS_REP = IS_MATCH + 192
        const val IS_REP0 = IS_REP + 12
        const val IS_REP1 = IS_REP0 + 12
        const val IS_REP2 = IS_REP1 + 12
        const val IS_REP0_LONG = IS_REP2 + 12
        const val DIST_SLOT = IS_REP0_LONG + 192
        const val SPECIAL = DIST_SLOT + 4 * 64
        val SPECIAL_OFF = IntArray(10).also {
            var o = SPECIAL
            for (i in 0 until 10) {
                it[i] = o; o += 1 shl ((i + 4 ushr 1) - 1)
            }
        }
        const val ALIGN = SPECIAL + 124
        const val MATCH_LEN = ALIGN + 16
        const val REP_LEN = MATCH_LEN + 514
        const val LITERAL = REP_LEN + 514
        const val TOTAL = LITERAL + 0x300 * 16
    }
}

package app.retra.patcher

import java.util.zip.Adler32

/**
 * VCDIFF (RFC 3284) decoder with the xdelta3 extensions: VCD_ADLER32 per-window checksums,
 * application header, and LZMA secondary compression. DJW/FGK secondary compression and
 * application-defined code tables are reported as unsupported.
 */
internal object Vcdiff {
    private const val FMT = "xdelta"

    private const val VCD_DECOMPRESS = 0x01
    private const val VCD_CODETABLE = 0x02
    private const val VCD_APPHEADER = 0x04

    private const val VCD_SOURCE = 0x01
    private const val VCD_TARGET = 0x02
    private const val VCD_ADLER32 = 0x04

    private const val NOOP = 0
    private const val ADD = 1
    private const val RUN = 2
    private const val COPY = 3

    private const val NEAR = 4
    private const val SAME = 3

    // Default code table (RFC 3284 section 5.6).
    private val TYPE1 = IntArray(256)
    private val SIZE1 = IntArray(256)
    private val MODE1 = IntArray(256)
    private val TYPE2 = IntArray(256)
    private val SIZE2 = IntArray(256)
    private val MODE2 = IntArray(256)

    init {
        var i = 0
        TYPE1[i] = RUN; i++
        for (s in 0..17) { TYPE1[i] = ADD; SIZE1[i] = s; i++ }
        for (m in 0..8) {
            TYPE1[i] = COPY; SIZE1[i] = 0; MODE1[i] = m; i++
            for (s in 4..18) { TYPE1[i] = COPY; SIZE1[i] = s; MODE1[i] = m; i++ }
        }
        for (m in 0..5) for (a in 1..4) for (c in 4..6) {
            TYPE1[i] = ADD; SIZE1[i] = a; TYPE2[i] = COPY; SIZE2[i] = c; MODE2[i] = m; i++
        }
        for (m in 6..8) for (a in 1..4) {
            TYPE1[i] = ADD; SIZE1[i] = a; TYPE2[i] = COPY; SIZE2[i] = 4; MODE2[i] = m; i++
        }
        for (m in 0..8) {
            TYPE1[i] = COPY; SIZE1[i] = 4; MODE1[i] = m; TYPE2[i] = ADD; SIZE2[i] = 1; i++
        }
        check(i == 256)
    }

    private fun corrupt(detail: String) = PatchException(PatchError.CORRUPT_PATCH, Msg.corrupt(FMT, detail))

    private class Reader(val buf: ByteArray, var pos: Int, var end: Int) {
        fun u8(): Int {
            if (pos >= end) throw corrupt("it ends unexpectedly")
            return buf[pos++].toInt() and 0xFF
        }

        fun varint(): Long {
            var r = 0L
            for (i in 0 until 10) {
                val b = u8()
                r = (r shl 7) or (b and 0x7F).toLong()
                if (b and 0x80 == 0) {
                    if (r < 0) throw corrupt("invalid number")
                    return r
                }
            }
            throw corrupt("invalid number")
        }

        fun int(what: String): Int {
            val v = varint()
            if (v > Int.MAX_VALUE) throw corrupt("$what is too large")
            return v.toInt()
        }
    }

    private class Header(val secondaryId: Int?, val hasCodeTable: Boolean, val appHeader: String?, val windowsStart: Int)

    private class Window(
        val indicator: Int, val segLen: Long, val segPos: Long, val targetLen: Int, val deltaInd: Int,
        val dataLen: Int, val instLen: Int, val addrLen: Int, val adler: Long?, val sectionsStart: Int,
    )

    private fun header(patch: ByteArray): Header {
        val r = Reader(patch, 4, patch.size)
        val ind = r.u8()
        if (ind and 0xF8 != 0) throw corrupt("unknown header flags")
        var secondary: Int? = null
        if (ind and VCD_DECOMPRESS != 0) secondary = r.u8()
        val hasTable = ind and VCD_CODETABLE != 0
        if (hasTable) {
            val n = r.int("code table")
            if (n > r.end - r.pos) throw corrupt("bad code table length")
            r.pos += n
        }
        var app: String? = null
        if (ind and VCD_APPHEADER != 0) {
            val n = r.int("application header")
            if (n > r.end - r.pos) throw corrupt("bad header length")
            app = String(patch, r.pos, n, Charsets.UTF_8)
            r.pos += n
        }
        return Header(secondary, hasTable, app, r.pos)
    }

    private fun windows(patch: ByteArray, start: Int): List<Window> {
        val list = ArrayList<Window>()
        val r = Reader(patch, start, patch.size)
        while (r.pos < r.end) {
            val ind = r.u8()
            if (ind and 0xF8 != 0 || (ind and VCD_SOURCE != 0 && ind and VCD_TARGET != 0)) throw corrupt("bad window flags")
            var segLen = 0L
            var segPos = 0L
            if (ind and (VCD_SOURCE or VCD_TARGET) != 0) {
                segLen = r.varint(); segPos = r.varint()
            }
            val deltaLen = r.int("window")
            val deltaStart = r.pos
            if (deltaLen > r.end - deltaStart) throw corrupt("a window is cut off")
            val tgtLen = r.int("window")
            val deltaInd = r.u8()
            val dataLen = r.int("data section")
            val instLen = r.int("instruction section")
            val addrLen = r.int("address section")
            var adler: Long? = null
            if (ind and VCD_ADLER32 != 0) {
                adler = (r.u8().toLong() shl 24) or (r.u8().toLong() shl 16) or (r.u8().toLong() shl 8) or r.u8().toLong()
            }
            val sections = r.pos
            if (sections.toLong() + dataLen + instLen + addrLen != deltaStart.toLong() + deltaLen) throw corrupt("inconsistent window sizes")
            list += Window(ind, segLen, segPos, tgtLen, deltaInd, dataLen, instLen, addrLen, adler, sections)
            r.pos = deltaStart + deltaLen
        }
        return list
    }

    fun inspect(patch: ByteArray): PatchInfo {
        val h = header(patch)
        val ws = windows(patch, h.windowsStart)
        val total = ws.sumOf { it.targetLen.toLong() }
        return PatchInfo(PatchFormat.VCDIFF, null, total, null, null, h.appHeader)
    }

    private fun secondaryName(id: Int?) = when (id) {
        1 -> "DJW"
        2 -> "LZMA"
        16 -> "FGK"
        null -> "unknown"
        else -> "unknown (#$id)"
    }

    fun apply(sourceIn: ByteArray, patch: ByteArray, ctx: ApplyContext): Pair<ByteArray, PatchInfo> {
        val h = header(patch)
        if (h.hasCodeTable) {
            throw PatchException(PatchError.UNSUPPORTED, "This xdelta patch uses a custom code table, which isn't supported.")
        }
        val ws = windows(patch, h.windowsStart)
        val total = ws.sumOf { it.targetLen.toLong() }
        if (total > Patcher.MAX_OUTPUT) throw PatchException(PatchError.UNSUPPORTED, "The patched game would be too large (${Msg.size(total)}).")
        val info = PatchInfo(PatchFormat.VCDIFF, null, total, null, null, h.appHeader)

        // Source bounds check (xdelta has no source checksum; size is the only up-front hint).
        var source = sourceIn
        val needed = ws.filter { it.indicator and VCD_SOURCE != 0 }.maxOfOrNull { it.segPos + it.segLen } ?: 0L
        if (needed > source.size) {
            val msg = if (source.isEmpty()) "This xdelta patch needs a base ROM, but none was provided."
            else "This patch expects a different base game: it reads ${Msg.size(needed)} of base ROM but yours is only ${Msg.size(source.size.toLong())}."
            if (ctx.strict || needed > Patcher.MAX_OUTPUT) throw PatchException(PatchError.SOURCE_MISMATCH, msg)
            ctx.warnings += msg
            source = source.copyOf(needed.toInt())
        }

        val out = ByteArray(total.toInt())
        val near = IntArray(NEAR)
        val same = IntArray(SAME * 256)
        val adler = Adler32()
        var outBase = 0
        var checksumWarned = false
        for (w in ws) {
            // Resolve sections (decompressing secondary-compressed ones).
            var dataBuf = patch; var dataPos = w.sectionsStart; var dataEnd = dataPos + w.dataLen
            var instBuf = patch; var instPos = dataEnd; var instEnd = instPos + w.instLen
            var addrBuf = patch; var addrPos = instEnd; var addrEnd = addrPos + w.addrLen
            if (w.deltaInd and 0x07.inv() != 0) throw corrupt("bad window flags")
            if (w.deltaInd != 0) {
                if (h.secondaryId != 2) {
                    if (h.secondaryId == null) throw corrupt("compressed section without a compressor")
                    throw PatchException(
                        PatchError.UNSUPPORTED,
                        "This xdelta patch uses ${secondaryName(h.secondaryId)} secondary compression, which isn't supported. " +
                            "Ask for a patch made with default settings or \"xdelta3 -S none\".",
                    )
                }
                if (w.deltaInd and 1 != 0) { val b = lzmaSection(patch, dataPos, dataEnd); dataBuf = b; dataPos = 0; dataEnd = b.size }
                if (w.deltaInd and 2 != 0) { val b = lzmaSection(patch, instPos, instEnd); instBuf = b; instPos = 0; instEnd = b.size }
                if (w.deltaInd and 4 != 0) { val b = lzmaSection(patch, addrPos, addrEnd); addrBuf = b; addrPos = 0; addrEnd = b.size }
            }
            val data = Reader(dataBuf, dataPos, dataEnd)
            val inst = Reader(instBuf, instPos, instEnd)
            val addr = Reader(addrBuf, addrPos, addrEnd)

            val segBuf: ByteArray
            val segStart: Int
            val segLen: Int
            when {
                w.indicator and VCD_SOURCE != 0 -> { segBuf = source; segStart = w.segPos.toInt(); segLen = w.segLen.toInt() }
                w.indicator and VCD_TARGET != 0 -> {
                    if (w.segPos + w.segLen > outBase) throw corrupt("window refers to data not yet produced")
                    segBuf = out; segStart = w.segPos.toInt(); segLen = w.segLen.toInt()
                }
                else -> { segBuf = out; segStart = 0; segLen = 0 }
            }
            val tLen = w.targetLen
            if (outBase.toLong() + tLen > out.size) throw corrupt("window too large")

            java.util.Arrays.fill(near, 0)
            java.util.Arrays.fill(same, 0)
            var nextSlot = 0
            var t = 0 // position within this target window
            while (inst.pos < inst.end) {
                val op = inst.u8()
                for (half in 0..1) {
                    val type = if (half == 0) TYPE1[op] else TYPE2[op]
                    if (type == NOOP) continue
                    var size = if (half == 0) SIZE1[op] else SIZE2[op]
                    if (size == 0) size = inst.int("instruction")
                    if (size > tLen - t) throw corrupt("instruction writes past the window")
                    val dst = outBase + t
                    when (type) {
                        ADD -> {
                            if (size > data.end - data.pos) throw corrupt("data section too short")
                            System.arraycopy(data.buf, data.pos, out, dst, size)
                            data.pos += size
                        }
                        RUN -> java.util.Arrays.fill(out, dst, dst + size, data.u8().toByte())
                        else -> {
                            val mode = if (half == 0) MODE1[op] else MODE2[op]
                            val here = segLen.toLong() + t
                            val a: Long = when {
                                mode == 0 -> addr.varint()
                                mode == 1 -> here - addr.varint()
                                mode < 2 + NEAR -> near[mode - 2].toLong() + addr.varint()
                                else -> same[(mode - 2 - NEAR) * 256 + addr.u8()].toLong()
                            }
                            if (a < 0 || a >= here) throw corrupt("invalid copy address")
                            val ai = a.toInt()
                            near[nextSlot] = ai; nextSlot = (nextSlot + 1) % NEAR
                            same[ai % (SAME * 256)] = ai
                            if (ai < segLen) {
                                if (ai + size <= segLen) {
                                    System.arraycopy(segBuf, segStart + ai, out, dst, size)
                                } else {
                                    // Spans from the source segment into the target window.
                                    val first = segLen - ai
                                    System.arraycopy(segBuf, segStart + ai, out, dst, first)
                                    var s = outBase
                                    for (k in first until size) out[dst + k] = out[s++]
                                }
                            } else {
                                val s = outBase + (ai - segLen)
                                if (s + size <= dst) System.arraycopy(out, s, out, dst, size)
                                else for (k in 0 until size) out[dst + k] = out[s + k]
                            }
                        }
                    }
                    t += size
                }
            }
            if (t != tLen) throw corrupt("a window produced ${t} of $tLen bytes")
            if (w.adler != null) {
                adler.reset()
                adler.update(out, outBase, tLen)
                if (adler.value != w.adler && !checksumWarned) {
                    checksumWarned = true
                    val usesSource = ws.any { it.indicator and VCD_SOURCE != 0 }
                    if (usesSource) {
                        ctx.soft(PatchError.SOURCE_MISMATCH, "The patched game doesn't match what the patch expects. This patch was most likely made for a different base game (yours has CRC32 ${Checksums.crc32Hex(sourceIn)}).")
                    } else {
                        ctx.soft(PatchError.TARGET_MISMATCH, "The patched game doesn't match the checksum stored in the patch. The patch may be damaged.")
                    }
                }
            }
            outBase += tLen
            ctx.progress(outBase.toLong(), total)
        }
        return out to info
    }

    private fun lzmaSection(patch: ByteArray, start: Int, end: Int): ByteArray {
        val r = Reader(patch, start, end)
        val size = r.int("compressed section")
        if (size > Patcher.MAX_OUTPUT) throw corrupt("compressed section too large")
        return Xz.decode(patch, r.pos, end - r.pos, size)
    }
}

package app.retra.patcher

import java.io.ByteArrayOutputStream

/**
 * Creates BPS patches (greedy, hash-based matcher: linear time, good enough for ROM hacks).
 */
object BpsCreator {
    private const val MIN_MATCH = 4
    private const val HASH_BITS = 20

    fun create(source: ByteArray, target: ByteArray, metadata: String? = null): ByteArray {
        val out = Out(target.size / 4 + 64)
        out.ascii("BPS1")
        out.varint(source.size.toLong())
        out.varint(target.size.toLong())
        val meta = metadata?.toByteArray(Charsets.UTF_8) ?: ByteArray(0)
        out.varint(meta.size.toLong())
        out.write(meta, 0, meta.size)

        val mask = (1 shl HASH_BITS) - 1
        val srcTable = IntArray(1 shl HASH_BITS) { -1 }
        for (i in 0..source.size - MIN_MATCH) srcTable[hash(source, i) and mask] = i
        val tgtTable = IntArray(1 shl HASH_BITS) { -1 }

        val n = target.size
        var i = 0
        var pendingStart = -1
        var srcRel = 0L
        var tgtRel = 0L
        var tgtHashed = 0 // target positions below this are in tgtTable

        fun flushPending(upTo: Int) {
            if (pendingStart < 0) return
            val len = upTo - pendingStart
            out.varint(((len - 1).toLong() shl 2) or 1L)
            out.write(target, pendingStart, len)
            pendingStart = -1
        }

        while (i < n) {
            // Candidate 1: SourceRead (same offset).
            var readLen = 0
            while (i + readLen < n && i + readLen < source.size && source[i + readLen] == target[i + readLen]) readLen++

            var srcLen = 0
            var srcPos = 0
            var tgtLen = 0
            var tgtPos = 0
            if (i + MIN_MATCH <= n) {
                val h = hash(target, i) and mask
                val s = srcTable[h]
                if (s >= 0 && s != i) {
                    var k = 0
                    while (i + k < n && s + k < source.size && source[s + k] == target[i + k]) k++
                    srcLen = k; srcPos = s
                }
                val t = tgtTable[h]
                if (t >= 0) {
                    var k = 0
                    while (i + k < n && target[t + k] == target[i + k]) k++
                    tgtLen = k; tgtPos = t
                }
            }

            val best = maxOf(readLen, srcLen, tgtLen)
            if (best < MIN_MATCH && !(readLen > 0 && readLen == n - i)) {
                if (pendingStart < 0) pendingStart = i
                i++
            } else {
                flushPending(i)
                val len: Int
                if (readLen >= srcLen && readLen >= tgtLen) {
                    len = readLen
                    out.varint((len - 1).toLong() shl 2)
                } else if (srcLen >= tgtLen) {
                    len = srcLen
                    out.varint(((len - 1).toLong() shl 2) or 2L)
                    val d = srcPos - srcRel
                    out.varint(if (d < 0) ((-d) shl 1) or 1L else d shl 1)
                    srcRel = srcPos.toLong() + len
                } else {
                    len = tgtLen
                    out.varint(((len - 1).toLong() shl 2) or 3L)
                    val d = tgtPos - tgtRel
                    out.varint(if (d < 0) ((-d) shl 1) or 1L else d shl 1)
                    tgtRel = tgtPos.toLong() + len
                }
                i += len
            }
            // Index target positions we've moved past (limit work inside long matches).
            val step = if (i - tgtHashed > 4096) 16 else 1
            while (tgtHashed + MIN_MATCH <= minOf(i, n)) {
                tgtTable[hash(target, tgtHashed) and mask] = tgtHashed
                tgtHashed += step
            }
            tgtHashed = maxOf(tgtHashed, i - MIN_MATCH + 1).coerceAtLeast(0)
        }
        flushPending(n)

        out.le32(Checksums.crc32(source))
        out.le32(Checksums.crc32(target))
        out.le32(Checksums.crc32(out.buf(), 0, out.size()))
        return out.toByteArray()
    }

    private fun hash(b: ByteArray, i: Int): Int {
        val v = (b[i].toInt() and 0xFF) or ((b[i + 1].toInt() and 0xFF) shl 8) or
            ((b[i + 2].toInt() and 0xFF) shl 16) or ((b[i + 3].toInt() and 0xFF) shl 24)
        return (v * -0x61c88647) ushr (32 - HASH_BITS)
    }

    private class Out(cap: Int) : ByteArrayOutputStream(cap) {
        fun buf(): ByteArray = buf

        fun ascii(s: String) = s.forEach { write(it.code) }

        fun varint(v: Long) {
            var data = v
            while (true) {
                val x = (data and 0x7F).toInt()
                data = data ushr 7
                if (data == 0L) {
                    write(0x80 or x); return
                }
                write(x)
                data--
            }
        }

        fun le32(v: Long) {
            for (k in 0 until 4) write(((v ushr (8 * k)) and 0xFF).toInt())
        }
    }
}

