package app.retra.ui

import androidx.compose.foundation.layout.PaddingValues
import androidx.compose.runtime.staticCompositionLocalOf
import androidx.compose.ui.unit.dp

enum class Tab { HOME, GAMES, STORE, PATCHER, SETTINGS }

/** Navigation + global actions available to every screen. */
interface AppActions {
    fun importGames()
    fun openGame(id: String, origin: String)
    fun play(id: String, resume: Boolean, origin: String)
    fun openStore(entryId: String? = null)
    fun openPatcher(baseGameId: String? = null)
    fun openTab(tab: Tab)
    fun openUrl(url: String)
    fun back()
}

object NoopActions : AppActions {
    override fun importGames() {}
    override fun openGame(id: String, origin: String) {}
    override fun play(id: String, resume: Boolean, origin: String) {}
    override fun openStore(entryId: String?) {}
    override fun openPatcher(baseGameId: String?) {}
    override fun openTab(tab: Tab) {}
    override fun openUrl(url: String) {}
    override fun back() {}
}

val LocalAppActions = staticCompositionLocalOf<AppActions> { NoopActions }

/** Space screens must leave at the bottom so content can scroll above the floating dock. */
val LocalDockPadding = staticCompositionLocalOf { PaddingValues(bottom = 112.dp) }

package app.retra.ui

import androidx.compose.foundation.layout.PaddingValues
import androidx.compose.foundation.layout.WindowInsets
import androidx.compose.foundation.layout.asPaddingValues
import androidx.compose.foundation.layout.safeDrawing
import androidx.compose.runtime.Composable
import androidx.compose.ui.platform.LocalLayoutDirection
import androidx.compose.foundation.layout.calculateStartPadding
import androidx.compose.foundation.layout.calculateEndPadding
import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.dp
import app.retra.ui.theme.Space

/** Vertical padding for a full-screen scrolling list: status bar + [top] above, dock below. */
@Composable
fun listPadding(top: Dp = Space.m, bottomExtra: Dp = 0.dp): PaddingValues {
    val insets = WindowInsets.safeDrawing.asPaddingValues()
    val dock = LocalDockPadding.current
    return PaddingValues(top = insets.calculateTopPadding() + top, bottom = dock.calculateBottomPadding() + bottomExtra)
}

/** Horizontal gutter including display cutouts (landscape). */
@Composable
fun gutter(): PaddingValues {
    val insets = WindowInsets.safeDrawing.asPaddingValues()
    val dir = LocalLayoutDirection.current
    return PaddingValues(start = insets.calculateStartPadding(dir) + Space.gutter, end = insets.calculateEndPadding(dir) + Space.gutter)
}

