@Composable
fun PatcherScreen(container: AppContainer, baseGameId: String?, patchPath: String?, patchName: String?) {
    val vm: PatcherViewModel = viewModel(factory = PatcherViewModel.factory(container))
    val state by vm.state.collectAsStateWithLifecycle()
    val games by vm.games.collectAsStateWithLifecycle()
    val context = LocalContext.current
    LaunchedEffect(baseGameId, patchPath) { vm.preselect(baseGameId, patchPath, patchName) }
    val pickBase = rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()) { it?.let(vm::chooseBaseFile) }
    val pickPatch = rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()) { it?.let(vm::choosePatchFile) }
    val export = rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("application/octet-stream")) { uri ->
        if (uri != null) vm.export(uri, context.contentResolver)
    }
    PatcherContent(
        state = state,
        games = games,
        onLibraryBase = vm::chooseLibraryBase,
        onBaseFile = { pickBase.launch(arrayOf("*/*")) },
        onPatchFile = { pickPatch.launch(arrayOf("*/*")) },
        onStrict = vm::setStrict,
        onName = vm::setOutputName,
        onApply = vm::apply,
        onAdd = vm::addToLibrary,
        onExport = { export.launch("${state.outputName.ifBlank { "patched" }}.gba") },
        onReset = vm::reset,
        onDismissError = vm::dismissError,
    )
}

@Composable
fun PatcherContent(
    state: PatcherState,
    games: List<Game>,
    onLibraryBase: (String) -> Unit = {},
    onBaseFile: () -> Unit = {},
    onPatchFile: () -> Unit = {},
    onStrict: (Boolean) -> Unit = {},
    onName: (String) -> Unit = {},
    onApply: () -> Unit = {},
    onAdd: () -> Unit = {},
    onExport: () -> Unit = {},
    onReset: () -> Unit = {},
    onDismissError: () -> Unit = {},
) {
    val c = Retra.colors
    val g = gutter()
    val actions = LocalAppActions.current
    var picking by remember { mutableStateOf(false) }
    val phase = state.phase
    Box(Modifier.fillMaxSize()) {
        LazyColumn(Modifier.fillMaxSize(), contentPadding = listPadding(Space.l)) {
            item("header") {
                ScreenHeader("Patcher", Modifier.padding(g), subtitle = "Turn a patch and a game you own into a new game")
            }
            if (phase is PatchPhase.Applying || phase is PatchPhase.Done) {
                item("progress") {
                    GlassSurface(Modifier.padding(g).padding(top = Space.l).fillMaxWidth(), shape = Radius.largeShape) {
                        Column(Modifier.fillMaxWidth().padding(Space.l), horizontalAlignment = Alignment.CenterHorizontally) {
                            PatchProgressRing((phase as? PatchPhase.Applying)?.progress ?: 1f, done = phase is PatchPhase.Done)
                            if (phase is PatchPhase.Done) {
                                Spacer(Modifier.height(Space.xs))
                                Text("${formatBytes(phase.size)} · CRC32 ${phase.crc32}", style = RetraType.label, color = c.inkMuted)
                                phase.warnings.forEach {
                                    Spacer(Modifier.height(Space.xs))
                                    Notice(Icons.Rounded.WarningAmber, it, c.warning)
                                }
                                Spacer(Modifier.height(Space.l))
                                if (phase.gameId != null) {
                                    RetraButton("Play now", { actions.play(phase.gameId, false, "patcher") }, Modifier.fillMaxWidth(), icon = Icons.Rounded.PlayArrow)
                                } else {
                                    RetraButton("Add to My Games", onAdd, Modifier.fillMaxWidth(), icon = Icons.Rounded.LibraryAdd)
                                }
                                Spacer(Modifier.height(Space.xs))
                                Row(horizontalArrangement = Arrangement.spacedBy(Space.s)) {
                                    RetraButton("Save .gba file", onExport, Modifier.weight(1f), icon = Icons.Rounded.SaveAlt, style = ButtonStyle.SECONDARY, compact = true)
                                    RetraButton("Patch another", onReset, Modifier.weight(1f), icon = Icons.Rounded.Refresh, style = ButtonStyle.SECONDARY, compact = true)
                                }
                            }
                        }
                    }
                }
                return@LazyColumn
            }
            item("base") {
                StepCard(1, "Base game", Modifier.padding(g).padding(top = Space.l).staggerIn(0), done = state.base != null) {
                    val b = state.base
                    if (b != null) {
                        Text(b.name, style = RetraType.bodyStrong, color = c.ink, maxLines = 1, overflow = TextOverflow.Ellipsis)
                        Text("${b.gameCode.ifBlank { "No code" }} · ${formatBytes(b.size)} · CRC32 ${b.crc32}", style = RetraType.caption, color = c.inkMuted)
                        Spacer(Modifier.height(Space.s))
                    } else {
                        Text("The clean ROM the patch was made for, dumped from your own cartridge.", style = RetraType.label, color = c.inkMuted)
                        Spacer(Modifier.height(Space.s))
                    }
                    Row(horizontalArrangement = Arrangement.spacedBy(Space.xs)) {
                        RetraButton("My Games", { picking = true }, Modifier.weight(1f), icon = Icons.Rounded.SportsEsports, style = ButtonStyle.SECONDARY, compact = true, enabled = games.isNotEmpty())
                        RetraButton("A file", onBaseFile, Modifier.weight(1f), icon = Icons.Rounded.FolderOpen, style = ButtonStyle.SECONDARY, compact = true)
                    }
                }
            }
            item("patch") {
                StepCard(2, "Patch", Modifier.padding(g).padding(top = Space.s).staggerIn(1), done = state.patch != null) {
                    val p = state.patch
                    if (p != null) {
                        Text(p.name, style = RetraType.bodyStrong, color = c.ink, maxLines = 1, overflow = TextOverflow.Ellipsis)
                        Text("${p.format} · ${formatBytes(p.size)}", style = RetraType.caption, color = c.inkMuted)
                        Spacer(Modifier.height(Space.xs))
                        InfoRow("Expects base", p.sourceCrc32?.let { "CRC32 $it" + (p.sourceSize?.let { s -> " · ${formatBytes(s)}" } ?: "") } ?: "Not recorded by ${p.format}")
                        InfoRow("Makes", p.targetCrc32?.let { "CRC32 $it" + (p.targetSize?.let { s -> " · ${formatBytes(s)}" } ?: "") } ?: p.targetSize?.let { formatBytes(it) } ?: "—")
                        p.metadata?.let { InfoRow("Notes", it) }
                        Spacer(Modifier.height(Space.xs))
                    } else {
                        Text("IPS, UPS, BPS or xdelta. Zips work too.", style = RetraType.label, color = c.inkMuted)
                        Spacer(Modifier.height(Space.s))
                    }
                    RetraButton(if (p == null) "Choose patch" else "Choose another", onPatchFile, Modifier.fillMaxWidth(), icon = Icons.Rounded.Description, style = ButtonStyle.SECONDARY, compact = true)
                }
            }
            if (state.base != null && state.patch != null) {
                item("match") {
                    Box(Modifier.padding(g).padding(top = Space.s)) {
                        when (state.match) {
                            CrcMatch.MATCH -> Notice(Icons.Rounded.CheckCircle, "Your base game matches what this patch expects.", c.success)
                            CrcMatch.MISMATCH -> Notice(
                                Icons.Rounded.WarningAmber,
                                "This patch was made for a different ROM (CRC32 ${state.patch.sourceCrc32}); yours is ${state.base.crc32}. It's probably another region or revision. Turn off the safety check only if the creator says it's fine.",
                                c.warning,
                            )
                            CrcMatch.UNKNOWN -> Notice(Icons.Rounded.HelpOutline, "${state.patch.format} patches can't check the base game. Make sure it's the version the creator names.", c.accent)
                        }
                    }
                }
                item("options") {
                    GlassGroup(Modifier.padding(g).padding(top = Space.s)) {
                        SwitchRow("Safety check", state.strict, onStrict, subtitle = "Stop if the base game doesn't match")
                        Divider()
                        Spacer(Modifier.height(Space.xs))
                        Text("New game's name", style = RetraType.label, color = c.inkMuted)
                        Spacer(Modifier.height(Space.xxs))
                        RetraTextField(state.outputName, onName, "Name", Modifier.fillMaxWidth())
                        Spacer(Modifier.height(Space.s))
                    }
                }
            }
            if (phase is PatchPhase.Failed) {
                item("error") {
                    Box(Modifier.padding(g).padding(top = Space.s)) { Notice(Icons.Rounded.WarningAmber, phase.message, c.danger) }
                }
            }
            item("apply") {
                RetraButton(
                    "Apply patch", onApply,
                    Modifier.padding(g).padding(top = Space.l).fillMaxWidth(),
                    icon = Icons.Rounded.AutoFixHigh,
                    enabled = state.canApply,
                )
                Text(
                    "Retra never provides commercial ROMs. The Game Library lists fan games whose patches work here.",
                    style = RetraType.caption, color = c.inkMuted,
                    modifier = Modifier.padding(g).padding(top = Space.s),
                )
            }
        }
        GlassSheet(visible = picking, onDismiss = { picking = false }, title = "Pick a base game") {
            if (games.isEmpty()) MochiMessage("No games yet", "Import your ROM first.", mood = MochiMood.SLEEPY)
            games.sortedBy { it.title.lowercase() }.forEach { game ->
                Row(
                    Modifier.fillMaxWidth().squishClickable({ onLibraryBase(game.id); picking = false }, pressed = 0.98f, label = game.title).padding(vertical = Space.xs),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Box(Modifier.width(72.dp).aspectRatio(3f / 2f).clip(Radius.smallShape)) { GameCover(game.coverModel(null), Modifier.fillMaxSize(), showTitle = false) }
                    Spacer(Modifier.width(Space.s))
                    Column(Modifier.weight(1f)) {
                        Text(game.title, style = RetraType.bodyStrong, color = c.ink, maxLines = 1, overflow = TextOverflow.Ellipsis)
                        Text("${game.gameCode} · CRC32 ${game.crc32}", style = RetraType.caption, color = c.inkMuted)
                    }
                }
            }
        }
    }
}

@Composable
private fun StepCard(n: Int, title: String, modifier: Modifier, done: Boolean, content: @Composable () -> Unit) {
    val c = Retra.colors
    GlassSurface(modifier.fillMaxWidth().widthIn(max = 640.dp), shape = Radius.mediumShape) {
        Column(Modifier.padding(Space.m)) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Text("Step $n", style = RetraType.caption, color = if (done) c.success else c.accent)
                if (done) {
                    Spacer(Modifier.width(Space.xxs))
                    androidx.compose.material3.Icon(Icons.Rounded.CheckCircle, "Done", tint = c.success, modifier = Modifier.height(14.dp))
                }
            }
            Text(title, style = RetraType.headline, color = c.ink)
            Spacer(Modifier.height(Space.xs))
            content()
        }
    }
}

package app.retra.ui.player

import android.content.ContentValues
import android.content.Context
import android.graphics.Bitmap
import android.net.Uri
import android.os.Build
import android.provider.MediaStore
import androidx.compose.runtime.Immutable
import androidx.core.content.FileProvider
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import androidx.lifecycle.viewmodel.initializer
import androidx.lifecycle.viewmodel.viewModelFactory
import app.retra.AppContainer
import app.retra.core.PlaytimeTracker
import app.retra.data.Cheat
import app.retra.data.MessageTone
import app.retra.data.SaveRepository
import app.retra.data.Settings
import app.retra.data.StateSlot
import app.retra.emu.AudioOutput
import app.retra.emu.EmuCore
import app.retra.emu.EmulatorSession
import app.retra.emu.NativeEmuCore
import app.retra.engine.LoadResult
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.io.ByteArrayOutputStream

sealed interface PlayerStatus {
    data object Loading : PlayerStatus
    data object Running : PlayerStatus
    data class Failed(val message: String) : PlayerStatus
}

@Immutable
data class PlayerUiState(
    val status: PlayerStatus = PlayerStatus.Loading,
    val title: String = "",
    val coverAsset: String? = null,
    val lastScreenPath: String? = null,
    val menuOpen: Boolean = false,
    val fastForward: Boolean = false,
    val rewinding: Boolean = false,
    val slots: List<StateSlot> = emptyList(),
    val cheats: List<Cheat> = emptyList(),
    val lastCapture: String? = null,
    val exiting: Boolean = false,
)

/** Converts a 240x160 ARGB frame to PNG (optionally nearest-neighbour upscaled). */
fun framePng(pixels: IntArray, scale: Int = 1): ByteArray {
    val bmp = Bitmap.createBitmap(pixels, EmuCore.WIDTH, EmuCore.HEIGHT, Bitmap.Config.ARGB_8888)
    val out = if (scale > 1) Bitmap.createScaledBitmap(bmp, EmuCore.WIDTH * scale, EmuCore.HEIGHT * scale, false) else bmp
    return ByteArrayOutputStream().use { s -> out.compress(Bitmap.CompressFormat.PNG, 100, s); s.toByteArray() }
}

class PlayerViewModel(
    private val container: AppContainer,
    private val gameId: String,
    private val startSlot: Int,
    private val coreFactory: () -> EmuCore = { NativeEmuCore() },
) : ViewModel() {
    private val _state = MutableStateFlow(PlayerUiState())
    val state: StateFlow<PlayerUiState> = _state.asStateFlow()
    val settings: StateFlow<Settings> get() = container.settings.settings

    var session: EmulatorSession? = null
        private set
    private val playtime = PlaytimeTracker()
    private var hostResumed = false
    private var ffToggled = false
    private var ffHeld = false
    private var finished = false
    private val saves: SaveRepository get() = container.saves

    init {
        val game = container.library.game(gameId)
        _state.update {
            it.copy(
                title = game?.title ?: "",
                coverAsset = game?.coverAsset,
                lastScreenPath = saves.lastScreenFile(gameId).takeIf { f -> f.exists() }?.absolutePath,
            )
        }
        viewModelScope.launch { boot() }
        viewModelScope.launch {
            container.settings.settings.collect { applySettings(it) }
        }
    }

    private suspend fun boot() {
        val game = container.library.game(gameId) ?: return fail("This game isn't in your library anymore.")
        val rom = container.library.readRom(gameId) ?: return fail("The game file is missing. Try importing it again.")
        val core = try {
            coreFactory()
        } catch (e: Throwable) {
            return fail("Retra's emulator engine couldn't start on this device (${e.javaClass.simpleName}).")
        }
        val audio = runCatching { AudioOutput() }.getOrNull()
        val s = EmulatorSession(core, audio) { data, first ->
            runCatching { saves.writeBatterySave(gameId, data, backup = first) }
        }
        session = s
        s.start()
        val bios = withContext(Dispatchers.IO) { container.bios.read() }
        when (val r = s.run { it.loadRom(rom, bios) }) {
            is LoadResult.Error -> {
                s.stop()
                session = null
                return fail("This game couldn't start: ${r.message}")
            }
            is LoadResult.Ok -> container.library.recordRomInfo(gameId, r.info.saveType.name, r.info.hasRtc)
        }
        val sav = withContext(Dispatchers.IO) { saves.readBatterySave(gameId) }
        val cheats = withContext(Dispatchers.IO) { container.cheats.cheats(gameId) }
        val st = container.settings.current
        s.run { c ->
            if (sav != null) c.loadBatterySave(sav)
            c.setColorCorrection(st.colorCorrection)
            c.setRtcOffsetSeconds(st.rtcOffsetSeconds)
            val codes = cheats.filter { it.enabled }.map { it.code }
            if (codes.isNotEmpty()) c.setCheats(codes)
            c.consumeSaveDirty() // loading the .sav isn't a new write
        }
        if (startSlot >= 0) {
            val data = withContext(Dispatchers.IO) { saves.readState(gameId, startSlot) }
            val ok = data != null && s.run { it.loadState(data) }
            if (!ok) container.messages.show("That save state couldn't be loaded, so the game started fresh.", MessageTone.ERROR)
        }
        applySettings(st)
        _state.update { it.copy(status = PlayerStatus.Running, cheats = cheats) }
        refreshSlots()
        updateRunning()
        game.title // keep reference for logs
    }

    private fun fail(message: String) {
        _state.update { it.copy(status = PlayerStatus.Failed(message)) }
    }

    private fun applySettings(st: Settings) {
        val s = session ?: return
        s.fastForwardSpeed = st.fastForwardSpeed
        s.fastForwardAudio = st.fastForwardAudio
        s.rewindEnabled = st.rewindEnabled
        s.muted = st.muted || st.volume <= 0f
        // AudioTrack volume is applied by the session's sink on its own thread-safe API.
        audioVolume(st)
    }

    private fun audioVolume(st: Settings) {
        val s = session ?: return
        viewModelScope.launch { runCatching { s.run { } } }
        volumeSink?.setVolume(if (st.muted) 0f else st.volume)
    }

    private val volumeSink get() = (session?.let { sessionAudio })
    private var sessionAudio: app.retra.emu.AudioSink? = null

    // ---- lifecycle ----

    fun onHostResume() {
        hostResumed = true
        updateRunning()
    }

    fun onHostPause() {
        hostResumed = false
        updateRunning()
        commitPlaytime()
    }

    private fun updateRunning() {
        val s = session ?: return
        val run = hostResumed && !_state.value.menuOpen && _state.value.status == PlayerStatus.Running && !finished
        s.isPaused = !run
        if (run) playtime.start() else playtime.pause()
    }

    private fun commitPlaytime() {
        val ms = playtime.drain()
        if (ms > 0) viewModelScope.launch { container.library.recordSession(gameId, ms) }
    }

    // ---- input ----

    fun setTouchKeys(mask: Int) { session?.touchKeys = mask }
    fun setPadKeys(mask: Int) { session?.padKeys = mask }

    fun toggleFastForward() {
        ffToggled = !ffToggled
        syncFf()
    }

    fun holdFastForward(held: Boolean) {
        ffHeld = held
        syncFf()
    }

    private fun syncFf() {
        val on = ffToggled || ffHeld
        session?.fastForward = on
        _state.update { it.copy(fastForward = on) }
    }

    fun setRewinding(on: Boolean) {
        if (on && !container.settings.current.rewindEnabled) {
            container.messages.show("Rewind is off. Turn it on in Settings.")
            return
        }
        session?.rewinding = on
        _state.update { it.copy(rewinding = on) }
    }

    // ---- menu ----

    fun openMenu(open: Boolean) {
        _state.update { it.copy(menuOpen = open, lastCapture = if (open) it.lastCapture else null) }
        if (open) {
            refreshSlots()
            commitPlaytime()
        }
        updateRunning()
    }

    private fun refreshSlots() = viewModelScope.launch {
        val slots = withContext(Dispatchers.IO) { saves.slots(gameId) }
        _state.update { it.copy(slots = slots) }
    }

    fun saveState(slot: Int) = viewModelScope.launch {
        val s = session ?: return@launch
        val (data, frame) = s.run { it.saveState() to s.snapshotFrame() }
        withContext(Dispatchers.IO) { saves.writeState(gameId, slot, data, framePng(frame)) }
        refreshSlots()
        container.messages.show(if (slot == 0) "Saved to the auto slot" else "Saved to slot $slot", MessageTone.SUCCESS)
    }

    fun loadState(slot: Int) = viewModelScope.launch {
        val s = session ?: return@launch
        val data = withContext(Dispatchers.IO) { saves.readState(gameId, slot) } ?: return@launch
        val ok = s.run { it.loadState(data) }
        s.clearRewind()
        if (ok) {
            container.messages.show(if (slot == 0) "Loaded the auto save" else "Loaded slot $slot", MessageTone.SUCCESS)
            openMenu(false)
        } else {
            container.messages.show("That state is from another version of the game and can't be loaded.", MessageTone.ERROR)
        }
    }

    fun reset() = viewModelScope.launch {
        val s = session ?: return@launch
        s.run { it.reset() }
        s.clearRewind()
        openMenu(false)
    }

    fun setCheats(list: List<Cheat>) = viewModelScope.launch {
        withContext(Dispatchers.IO) { container.cheats.save(gameId, list) }
        _state.update { it.copy(cheats = list) }
        val s = session ?: return@launch
        val codes = list.filter { it.enabled }.map { it.code }
        val accepted = s.run { it.setCheats(codes) }
        val lines = codes.sumOf { it.lines().size }
        if (lines > 0 && accepted < lines) {
            container.messages.show("$accepted of $lines code lines work with this engine", MessageTone.INFO)
        }
    }

    fun screenshot(context: Context) = viewModelScope.launch {
        val s = session ?: return@launch
        val frame = s.run { s.snapshotFrame() }
        val png = withContext(Dispatchers.Default) { framePng(frame, scale = 3) }
        val file = saves.newCaptureFile(gameId)
        withContext(Dispatchers.IO) {
            app.retra.core.AtomicFiles.write(file, png)
            if (Build.VERSION.SDK_INT >= 29) runCatching { saveToGallery(context, png, file.name) }
        }
        _state.update { it.copy(lastCapture = file.absolutePath) }
        container.messages.show(if (Build.VERSION.SDK_INT >= 29) "Screenshot saved to Pictures/Retra" else "Screenshot saved", MessageTone.SUCCESS)
    }

    private fun saveToGallery(context: Context, png: ByteArray, name: String) {
        val values = ContentValues().apply {
            put(MediaStore.Images.Media.DISPLAY_NAME, name)
            put(MediaStore.Images.Media.MIME_TYPE, "image/png")
            put(MediaStore.Images.Media.RELATIVE_PATH, "Pictures/Retra")
        }
        val uri = context.contentResolver.insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI, values) ?: return
        context.contentResolver.openOutputStream(uri)?.use { it.write(png) }
    }

    fun shareUri(context: Context, path: String): Uri =
        FileProvider.getUriForFile(context, "${context.packageName}.files", java.io.File(path))

    /** Saves the auto state + last-session screenshot and stops the session. */
    suspend fun finish() {
        if (finished) return
        finished = true
        _state.update { it.copy(exiting = true) }
        val s = session ?: return
        playtime.pause()
        if (_state.value.status == PlayerStatus.Running && s.isRunning) {
            runCatching {
                s.isPaused = true
                val (data, frame) = s.run { it.saveState() to s.snapshotFrame() }
                withContext(Dispatchers.IO) {
                    val png = framePng(frame)
                    saves.writeState(gameId, SaveRepository.AUTO_SLOT, data, png)
                    saves.writeLastScreen(gameId, framePng(frame, 2))
                }
                s.flushBatterySave()
            }
        }
        withContext(Dispatchers.IO) { s.stop() }
        session = null
        container.library.recordSession(gameId, playtime.drain())
    }

    override fun onCleared() {
        if (!finished) container.scope.launch { finish() }
    }

    companion object {
        fun factory(c: AppContainer, id: String, slot: Int) = viewModelFactory { initializer { PlayerViewModel(c, id, slot) } }
    }
}

