@Stable
class SheetEntry {
    var visible by mutableStateOf(false)
    var title by mutableStateOf<String?>(null)
    var scrollable by mutableStateOf(true)
    var onDismiss by mutableStateOf({})
    var content by mutableStateOf<@Composable ColumnScope.() -> Unit>({})
