/**
 * Sheets are drawn at the root, above the dock and outside the blur source, so they can blur the
 * screen behind them. Screens just call [GlassSheet]; without a host (previews) it draws inline.
 */
class SheetHost {
    val entries = mutableStateListOf<SheetEntry>()
    val anyVisible: Boolean get() = entries.any { it.visible }
}

val LocalSheetHost = staticCompositionLocalOf<SheetHost?> { null }

@Composable
fun GlassSheet(
    visible: Boolean,
    onDismiss: () -> Unit,
    modifier: Modifier = Modifier,
    title: String? = null,
    scrollable: Boolean = true,
    content: @Composable ColumnScope.() -> Unit,
) {
    val host = LocalSheetHost.current
    if (host == null) {
        GlassSheetSurface(visible, onDismiss, modifier, title, scrollable, content)
        return
    }
    val entry = remember { SheetEntry() }
    entry.visible = visible
    entry.title = title
    entry.scrollable = scrollable
    entry.onDismiss = onDismiss
    entry.content = content
    DisposableEffect(host, entry) {
        host.entries += entry
        onDispose { host.entries -= entry }
    }
}

/** Draws every registered sheet; place above the dock with the root HazeState provided. */
@Composable
fun SheetLayer(host: SheetHost) {
    host.entries.forEach { e ->
        key(e) { GlassSheetSurface(e.visible, e.onDismiss, Modifier, e.title, e.scrollable, e.content) }
    }
}

